-- Seed 210 practice questions and four 70-question combined mocks.
-- The pre-existing 50-question sets remain available during deployment.
INSERT INTO public.kpp_questions (
  id, category, set_id, order_index, question_en, question_ms, options_en, options_ms,
  correct_index, explanation_en, explanation_ms, image_url, source_url
) VALUES
  ('a3cc16dc-2d79-46cf-b49d-8938e893262a'::uuid, 'road-signs', 'quiz-a-1', 1, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Gated rail crossing","Divided road begins","Narrow bridge ahead","Side road to the left"]'::jsonb, '["Lintasan kereta api berpagar","Jalan terbahagi dua bermula","Jambatan sempit di hadapan","Simpang jalan di sebelah kiri"]'::jsonb, 0, 'Gated rail crossing. Stop and wait for the gate to open before proceeding carefully.', 'Lintasan kereta api berpagar. Berhenti dan tunggu pagar dibuka sebelum meneruskan perjalanan dengan berhati-hati.', '/signs/e846f69e41c180a7.svg', 'KPP General PDF page 56'),
  ('618f6ddc-44b0-41a6-bb5d-953abc1f9115'::uuid, 'road-signs', 'quiz-a-1', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Designated U-turn","One-way traffic","Turn right only","Keep right"]'::jsonb, '["Tempat pusingan U","Trafik sehala","Belok kanan sahaja","Ikut sebelah kanan"]'::jsonb, 0, 'The blue sign marks a place provided for vehicles to make a U-turn.', 'Papan tanda biru ini menandakan tempat yang disediakan untuk kenderaan membuat pusingan U.', '/signs/8956fe8a103938b3.svg', 'KPP General PDF page 69'),
  ('ee618bef-ff90-55c9-b380-fb17b9e98690'::uuid, 'road-signs', 'quiz-a-1', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Side road to the left","T-junction ahead","Four-way intersection","Y-junction ahead"]'::jsonb, '["Simpang jalan di sebelah kiri","Persimpangan T di hadapan","Persimpangan empat hala","Persimpangan Y di hadapan"]'::jsonb, 2, 'This sign means four-way intersection. Look for vehicles approaching from both sides before proceeding.', 'Papan tanda ini bermaksud persimpangan empat hala. Perhatikan kenderaan yang datang dari kedua-dua sisi sebelum meneruskan perjalanan.', '/signs/4a3491aff2749365.svg', 'KPP General PDF page 40'),
  ('e50fcb14-3681-42be-afd9-9687dcf58fa1'::uuid, 'road-signs', 'quiz-a-1', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No sounding the horn","Stop at the junction","No motorcycle entry","No vehicle entry"]'::jsonb, '["Dilarang membunyikan hon","Berhenti di persimpangan","Motosikal dilarang masuk","Kenderaan dilarang masuk"]'::jsonb, 0, 'The crossed-out horn means the horn must not be used in this area.', 'Simbol hon yang dipalang bermaksud hon tidak boleh dibunyikan di kawasan ini.', '/signs/ce55b86645694f5d.svg', 'KPP General PDF page 57'),
  ('1cb10e5f-d70c-449e-bce3-b3125bd912b0'::uuid, 'road-signs', 'quiz-a-1', 5, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No vehicle entry","No motorcycle entry","No sounding the horn","Stop at the junction"]'::jsonb, '["Kenderaan dilarang masuk","Motosikal dilarang masuk","Dilarang membunyikan hon","Berhenti di persimpangan"]'::jsonb, 0, 'No vehicle entry. Plan your route so you can obey this restriction.', 'Kenderaan dilarang masuk. Rancang laluan supaya anda dapat mematuhi larangan ini.', '/signs/9a316a4baac9f49a.svg', 'KPP General PDF page 57'),
  ('10e11267-6610-4f86-bd12-24c175d08f41'::uuid, 'road-signs', 'quiz-a-1', 6, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No left turn","No right turn","No parking","No vehicle entry"]'::jsonb, '["Dilarang membelok ke kiri","Dilarang membelok ke kanan","Dilarang meletak kenderaan","Kenderaan dilarang masuk"]'::jsonb, 0, 'No left turn. Plan your route so you can obey this restriction.', 'Dilarang membelok ke kiri. Rancang laluan supaya anda dapat mematuhi larangan ini.', '/signs/ef495735d6870ce2.svg', 'KPP General PDF page 57'),
  ('129c610b-6725-4d9c-b257-e2e40f2f44a5'::uuid, 'road-signs', 'quiz-a-1', 7, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No right turn","No left turn","No parking","No vehicle entry"]'::jsonb, '["Dilarang membelok ke kanan","Dilarang membelok ke kiri","Dilarang meletak kenderaan","Kenderaan dilarang masuk"]'::jsonb, 0, 'No right turn. Use another route if you need to turn right.', 'Dilarang membelok ke kanan. Gunakan laluan lain jika anda perlu membelok ke kanan.', '/signs/2eee15e55fa0ef48.svg', 'KPP General PDF page 57'),
  ('208e1662-84e8-43bd-90dc-8beaa8dde1bd'::uuid, 'road-signs', 'quiz-a-1', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No U-turn","No parking","No left turn","No right turn"]'::jsonb, '["Dilarang membuat pusingan U","Dilarang meletak kenderaan","Dilarang membelok ke kiri","Dilarang membelok ke kanan"]'::jsonb, 0, 'No U-turn. Plan your route so you can obey this restriction.', 'Dilarang membuat pusingan U. Rancang laluan supaya anda dapat mematuhi larangan ini.', '/signs/a299aef5bccc0fca.svg', 'KPP General PDF page 58'),
  ('e95b8085-31e9-57c4-b725-860b5b44eb29'::uuid, 'road-signs', 'quiz-a-1', 9, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Side road to the left","Side road to the right","Staggered junction ahead","Angled branch to the left"]'::jsonb, '["Simpang jalan di sebelah kiri","Simpang jalan di sebelah kanan","Persimpangan beranjak di hadapan","Simpang serong di sebelah kiri"]'::jsonb, 0, 'This sign means side road to the left.', 'Papan tanda ini bermaksud simpang jalan di sebelah kiri.', '/signs/e22292f492beec26.svg', 'KPP General PDF page 42'),
  ('15c5fc28-0956-5e95-8415-75796a5452fd'::uuid, 'road-signs', 'quiz-a-1', 10, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Side road to the left","Side road to the right","Staggered junction ahead","Angled branch to the left"]'::jsonb, '["Simpang jalan di sebelah kiri","Simpang jalan di sebelah kanan","Persimpangan beranjak di hadapan","Simpang serong di sebelah kiri"]'::jsonb, 1, 'This sign means side road to the right.', 'Papan tanda ini bermaksud simpang jalan di sebelah kanan.', '/signs/12e8b0d727c5bdf1.svg', 'KPP General PDF page 42'),
  ('6de9f48d-76e8-57e6-9da5-f5c31344fdb5'::uuid, 'road-signs', 'quiz-a-1', 11, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Y-junction ahead","Four-way intersection","T-junction ahead","Roundabout ahead"]'::jsonb, '["Persimpangan Y di hadapan","Persimpangan empat hala","Persimpangan T di hadapan","Bulatan di hadapan"]'::jsonb, 2, 'This sign means t-junction ahead. Slow down, signal your turn and stop at the junction before proceeding safely.', 'Papan tanda ini bermaksud persimpangan T di hadapan. Perlahankan kenderaan, beri isyarat membelok dan berhenti di persimpangan sebelum meneruskan perjalanan dengan selamat.', '/signs/e3ccd470b3c6bc8e.svg', 'KPP General PDF page 42'),
  ('ccf1c02b-e28a-4b29-b24a-d14d1138c37a'::uuid, 'road-signs', 'quiz-a-1', 12, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No motorcycle entry","No sounding the horn","Stop at the junction","No vehicle entry"]'::jsonb, '["Motosikal dilarang masuk","Dilarang membunyikan hon","Berhenti di persimpangan","Kenderaan dilarang masuk"]'::jsonb, 0, 'No motorcycle entry. Choose an alternative route if riding a motorcycle.', 'Motosikal dilarang masuk. Pilih laluan lain jika menunggang motosikal.', '/signs/efd2fb23c0d0e1ac.svg', 'KPP General PDF page 58'),
  ('11a7d793-f8d2-5188-acd6-e158ecdb8de1'::uuid, 'road-signs', 'quiz-a-1', 13, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass either side of the island","Limited clearance ahead","Obstacle at the divider","Risk of falling rocks"]'::jsonb, '["Lalui pulau dari mana-mana sisi","Kelegaan laluan terhad di hadapan","Halangan di pembahagi jalan","Risiko runtuhan batu"]'::jsonb, 0, 'This sign means pass either side of the island. Choose a lane that leads where you intend to go and keep within it.', 'Papan tanda ini bermaksud lalui pulau dari mana-mana sisi. Pilih lorong yang menuju ke arah destinasi dan kekal dalam lorong itu.', '/signs/322e269754adeff6.svg', 'KPP General PDF page 44'),
  ('e353ce3a-0dd5-4a7f-9a8a-0b387ea23a69'::uuid, 'road-signs', 'quiz-a-1', 14, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No parking","No U-turn","No left turn","No right turn"]'::jsonb, '["Dilarang meletak kenderaan","Dilarang membuat pusingan U","Dilarang membelok ke kiri","Dilarang membelok ke kanan"]'::jsonb, 0, 'Parking is prohibited where this sign applies.', 'Anda tidak boleh meletakkan kenderaan di kawasan yang tertakluk pada tanda ini.', '/signs/fbd415b24ab21b44.svg', 'KPP General PDF page 58'),
  ('728349e8-57df-493e-ad13-43d1d80bd253'::uuid, 'road-signs', 'quiz-a-1', 15, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No stopping","No overtaking","No left turn","No parking"]'::jsonb, '["Dilarang berhenti","Dilarang memotong","Dilarang membelok ke kiri","Dilarang meletak kenderaan"]'::jsonb, 0, 'The crossed lines mean you cannot stop in the signed area.', 'Garisan bersilang bermaksud anda tidak boleh berhenti di kawasan bertanda ini.', '/signs/ecd3d648f3d4a187.svg', 'KPP General PDF page 59'),
  ('ca6cba6e-03ca-4d9a-9873-e8765bc948d9'::uuid, 'road-signs', 'quiz-a-2', 1, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Stop at the junction","No sounding the horn","No motorcycle entry","No vehicle entry"]'::jsonb, '["Berhenti di persimpangan","Dilarang membunyikan hon","Motosikal dilarang masuk","Kenderaan dilarang masuk"]'::jsonb, 0, 'Stop at the junction. Stop before the line, check both directions and continue only when safe.', 'Berhenti di persimpangan. Berhenti sebelum garisan, periksa kedua-dua arah dan teruskan hanya apabila selamat.', '/signs/8cd2c7d525ad7c21.svg', 'KPP General PDF page 59'),
  ('0144363e-2ef2-5472-a74b-783bc33f4774'::uuid, 'road-signs', 'quiz-a-2', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Sharp left bend","Sharp right bend","Double bend, left first","Direction of a sharp bend"]'::jsonb, '["Selekoh tajam ke kiri","Selekoh tajam ke kanan","Dua selekoh, mula ke kiri","Arah selekoh yang tajam"]'::jsonb, 0, 'This sign means sharp left bend.', 'Papan tanda ini bermaksud selekoh tajam ke kiri.', '/signs/194637442da016e5.svg', 'KPP General PDF page 47'),
  ('a579b6a5-f867-53cf-a189-85d923173482'::uuid, 'road-signs', 'quiz-a-2', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Sharp left bend","Sharp right bend","Double bend, left first","Direction of a sharp bend"]'::jsonb, '["Selekoh tajam ke kiri","Selekoh tajam ke kanan","Dua selekoh, mula ke kiri","Arah selekoh yang tajam"]'::jsonb, 1, 'This sign means sharp right bend.', 'Papan tanda ini bermaksud selekoh tajam ke kanan.', '/signs/8c4124b32afd3704.svg', 'KPP General PDF page 47'),
  ('9e23479a-a545-555e-901a-c7912696a0b2'::uuid, 'road-signs', 'quiz-a-2', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Double bend, left first","Double bend, right first","Direction of a sharp bend","Sharp right bend"]'::jsonb, '["Dua selekoh, mula ke kiri","Dua selekoh, mula ke kanan","Arah selekoh yang tajam","Selekoh tajam ke kanan"]'::jsonb, 2, 'This sign means direction of a sharp bend.', 'Papan tanda ini bermaksud arah selekoh yang tajam.', '/signs/b716cb9e685088a5.svg', 'KPP General PDF page 47'),
  ('2abde0de-eb04-4a26-a78c-f1481f52ea8f'::uuid, 'road-signs', 'quiz-a-2', 5, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Stop for children crossing","End of the posted speed limit","No entry over 8 tonnes","No sounding the horn"]'::jsonb, '["Berhenti untuk kanak-kanak melintas","Had laju yang dipaparkan tamat","Kenderaan melebihi 8 tan dilarang masuk","Dilarang membunyikan hon"]'::jsonb, 0, 'Stop for children crossing. Wait for children to clear the crossing before moving off.', 'Berhenti untuk kanak-kanak melintas. Tunggu sehingga kanak-kanak selesai melintas sebelum bergerak.', '/signs/e22b17f982a5ee46.svg', 'KPP General PDF page 59'),
  ('87c01b4c-a79f-4ab8-adb8-77b40efab05a'::uuid, 'road-signs', 'quiz-a-2', 6, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["End of the posted speed limit","Stop for children crossing","No sounding the horn","Stop at the junction"]'::jsonb, '["Had laju yang dipaparkan tamat","Berhenti untuk kanak-kanak melintas","Dilarang membunyikan hon","Berhenti di persimpangan"]'::jsonb, 0, 'End of the posted speed limit. Follow the next applicable speed limit.', 'Had laju yang dipaparkan tamat. Patuhi had laju seterusnya yang berkuat kuasa.', '/signs/63b26ca2bbf8dc2b.png', 'KPP General PDF page 60'),
  ('de032fdf-b2ff-5583-ac25-d16ea2e3e58c'::uuid, 'road-signs', 'quiz-a-2', 7, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Divided road begins","Divided road ends","Extra uphill lane","Steep uphill stretch"]'::jsonb, '["Jalan terbahagi dua bermula","Jalan terbahagi dua tamat","Lorong tambahan untuk mendaki","Jalan mendaki dengan curam"]'::jsonb, 1, 'This sign means divided road ends. Watch for vehicles coming the other way once the divider ends.', 'Papan tanda ini bermaksud jalan terbahagi dua tamat. Awasi kenderaan dari arah bertentangan selepas pembahagi jalan tamat.', '/signs/b12139221efc15b6.svg', 'KPP General PDF page 48'),
  ('6b6055c3-9599-5d1d-b5db-f5cdd94973b8'::uuid, 'road-signs', 'quiz-a-2', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Extra downhill lane","Steep uphill stretch","Divided road begins","Divided road ends"]'::jsonb, '["Lorong tambahan untuk menurun","Jalan mendaki dengan curam","Jalan terbahagi dua bermula","Jalan terbahagi dua tamat"]'::jsonb, 2, 'This sign means divided road begins. Stay on the correct side as the divider separates the two streams of traffic.', 'Papan tanda ini bermaksud jalan terbahagi dua bermula. Kekal di sebelah yang betul apabila pembahagi jalan memisahkan dua aliran trafik.', '/signs/788d475c2d05336c.svg', 'KPP General PDF page 48'),
  ('1ed2bbf8-e87f-5705-80d8-05b12400cc34'::uuid, 'road-signs', 'quiz-a-2', 9, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["T-junction ahead","Y-junction ahead","Four-way intersection","Roundabout ahead"]'::jsonb, '["Persimpangan T di hadapan","Persimpangan Y di hadapan","Persimpangan empat hala","Bulatan di hadapan"]'::jsonb, 3, 'This sign means roundabout ahead. Pick the appropriate approach lane and yield to traffic already in the roundabout.', 'Papan tanda ini bermaksud bulatan di hadapan. Pilih lorong masuk yang sesuai dan beri laluan kepada kenderaan yang sudah berada dalam bulatan.', '/signs/d26a8ccc75c5a905.svg', 'KPP General PDF page 48'),
  ('0ed3f342-a506-5b15-b1de-ba8c951f2b6a'::uuid, 'road-signs', 'quiz-a-2', 10, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Two-way traffic ahead","Road narrows on the left","Extra downhill lane","Road narrows on the right"]'::jsonb, '["Lalu lintas dua hala di hadapan","Jalan menyempit di sebelah kiri","Lorong tambahan untuk menurun","Jalan menyempit di sebelah kanan"]'::jsonb, 0, 'This sign means two-way traffic ahead. Expect oncoming vehicles on the same road and check carefully before overtaking.', 'Papan tanda ini bermaksud lalu lintas dua hala di hadapan. Jangkakan kenderaan dari arah bertentangan di jalan yang sama dan periksa keadaan sebelum memotong.', '/signs/ea082fc0b4c65733.svg', 'KPP General PDF page 49'),
  ('6a33c973-7421-44f3-80f3-6f5b01da7697'::uuid, 'road-signs', 'quiz-a-2', 11, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No entry over 8 tonnes","Stop for children crossing","End of the posted speed limit","No sounding the horn"]'::jsonb, '["Kenderaan melebihi 8 tan dilarang masuk","Berhenti untuk kanak-kanak melintas","Had laju yang dipaparkan tamat","Dilarang membunyikan hon"]'::jsonb, 0, 'No entry over 8 tonnes. Use another route if your vehicle exceeds the weight shown.', 'Kenderaan melebihi 8 tan dilarang masuk. Gunakan laluan lain jika kenderaan melebihi berat yang dipaparkan.', '/signs/ed63604f3712ca41.svg', 'KPP General PDF page 62'),
  ('ae84be68-cf30-4366-a148-68fd57ee5eef'::uuid, 'road-signs', 'quiz-a-2', 12, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["One-way traffic","Turn left only","Turn right only","Pass on the left"]'::jsonb, '["Lalu lintas sehala","Belok ke kiri sahaja","Belok ke kanan sahaja","Lalu di sebelah kiri"]'::jsonb, 0, 'One-way traffic. Follow the direction of the arrow.', 'Lalu lintas sehala. Ikut arah anak panah.', '/signs/396a58e1a26f5557.svg', 'KPP General PDF page 63'),
  ('0dfad1d5-7682-5219-9732-8ba1bd5e64ec'::uuid, 'road-signs', 'quiz-a-2', 13, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on the right","Road narrows on the left","Two-way traffic ahead","Road narrows on both sides"]'::jsonb, '["Jalan menyempit di sebelah kanan","Jalan menyempit di sebelah kiri","Lalu lintas dua hala di hadapan","Jalan menyempit di kedua-dua sisi"]'::jsonb, 3, 'This sign means road narrows on both sides.', 'Papan tanda ini bermaksud jalan menyempit di kedua-dua sisi.', '/signs/ce68f8896451a2c9.svg', 'KPP General PDF page 50'),
  ('039bc376-de68-554e-8e23-9bfaf8c23138'::uuid, 'road-signs', 'quiz-a-2', 14, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on the left","Road narrows on the right","Two-way traffic ahead","Road narrows on both sides"]'::jsonb, '["Jalan menyempit di sebelah kiri","Jalan menyempit di sebelah kanan","Lalu lintas dua hala di hadapan","Jalan menyempit di kedua-dua sisi"]'::jsonb, 0, 'This sign means road narrows on the left.', 'Papan tanda ini bermaksud jalan menyempit di sebelah kiri.', '/signs/2be93e13645351ef.svg', 'KPP General PDF page 50'),
  ('801072d7-872d-5134-9e43-a650da387398'::uuid, 'road-signs', 'quiz-a-2', 15, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on both sides","Road narrows on the right","Road narrows on the left","Two-way traffic ahead"]'::jsonb, '["Jalan menyempit di kedua-dua sisi","Jalan menyempit di sebelah kanan","Jalan menyempit di sebelah kiri","Lalu lintas dua hala di hadapan"]'::jsonb, 1, 'This sign means road narrows on the right.', 'Papan tanda ini bermaksud jalan menyempit di sebelah kanan.', '/signs/e08ca85fb4d9816f.svg', 'KPP General PDF page 50'),
  ('086c2471-8b72-5702-b170-8cdcb30b6d2c'::uuid, 'road-signs', 'quiz-a-3', 1, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Divided road begins","Steep downhill stretch","Steep uphill stretch","Divided road ends"]'::jsonb, '["Jalan terbahagi dua bermula","Jalan menurun dengan curam","Jalan mendaki dengan curam","Jalan terbahagi dua tamat"]'::jsonb, 2, 'This sign means steep uphill stretch. Select a lower gear to get the power needed to climb.', 'Papan tanda ini bermaksud jalan mendaki dengan curam. Gunakan gear rendah untuk mendapatkan kuasa yang diperlukan semasa mendaki.', '/signs/fa01479a3e275ae3.svg', 'KPP General PDF page 50'),
  ('0bfcb0c3-b39a-57bc-9bf0-f0047509c9c5'::uuid, 'road-signs', 'quiz-a-3', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Steep uphill stretch","Divided road begins","Divided road ends","Steep downhill stretch"]'::jsonb, '["Jalan mendaki dengan curam","Jalan terbahagi dua bermula","Jalan terbahagi dua tamat","Jalan menurun dengan curam"]'::jsonb, 3, 'This sign means steep downhill stretch. Select a lower gear to help control your speed on the descent.', 'Papan tanda ini bermaksud jalan menurun dengan curam. Gunakan gear rendah untuk membantu mengawal kelajuan semasa menurun.', '/signs/eb9c555ec03577f6.svg', 'KPP General PDF page 50'),
  ('e635661c-ba6a-5315-9691-ab6905c3e516'::uuid, 'road-signs', 'quiz-a-3', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Narrow bridge ahead","Uneven road surface","Road hump ahead","Slippery road surface"]'::jsonb, '["Jambatan sempit di hadapan","Permukaan jalan tidak rata","Bonggol jalan di hadapan","Permukaan jalan licin"]'::jsonb, 0, 'This sign means narrow bridge ahead. Slow down and give way if a vehicle coming the other way is closer to the bridge.', 'Papan tanda ini bermaksud jambatan sempit di hadapan. Perlahankan kenderaan dan beri laluan jika kenderaan dari arah bertentangan lebih hampir dengan jambatan.', '/signs/d1e9a6d6aab128b3.svg', 'KPP General PDF page 51'),
  ('b871c12d-17a8-5be3-aa85-59b3a74e7ff9'::uuid, 'road-signs', 'quiz-a-3', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Uneven road surface","Slippery road surface","Soft road shoulder","Narrow bridge ahead"]'::jsonb, '["Permukaan jalan tidak rata","Permukaan jalan licin","Bahu jalan lembut","Jambatan sempit di hadapan"]'::jsonb, 1, 'This sign means slippery road surface. Slow smoothly, avoid hard braking and leave a safe gap.', 'Papan tanda ini bermaksud permukaan jalan licin. Perlahankan kenderaan dengan lancar, elakkan brek mengejut dan kekalkan jarak selamat.', '/signs/9702f462c37241a4.svg', 'KPP General PDF page 51'),
  ('ba0d0d24-3b0e-4463-96b8-ef7cd4358b3f'::uuid, 'road-signs', 'quiz-a-3', 5, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Turn left only","Turn right only","Pass on the left","One-way traffic"]'::jsonb, '["Belok ke kiri sahaja","Belok ke kanan sahaja","Lalu di sebelah kiri","Lalu lintas sehala"]'::jsonb, 0, 'Turn left only. Follow the required direction.', 'Belok ke kiri sahaja. Ikut arah yang diwajibkan.', '/signs/57708bf453b84a72.svg', 'KPP General PDF page 63'),
  ('edbd84be-577e-4a9f-af23-2d7086426c88'::uuid, 'road-signs', 'quiz-a-3', 6, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Turn right only","Turn left only","Pass on the left","Pass on the right"]'::jsonb, '["Belok ke kanan sahaja","Belok ke kiri sahaja","Lalu di sebelah kiri","Lalu di sebelah kanan"]'::jsonb, 0, 'Turn right only. Follow the required direction.', 'Belok ke kanan sahaja. Ikut arah yang diwajibkan.', '/signs/cbae8fe06ab6d6f0.svg', 'KPP General PDF page 63'),
  ('5b0ce5f6-6dae-5e84-ad18-b9244a674278'::uuid, 'road-signs', 'quiz-a-3', 7, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Stop sign ahead","Traffic lights ahead","Give-way sign ahead","Speed limit zone ahead"]'::jsonb, '["Tanda berhenti di hadapan","Lampu isyarat di hadapan","Tanda beri laluan di hadapan","Zon had laju di hadapan"]'::jsonb, 0, 'This sign means stop sign ahead. Slow down early and be ready to come to a complete stop at the actual stop sign.', 'Papan tanda ini bermaksud tanda berhenti di hadapan. Perlahankan kenderaan awal dan bersedia untuk berhenti sepenuhnya di tanda berhenti sebenar.', '/signs/add368369889404d.svg', 'KPP General PDF page 52'),
  ('0b5d54c2-1a23-5262-bc01-bf0523ebb6ce'::uuid, 'road-signs', 'quiz-a-3', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Risk of falling rocks","Other hazard ahead","Obstacle at the divider","Limited clearance ahead"]'::jsonb, '["Risiko runtuhan batu","Bahaya lain di hadapan","Halangan di pembahagi jalan","Kelegaan laluan terhad di hadapan"]'::jsonb, 1, 'This sign means other hazard ahead.', 'Papan tanda ini bermaksud bahaya lain di hadapan.', '/signs/3f13bbd2ffe5c466.svg', 'KPP General PDF page 52'),
  ('5f986734-65ce-42a3-9285-92729c848da9'::uuid, 'road-signs', 'quiz-a-3', 9, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Compulsory right turn","Lane for motorcycles","Pass on either side","Lane for bicycles"]'::jsonb, '["Wajib belok ke kanan","Lorong untuk motosikal","Lalu di mana-mana sisi","Lorong untuk basikal"]'::jsonb, 0, 'Compulsory right turn. Follow the required direction.', 'Wajib belok ke kanan. Ikut arah yang diwajibkan.', '/signs/c70027b1fa8b10e9.svg', 'KPP General PDF page 63'),
  ('bbec7bfb-a098-56dd-ad8f-f5138bc008e9'::uuid, 'road-signs', 'quiz-a-3', 10, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Other hazard ahead","Obstacle at the divider","Limited clearance ahead","Risk of falling rocks"]'::jsonb, '["Bahaya lain di hadapan","Halangan di pembahagi jalan","Kelegaan laluan terhad di hadapan","Risiko runtuhan batu"]'::jsonb, 3, 'This sign means risk of falling rocks. Watch the road for fallen material before continuing.', 'Papan tanda ini bermaksud risiko runtuhan batu. Perhatikan bahan runtuhan di jalan sebelum meneruskan perjalanan.', '/signs/adc5145404e740b4.svg', 'KPP General PDF page 53'),
  ('0bf7871f-0e8f-4da5-817c-e78fab9882a2'::uuid, 'road-signs', 'quiz-a-3', 11, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on the left","Lane for bicycles","Turn left only","Turn right only"]'::jsonb, '["Lalu di sebelah kiri","Lorong untuk basikal","Belok ke kiri sahaja","Belok ke kanan sahaja"]'::jsonb, 0, 'Pass on the left. Follow the instruction shown on the sign.', 'Lalu di sebelah kiri. Patuhi arahan pada papan tanda.', '/signs/24dc89f9e7127cca.svg', 'KPP General PDF page 64'),
  ('145224aa-31e9-4e1b-ad9a-ed66bb65549c'::uuid, 'road-signs', 'quiz-a-3', 12, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on the right","Lane for bicycles","Turn right only","Pass on the left"]'::jsonb, '["Lalu di sebelah kanan","Lorong untuk basikal","Belok ke kanan sahaja","Lalu di sebelah kiri"]'::jsonb, 0, 'Pass on the right. Follow the instruction shown on the sign.', 'Lalu di sebelah kanan. Patuhi arahan pada papan tanda.', '/signs/a50c8dd8a202a25e.svg', 'KPP General PDF page 64'),
  ('cfa2ddaa-9499-42f0-a468-bb567b23d6b7'::uuid, 'road-signs', 'quiz-a-3', 13, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on either side","Lane for motorcycles","Pass on the right","Compulsory right turn"]'::jsonb, '["Lalu di mana-mana sisi","Lorong untuk motosikal","Lalu di sebelah kanan","Wajib belok ke kanan"]'::jsonb, 0, 'Pass on either side. Follow the instruction shown on the sign.', 'Lalu di mana-mana sisi. Patuhi arahan pada papan tanda.', '/signs/6103dff69316bf86.svg', 'KPP General PDF page 64'),
  ('55eb8233-72e9-5c46-a063-d9ff5be486fa'::uuid, 'road-signs', 'quiz-a-3', 14, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pedestrian crossing ahead","Schoolchildren may cross","Playground nearby","Blind pedestrians may cross"]'::jsonb, '["Lintasan pejalan kaki di hadapan","Murid sekolah mungkin melintas","Taman permainan berhampiran","Orang buta mungkin melintas"]'::jsonb, 3, 'This sign means blind pedestrians may cross. Slow down, give people time to cross and avoid sounding the horn.', 'Papan tanda ini bermaksud orang buta mungkin melintas. Perlahankan kenderaan, beri masa untuk orang melintas dan elakkan membunyikan hon.', '/signs/f986766e1fca4c02.svg', 'KPP General PDF page 54'),
  ('58035b3b-6f91-4722-80c5-5b9497b29ae5'::uuid, 'road-signs', 'quiz-a-3', 15, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for motorcycles","Pass on either side","Compulsory right turn","Pass on the right"]'::jsonb, '["Lorong untuk motosikal","Lalu di mana-mana sisi","Wajib belok ke kanan","Lalu di sebelah kanan"]'::jsonb, 0, 'Lane for motorcycles. Follow the instruction shown on the sign.', 'Lorong untuk motosikal. Patuhi arahan pada papan tanda.', '/signs/e0389a069e72ed52.png', 'KPP General PDF page 65'),
  ('3c07c163-fe3e-5098-9651-951a404e55e4'::uuid, 'traffic-rules', 'quiz-b-1', 1, 'How do you calculate the full distance a moving car needs to stop?', 'Bagaimanakah anda mengira jumlah jarak yang diperlukan untuk memberhentikan kereta yang bergerak?', '["Add reaction and braking distances","Subtract reaction from braking distance","Double the braking distance","Average reaction and braking distances"]'::jsonb, '["Tambah jarak reaksi dan jarak membrek","Tolak jarak reaksi daripada jarak membrek","Gandakan jarak membrek","Kira purata jarak reaksi dan jarak membrek"]'::jsonb, 0, 'The car travels while you react and continues moving after you press the brake. Add both distances.', 'Kereta bergerak semasa anda bertindak balas dan terus bergerak selepas anda menekan brek. Tambahkan kedua-dua jarak itu.', NULL, 'KPP Kelas D Automatik, PDF page 264'),
  ('c892bc41-44fe-54e5-9ade-bf2718126cda'::uuid, 'traffic-rules', 'quiz-b-1', 2, 'A driver spots an obstacle and moves a foot towards the brake. What is this stage called?', 'Pemandu nampak halangan dan menggerakkan kaki ke arah pedal brek. Apakah nama fasa ini?', '["Braking","Reaction","Acceleration","Coasting"]'::jsonb, '["Membrek","Reaksi","Pecutan","Meluncur"]'::jsonb, 1, 'Reaction distance begins when you notice the hazard and ends when you apply the brakes.', 'Jarak reaksi bermula apabila anda menyedari bahaya dan berakhir apabila anda menekan brek.', NULL, 'KPP Kelas D Automatik, PDF page 264'),
  ('749ee520-b9cd-5948-b8a9-59897d445f3a'::uuid, 'traffic-rules', 'quiz-b-1', 3, 'At 60 km/h, the total stopping distance in the example is 44 metres. The first 17 metres occur before braking. What is the braking distance?', 'Pada 60 km/j, jumlah jarak berhenti dalam contoh ialah 44 meter. Kenderaan bergerak 17 meter sebelum membrek. Berapakah jarak membrek?', '["17 metres","22 metres","27 metres","32 metres"]'::jsonb, '["17 meter","22 meter","27 meter","32 meter"]'::jsonb, 2, 'The chart breaks the 44 metres into 17 metres of reaction distance and 27 metres of braking distance.', 'Carta membahagikan 44 meter kepada 17 meter jarak reaksi dan 27 meter jarak membrek.', NULL, 'KPP Kelas D Automatik, PDF page 264'),
  ('7200f656-55e8-581d-8955-ffa003b718ac'::uuid, 'traffic-rules', 'quiz-b-1', 4, 'You are close to a junction and realise you are in the wrong lane for your turn. What should you avoid?', 'Anda hampir tiba di persimpangan dan baru sedar anda berada di lorong yang salah untuk membelok. Apakah yang perlu dielakkan?', '["Continuing in your lane","Making a last-second turn","Checking traffic around you","Changing your planned route"]'::jsonb, '["Meneruskan perjalanan di lorong anda","Membelok secara tiba-tiba","Memeriksa trafik di sekeliling","Mengubah laluan yang dirancang"]'::jsonb, 1, 'Choose your lane before arriving. A sudden change of direction at the junction can endanger others.', 'Pilih lorong sebelum tiba. Perubahan arah secara tiba-tiba di persimpangan boleh membahayakan orang lain.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 126'),
  ('2f25f892-1b8c-583e-8932-00294335fbf9'::uuid, 'traffic-rules', 'quiz-b-1', 5, 'You have priority at a junction. How should you approach it?', 'Anda mempunyai keutamaan di persimpangan. Bagaimanakah anda perlu menghampirinya?', '["Keep your current speed","Speed up before crossing","Slow down before crossing","Slow down after crossing"]'::jsonb, '["Kekalkan kelajuan semasa","Tambah kelajuan sebelum melintas","Perlahankan kenderaan sebelum melintas","Perlahankan kenderaan selepas melintas"]'::jsonb, 2, 'Reduce speed at a junction even when you have priority.', 'Perlahankan kenderaan di persimpangan walaupun anda mempunyai keutamaan.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 126'),
  ('a3caf613-80e6-51ec-86c5-24c6ef20f1ee'::uuid, 'traffic-rules', 'quiz-b-1', 6, 'What helps other drivers understand that you plan to turn at a junction?', 'Apakah yang membantu pemandu lain memahami bahawa anda hendak membelok di persimpangan?', '["Correct lane and early signal","Correct lane and late signal","Any lane and early signal","Any lane and late signal"]'::jsonb, '["Lorong betul dan isyarat awal","Lorong betul dan isyarat lewat","Mana-mana lorong dan isyarat awal","Mana-mana lorong dan isyarat lewat"]'::jsonb, 0, 'Position the car in the correct lane and signal before you manoeuvre.', 'Letakkan kereta di lorong yang betul dan beri isyarat sebelum melakukan olah gerak.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 127'),
  ('48540c8d-c1ae-5b7a-9ab9-e7a5c72a1dd1'::uuid, 'traffic-rules', 'quiz-b-1', 7, 'The road ahead is clear for overtaking. What should you check just before moving right?', 'Jalan di hadapan lapang untuk memotong. Apakah yang patut diperiksa sebelum bergerak ke kanan?', '["Behind and beside your car","Ahead and along the shoulder","Ahead and beside your car","Behind and along the shoulder"]'::jsonb, '["Belakang dan sisi kereta anda","Hadapan dan sepanjang bahu jalan","Hadapan dan sisi kereta anda","Belakang dan sepanjang bahu jalan"]'::jsonb, 0, 'Check behind and to the side before moving right. A vehicle could already be overtaking you.', 'Periksa keadaan di belakang dan di sisi sebelum bergerak ke kanan. Kenderaan lain mungkin sedang memotong anda.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 123'),
  ('827f3a44-961f-585a-aa78-90c8fb2067d8'::uuid, 'traffic-rules', 'quiz-b-1', 8, 'What should you see in the side mirror before returning to your lane after passing a car?', 'Apakah yang perlu kelihatan dalam cermin sisi sebelum anda kembali ke lorong asal selepas memotong kereta?', '["The front of the car you passed","The side of the car you passed","The rear of the car ahead","The front of the next car ahead"]'::jsonb, '["Bahagian depan kereta yang dipotong","Bahagian sisi kereta yang dipotong","Bahagian belakang kereta di hadapan","Bahagian depan kereta seterusnya"]'::jsonb, 0, 'Check the left mirror for the front of the car you passed. Return only when the lane is clear.', 'Lihat bahagian depan kereta yang dipotong melalui cermin kiri. Masuk semula hanya apabila lorong selamat.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 123'),
  ('5df63d85-8e4a-5252-b8dd-3ed431cf8d16'::uuid, 'traffic-rules', 'quiz-b-1', 9, 'You reach your roadside marker before finishing the count. How should you check your next following gap?', 'Anda tiba di penanda tepi jalan sebelum selesai mengira. Bagaimanakah anda perlu menyemak jarak mengekori selepas itu?', '["Ease off, then pick another marker","Hold speed, then pick another marker","Ease off, then reuse the same marker","Hold speed, then use the moving car"]'::jsonb, '["Perlahankan kenderaan, kemudian pilih penanda lain","Kekalkan kelajuan, kemudian pilih penanda lain","Perlahankan kenderaan, kemudian guna semula penanda yang sama","Kekalkan kelajuan, kemudian guna kereta yang bergerak"]'::jsonb, 0, 'You are following too closely. Slow down, choose another fixed marker and repeat the count.', 'Anda mengekori terlalu rapat. Perlahankan kenderaan, pilih penanda tetap yang lain dan ulang kiraan.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 119'),
  ('a7cfc02a-479e-5453-b1da-1fabc9f55e4d'::uuid, 'traffic-rules', 'quiz-b-1', 10, 'You have enough room to overtake. When should you signal right?', 'Anda mempunyai ruang yang cukup untuk memotong. Bilakah anda perlu memberi isyarat kanan?', '["After entering the other lane","While entering the other lane","Just as you cross the lane line","Before leaving your lane"]'::jsonb, '["Selepas memasuki lorong sebelah","Semasa memasuki lorong sebelah","Sebaik sahaja melintasi garisan lorong","Sebelum meninggalkan lorong anda"]'::jsonb, 3, 'Signal right at least three seconds before moving right to overtake.', 'Beri isyarat kanan sekurang-kurangnya tiga saat sebelum bergerak ke kanan untuk memotong.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 123'),
  ('6896c4b7-0563-5124-87ca-e7d1c65302d6'::uuid, 'traffic-rules', 'quiz-b-1', 11, 'You are following a car at a steady speed in normal conditions. What is the shortest following gap the handbook recommends?', 'Anda mengekori kereta pada kelajuan tetap dalam keadaan biasa. Apakah jarak masa mengekori paling singkat yang disarankan dalam buku panduan?', '["1 second","2 seconds","3 seconds","4 seconds"]'::jsonb, '["1 saat","2 saat","3 saat","4 saat"]'::jsonb, 1, 'Start counting when the vehicle ahead passes a fixed point. Ease off if you reach the same point before you finish counting two seconds.', 'Mula mengira apabila kenderaan di hadapan melepasi penanda tetap. Perlahankan kenderaan jika anda tiba di penanda sebelum tamat kiraan dua saat.', NULL, 'KPP General, PDF pages 118–120'),
  ('7f464b9c-a62a-57e4-bef7-4cb087f3598c'::uuid, 'traffic-rules', 'quiz-b-1', 12, 'What following gap should you leave when the road becomes slippery?', 'Berapakah jarak masa mengekori yang patut dikekalkan apabila jalan menjadi licin?', '["One second","Two seconds","Three seconds","Four seconds"]'::jsonb, '["Satu saat","Dua saat","Tiga saat","Empat saat"]'::jsonb, 3, 'Use a longer gap on slippery roads. The four-second rule also applies in poor weather and when towing or being tailgated.', 'Jarakkan kenderaan apabila jalan licin. Peraturan empat saat juga digunakan semasa cuaca buruk, ketika menarik beban atau apabila diekori terlalu rapat.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 120'),
  ('8d7c0d3f-3036-57da-9f3f-edecc0eb2d41'::uuid, 'traffic-rules', 'quiz-b-1', 13, 'When do you start counting to check your following gap?', 'Bilakah anda mula mengira untuk menyemak jarak mengekori?', '["When you first see a marker","When your car reaches the marker","When the car ahead passes the marker","When the car ahead passes another car"]'::jsonb, '["Apabila anda mula nampak penanda","Apabila kereta anda sampai di penanda","Apabila kereta di hadapan melepasi penanda","Apabila kereta di hadapan memotong kereta lain"]'::jsonb, 2, 'Pick a fixed marker such as a tree. Count from the moment the leading car passes it.', 'Pilih penanda tetap seperti pokok. Mula mengira apabila kereta di hadapan melepasi penanda itu.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 118'),
  ('456eb987-e1f2-59f2-be1a-2fa6c978eca9'::uuid, 'traffic-rules', 'quiz-b-1', 14, 'What is the 12-second check used for before overtaking?', 'Apakah tujuan pemeriksaan 12 saat sebelum memotong?', '["To scan the road ahead","To time the signal flashes","To measure your following gap","To time the whole manoeuvre"]'::jsonb, '["Untuk mengimbas jalan di hadapan","Untuk mengira tempoh kelipan isyarat","Untuk mengukur jarak mengekori","Untuk mengira tempoh seluruh olah gerak"]'::jsonb, 0, 'Look ahead for potential hazards over the distance you will cover in about 12 seconds.', 'Imbas ke hadapan untuk mengesan bahaya yang mungkin timbul dalam jarak yang akan dilalui dalam kira-kira 12 saat.', NULL, 'Kurikulum Pendidikan Pemandu, PDF pages 122–123'),
  ('3603e7b5-a719-5c00-8458-8c48356208ae'::uuid, 'traffic-rules', 'quiz-b-1', 15, 'Which point is the handbook’s reference for leaving a gap when stopping behind a car?', 'Bahagian manakah dijadikan panduan dalam buku untuk meninggalkan jarak ketika berhenti di belakang kereta?', '["The car’s rear window","The car’s rear wheels","The car’s registration plate","The car’s brake lights"]'::jsonb, '["Cermin belakang kereta hadapan","Roda belakang kereta hadapan","Nombor pendaftaran kereta hadapan","Lampu brek kereta hadapan"]'::jsonb, 1, 'Leave enough room to see the rear wheels of the car ahead and move out if it breaks down.', 'Tinggalkan ruang yang cukup untuk melihat roda belakang kereta di hadapan dan keluar dari barisan jika kereta itu rosak.', NULL, 'KPP Kelas D Automatik, PDF page 263'),
  ('5eeb0ccd-c996-56e2-8736-a31522cc6510'::uuid, 'traffic-rules', 'quiz-b-1', 16, 'After checking the mirrors and signalling, what is the next CITO step before changing lanes?', 'Selepas memeriksa cermin dan memberi isyarat, apakah langkah CITO seterusnya sebelum menukar lorong?', '["Check your speed","Change to a lower gear","Check the blind spot","Start moving across"]'::jsonb, '["Semak kelajuan anda","Tukar ke gear lebih rendah","Periksa titik buta","Mula masuk ke lorong sebelah"]'::jsonb, 2, 'The T in CITO means titik buta. Look over your shoulder to check what the mirrors miss.', 'T dalam CITO bermaksud titik buta. Toleh ke paras bahu untuk melihat kawasan yang tidak kelihatan dalam cermin.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 115'),
  ('3d7c8444-cfe5-583c-8712-852f96d09047'::uuid, 'traffic-rules', 'quiz-b-1', 17, 'After choosing your position at a junction, what should you adjust before selecting a gear?', 'Selepas menentukan posisi di persimpangan, apakah yang perlu dilaraskan sebelum memilih gear?', '["Your speed","Your seat position","Your headlight beam","Your interior mirror"]'::jsonb, '["Kelajuan","Kedudukan tempat duduk","Pancaran lampu hadapan","Cermin pandang belakang"]'::jsonb, 0, 'Choose a safe speed for the junction, then select a gear that suits it.', 'Pilih kelajuan yang selamat untuk persimpangan, kemudian gunakan gear yang sepadan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 109'),
  ('aef65697-00e5-5b3e-bcff-607307da4596'::uuid, 'traffic-rules', 'quiz-b-1', 18, 'What should you do to check a blind spot before moving sideways?', 'Apakah tindakan anda untuk memeriksa titik buta sebelum bergerak ke sisi?', '["Look over your shoulder","Look in the rear-view mirror","Watch the car ahead","Watch the lane marking"]'::jsonb, '["Toleh ke arah bahu","Lihat cermin pandang belakang","Perhatikan kereta di hadapan","Perhatikan garisan lorong"]'::jsonb, 0, 'A shoulder check covers the area that the mirrors cannot show.', 'Tolehan ke arah bahu membantu memeriksa kawasan yang tidak kelihatan dalam cermin.', NULL, 'KPP Automatic Driving Curriculum, PDF page 98'),
  ('fbfa0b80-12eb-5083-b9d6-5db969e6e036'::uuid, 'traffic-rules', 'quiz-b-1', 19, 'When should you decide which way to go at a junction?', 'Bilakah anda patut menentukan arah di persimpangan?', '["Before reaching the junction","As you cross the junction","After entering the junction","When the vehicle behind signals"]'::jsonb, '["Sebelum tiba di persimpangan","Semasa melintasi persimpangan","Selepas memasuki persimpangan","Apabila kenderaan di belakang memberi isyarat"]'::jsonb, 0, 'Plan your route early so you can position the vehicle without a last-minute change.', 'Rancang arah lebih awal supaya anda boleh memilih posisi tanpa menukar haluan pada saat akhir.', NULL, 'KPP Automatic Driving Curriculum, PDF page 108'),
  ('6b874ff2-51c2-5b46-b811-be0fefb5171b'::uuid, 'traffic-rules', 'quiz-b-1', 20, 'What changes when you drop back from a tall vehicle you are following?', 'Apakah yang berubah apabila anda menambah jarak di belakang kenderaan tinggi?', '["More of the road ahead comes into view","The vehicle ahead fills more of the view","The view ahead stays the same","Less of the road ahead can be seen"]'::jsonb, '["Lebih banyak jalan di hadapan dapat dilihat","Kenderaan di hadapan memenuhi lebih banyak pandangan","Pandangan di hadapan kekal sama","Kurang jalan di hadapan dapat dilihat"]'::jsonb, 0, 'With more space, the vehicle ahead blocks less of your view.', 'Dengan ruang tambahan, kenderaan di hadapan kurang menghalang pandangan anda.', NULL, 'KPP Automatic Driving Curriculum, PDF page 104'),
  ('b56eedce-474f-5a4d-a8a1-52b6ea5ae9f5'::uuid, 'traffic-rules', 'quiz-b-1', 21, 'Why scan well ahead before overtaking?', 'Mengapa perlu mengimbas jauh ke hadapan sebelum memotong?', '["To check whether the road ahead is clear","To check whether the next car is slowing","To judge the gap behind your own car","To estimate how closely you can follow"]'::jsonb, '["Untuk memastikan jalan di hadapan lapang","Untuk melihat sama ada kereta hadapan memperlahankan kenderaan","Untuk menganggar jarak di belakang kereta sendiri","Untuk menganggar jarak mengekori terdekat"]'::jsonb, 0, 'A forward scan helps you judge if the road is clear for the manoeuvre.', 'Imbasan ke hadapan membantu anda menilai sama ada laluan lapang untuk memotong.', NULL, 'KPP General, PDF page 122'),
  ('380261ba-245e-5fc2-97fe-3e30bbb95d04'::uuid, 'traffic-rules', 'quiz-b-1', 22, 'Which mirror should show the front of a vehicle you have just passed before you move left?', 'Cermin manakah yang patut menunjukkan bahagian hadapan kenderaan yang baru dipotong sebelum anda bergerak ke kiri?', '["Left side mirror","Right side mirror","Interior mirror","Any of the mirrors"]'::jsonb, '["Cermin sisi kiri","Cermin sisi kanan","Cermin pandang belakang","Mana-mana cermin"]'::jsonb, 0, 'Check the left side mirror and make sure it is safe before moving back.', 'Periksa cermin sisi kiri dan pastikan selamat sebelum kembali ke kiri.', NULL, 'KPP Automatic Driving Curriculum, PDF page 105'),
  ('f2aa68f5-5795-5641-aa93-61f8dba55ecd'::uuid, 'traffic-rules', 'quiz-b-1', 23, 'You are already alongside a vehicle you are passing. Which gap still matters?', 'Anda sudah berada di sebelah kenderaan yang dipotong. Jarak manakah masih perlu dijaga?', '["The gap between the sides of both vehicles","The gap behind the vehicle being passed","The gap to the centre line only","The gap to the vehicle behind you"]'::jsonb, '["Jarak antara sisi kedua-dua kenderaan","Jarak di belakang kenderaan yang dipotong","Jarak ke garisan tengah sahaja","Jarak ke kenderaan di belakang anda"]'::jsonb, 0, 'Keep a safe lateral gap throughout the pass.', 'Kekalkan jarak sisi yang selamat sepanjang tindakan memotong.', NULL, 'KPP Automatic Driving Curriculum, PDF page 105'),
  ('a8aa56e7-4aea-5513-beb7-e1eb1c89fe14'::uuid, 'traffic-rules', 'quiz-b-1', 24, 'When passing a vehicle on a clear two-way road, which side should you normally move to?', 'Ketika memotong di jalan dua hala yang lapang, ke arah manakah anda biasanya perlu bergerak?', '["To the right","To the left","Onto the shoulder","Toward the centre of your lane"]'::jsonb, '["Ke kanan","Ke kiri","Ke bahu jalan","Ke tengah lorong sendiri"]'::jsonb, 0, 'Check the road and surrounding traffic before moving right to pass.', 'Periksa jalan dan trafik sekeliling sebelum bergerak ke kanan untuk memotong.', NULL, 'KPP Automatic Driving Curriculum, PDF page 105'),
  ('0d97dca7-2614-5fcb-b113-146a76b77964'::uuid, 'traffic-rules', 'quiz-b-1', 25, 'You catch a slow car near the crest of a hill. When should you consider passing?', 'Anda menghampiri kereta perlahan berhampiran puncak bukit. Bilakah anda patut mempertimbangkan untuk memotong?', '["After the road ahead is clear","Just before the crest","As you reach the crest","As soon as the car slows"]'::jsonb, '["Selepas laluan di hadapan jelas","Sebelum tiba di puncak","Sebaik tiba di puncak","Sebaik kereta itu memperlahankan kenderaan"]'::jsonb, 0, 'Wait until past the crest and check that there is clear road ahead.', 'Tunggu sehingga melepasi puncak dan pastikan laluan di hadapan jelas.', NULL, 'KPP Automatic Driving Curriculum, PDF page 106'),
  ('022d01dc-f60b-5df8-b24f-91df789664e6'::uuid, 'traffic-rules', 'quiz-b-2', 1, 'You are considering a pass where visibility is good. Where should you hold back?', 'Anda bercadang untuk memotong di tempat yang mempunyai jarak penglihatan yang baik. Di manakah anda perlu menangguhkan tindakan itu?', '["Approaching a pedestrian crossing","Passing an empty bus bay","Driving past a parking bay","Passing a sign on a straight road"]'::jsonb, '["Menghampiri lintasan pejalan kaki","Melalui petak bas yang kosong","Memandu melepasi petak parkir","Melepasi papan tanda di jalan lurus"]'::jsonb, 0, 'Avoid passing vehicles on the approach to a pedestrian crossing.', 'Elakkan memotong kenderaan ketika menghampiri lintasan pejalan kaki.', NULL, 'KPP Automatic Driving Curriculum, PDF page 106'),
  ('e2e211bc-64c3-51d9-8f51-630523e34eed'::uuid, 'traffic-rules', 'quiz-b-2', 2, 'The car behind needs to see you slowing. Which lights should you check before leaving?', 'Pemandu di belakang perlu melihat apabila anda memperlahankan kenderaan. Lampu manakah yang patut diperiksa sebelum bertolak?', '["Brake lights","Reversing lights","Direction indicators","Rear fog lights"]'::jsonb, '["Lampu brek","Lampu undur","Lampu isyarat","Lampu kabus belakang"]'::jsonb, 0, 'Brake lights must work so following drivers can see you slowing.', 'Lampu brek mesti berfungsi supaya pemandu di belakang boleh melihat anda memperlahankan kenderaan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 120'),
  ('96f0c708-1daa-519b-aad4-f748b93ebcc7'::uuid, 'traffic-rules', 'quiz-b-2', 3, 'A driver follows you too closely. What following gap should you leave ahead?', 'Pemandu di belakang mengekori terlalu rapat. Berapakah jarak masa yang patut anda tinggalkan di hadapan?', '["Four seconds","Two seconds","One second","Half a second"]'::jsonb, '["Empat saat","Dua saat","Satu saat","Setengah saat"]'::jsonb, 0, 'Leave more space in front so you have time to slow down gradually.', 'Tinggalkan lebih ruang di hadapan supaya anda boleh memperlahankan kenderaan secara beransur-ansur.', NULL, 'KPP Automatic Driving Curriculum, PDF page 102'),
  ('27b2f825-a77a-54ec-8017-bfbc51ab0e9c'::uuid, 'traffic-rules', 'quiz-b-2', 4, 'An oncoming vehicle drifts into your lane. Which direction should you move if there is room?', 'Kenderaan dari arah bertentangan memasuki lorong anda. Ke arah manakah patut anda bergerak jika ada ruang?', '["Move to the left","Move to the right","Hold the same line","Follow the other vehicle’s path"]'::jsonb, '["Bergerak ke kiri","Bergerak ke kanan","Kekalkan laluan yang sama","Ikut laluan kenderaan itu"]'::jsonb, 0, 'Move left if safe and warn the oncoming driver with your horn or a flash of the headlights.', 'Bergerak ke kiri jika selamat dan beri amaran dengan hon atau kelipan lampu hadapan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 107'),
  ('98e3b156-f5a3-5858-9044-0b1ef99119c8'::uuid, 'traffic-rules', 'quiz-b-2', 5, 'You want to take the first exit at a two-lane roundabout. How do you enter?', 'Anda hendak mengambil susur keluar pertama di bulatan dua lorong. Bagaimanakah anda perlu masuk?', '["Left lane, right signal","Right lane, left signal","Left lane, left signal","Right lane, right signal"]'::jsonb, '["Lorong kiri, isyarat kanan","Lorong kanan, isyarat kiri","Lorong kiri, isyarat kiri","Lorong kanan, isyarat kanan"]'::jsonb, 2, 'Signal left as you approach, enter the left lane and keep signalling left through the exit.', 'Beri isyarat kiri ketika menghampiri bulatan, masuk ke lorong kiri dan kekalkan isyarat sehingga keluar.', NULL, 'KPP Kelas D Automatik, PDF page 258'),
  ('6dcd330d-4a32-5383-817f-3a76e538698e'::uuid, 'traffic-rules', 'quiz-b-2', 6, 'You are taking the second exit at a two-lane roundabout. When should you signal left?', 'Anda akan mengambil susur keluar kedua di bulatan dua lorong. Bilakah anda patut memberi isyarat kiri?', '["Just after passing the first exit","Before entering the roundabout","Just before reaching the first exit","After leaving the roundabout"]'::jsonb, '["Sejurus selepas melepasi susur pertama","Sebelum memasuki bulatan","Sejurus sebelum tiba di susur pertama","Selepas meninggalkan bulatan"]'::jsonb, 0, 'Use the left lane unless it is blocked. Stay in your lane and signal left after passing the first exit.', 'Gunakan lorong kiri kecuali jika terhalang. Kekal di lorong anda dan beri isyarat kiri selepas melepasi susur keluar pertama.', NULL, 'KPP Kelas D Automatik, PDF pages 258–259'),
  ('6d74794c-f502-5d4e-b7b1-2f7bb235e391'::uuid, 'traffic-rules', 'quiz-b-2', 7, 'You enter a roundabout to make a U-turn. How do you signal?', 'Anda memasuki bulatan untuk membuat pusingan U. Bagaimanakah anda perlu memberi isyarat?', '["Left on entry, right to exit","Right on entry, left to exit","Right on entry, right to exit","Left on entry, left to exit"]'::jsonb, '["Kiri ketika masuk, kanan untuk keluar","Kanan ketika masuk, kiri untuk keluar","Kanan ketika masuk, kanan untuk keluar","Kiri ketika masuk, kiri untuk keluar"]'::jsonb, 1, 'Enter in the right lane with the right signal. Change to the left signal after passing the exit before yours.', 'Masuk di lorong kanan dengan isyarat kanan. Tukar kepada isyarat kiri selepas melepasi susur keluar sebelum susur anda.', NULL, 'KPP Kelas D Automatik, PDF page 259'),
  ('b42f2d44-12be-5c7f-9d6f-bc67680c7960'::uuid, 'traffic-rules', 'quiz-b-2', 8, 'At a three-lane roundabout with no lane arrows, which approach lane does the handbook recommend for going straight?', 'Di bulatan tiga lorong tanpa anak panah lorong, lorong manakah disyorkan oleh buku panduan untuk bergerak lurus?', '["The left lane","The right lane","The middle lane","Any open lane"]'::jsonb, '["Lorong kiri","Lorong kanan","Lorong tengah","Mana-mana lorong kosong"]'::jsonb, 2, 'In a three-lane roundabout, the middle lane is for straight ahead. The left lane is for a left turn, and the right lane is for a right turn or U-turn.', 'Di bulatan tiga lorong, lorong tengah untuk terus. Lorong kiri untuk membelok ke kiri, dan lorong kanan untuk membelok ke kanan atau membuat pusingan U.', NULL, 'KPP Kelas D Automatik, PDF page 257'),
  ('757ed720-ec57-51c1-86cf-a86528350167'::uuid, 'traffic-rules', 'quiz-b-2', 9, 'You are waiting to enter a roundabout. Which vehicles already circulating should you give way to?', 'Anda menunggu untuk memasuki bulatan. Kenderaan manakah yang sudah berada di bulatan perlu diberi laluan?', '["Circulating traffic on your left","Circulating traffic from your right","Vehicles entering at the next arm","Vehicles leaving at the next exit"]'::jsonb, '["Trafik yang beredar di sebelah kiri","Trafik yang beredar dari kanan","Kenderaan yang masuk di laluan seterusnya","Kenderaan yang keluar di susur seterusnya"]'::jsonb, 1, 'Slow down and let traffic approaching from the right pass before you enter.', 'Perlahankan kenderaan dan beri laluan kepada trafik dari sebelah kanan sebelum masuk.', NULL, 'KPP Kelas D Automatik, PDF page 257'),
  ('5569182b-2965-5279-83a8-eecb167573f4'::uuid, 'traffic-rules', 'quiz-b-2', 10, 'The light turns amber and you have enough room to stop before the line. What should you do?', 'Lampu bertukar jingga dan ruang mencukupi untuk berhenti sebelum garisan. Apakah tindakan anda?', '["Stop behind the line","Proceed if the lane is clear","Slow down and pass the line","Wait beyond the line"]'::jsonb, '["Berhenti di belakang garisan","Teruskan jika lorong lapang","Perlahankan dan lepasi garisan","Tunggu selepas garisan"]'::jsonb, 0, 'Amber means stop unless you have already passed the line.', 'Lampu jingga bermaksud berhenti kecuali jika anda sudah melepasi garisan.', NULL, 'KPP General, PDF page 34'),
  ('4b887bbc-5f1a-5fc7-a46d-95c8932b65be'::uuid, 'traffic-rules', 'quiz-b-2', 11, 'Traffic lights fail at a four-way junction. Who automatically has priority?', 'Lampu isyarat di simpang empat gagal berfungsi. Siapakah yang mendapat keutamaan secara automatik?', '["No approach","Traffic from the right","Traffic going straight","Traffic on the wider road"]'::jsonb, '["Tiada mana-mana arah","Trafik dari kanan","Trafik yang bergerak lurus","Trafik di jalan lebih lebar"]'::jsonb, 0, 'No approach has automatic priority at a four-way junction with failed signals. Proceed cautiously and cooperate with other drivers.', 'Tiada mana-mana arah mendapat keutamaan secara automatik. Berhati-hati dan bertimbang rasa dengan pemandu lain.', NULL, 'KPP General, PDF page 34'),
  ('69a0ee40-65e8-5cca-a85a-998c473bc428'::uuid, 'traffic-rules', 'quiz-b-2', 12, 'A traffic officer has their back to you, with their right arm out to the side and their left arm across their chest. What should you do?', 'Anggota polis trafik membelakangi anda dengan lengan kanan diluruskan ke sisi dan lengan kiri di hadapan dada. Apakah tindakan anda?', '["Stop and wait","Slow and proceed","Move to the right","Move to the left"]'::jsonb, '["Berhenti dan tunggu","Perlahankan dan teruskan","Bergerak ke kanan","Bergerak ke kiri"]'::jsonb, 0, 'For this signal, traffic behind the officer stops. Traffic in front may turn right.', 'Bagi isyarat ini, trafik di belakang anggota polis berhenti. Trafik di hadapannya boleh membelok ke kanan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 74'),
  ('34f0e205-e44a-5174-b1e1-4ad34b29f6e9'::uuid, 'traffic-rules', 'quiz-b-2', 13, 'The lights fail at a T-junction. Which traffic goes first?', 'Lampu isyarat di simpang tiga gagal berfungsi. Trafik manakah bergerak dahulu?', '["Traffic on the main road","Traffic entering from the side road","Traffic turning across the main road","Traffic arriving at the signals first"]'::jsonb, '["Trafik di jalan utama","Trafik yang keluar dari jalan sisi","Trafik yang membelok merentasi jalan utama","Trafik yang tiba dahulu di lampu isyarat"]'::jsonb, 0, 'Give priority to vehicles on the main road when the lights fail at a T-junction.', 'Apabila lampu isyarat gagal berfungsi di simpang tiga, beri keutamaan kepada kenderaan di jalan utama.', NULL, 'KPP General, PDF page 34'),
  ('956cfc41-6ea4-56cd-ad6b-9030913a9928'::uuid, 'traffic-rules', 'quiz-b-2', 14, 'Before a right turn at a junction, when should you reduce speed?', 'Sebelum membelok ke kanan di persimpangan, bilakah anda patut mengurangkan kelajuan?', '["On the approach","Halfway through the turn","After straightening the wheel","Once you leave the junction"]'::jsonb, '["Semasa menghampiri persimpangan","Di pertengahan belokan","Selepas meluruskan stereng","Sebaik keluar dari persimpangan"]'::jsonb, 0, 'Reduce speed before turning so you can control the vehicle through the junction.', 'Kurangkan kelajuan sebelum membelok supaya kenderaan dapat dikawal semasa melalui persimpangan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 112'),
  ('cea9df00-6ec6-5a76-9f67-929633fd5290'::uuid, 'traffic-rules', 'quiz-b-2', 15, 'An ambulance sounds its siren behind you while you have right of way. What should you do?', 'Ambulans membunyikan siren di belakang ketika anda mempunyai hak laluan. Apakah tindakan anda?', '["Give it room to pass","Keep your right of way","Speed up to clear the lane","Wait for the siren to stop"]'::jsonb, '["Beri ruang untuk ia lalu","Kekalkan hak laluan anda","Pecut untuk mengosongkan lorong","Tunggu sehingga siren berhenti"]'::jsonb, 0, 'Give priority to emergency vehicles sounding a siren even when you have the right of way.', 'Beri keutamaan kepada kenderaan kecemasan yang membunyikan siren walaupun anda mempunyai hak laluan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 89'),
  ('5ecad7e2-9fb8-5927-9da7-bd0e39c6452a'::uuid, 'traffic-rules', 'quiz-b-2', 16, 'How should you begin a turn using the pull-and-push steering technique?', 'Bagaimanakah anda memulakan belokan menggunakan teknik stereng tarik dan tolak?', '["Draw the steering wheel down","Press the steering wheel upward","Hold the wheel with one hand","Cross your hands over first"]'::jsonb, '["Tarik stereng ke bawah","Tolak stereng ke atas","Pegang stereng dengan sebelah tangan","Silangkan tangan terlebih dahulu"]'::jsonb, 0, 'Start by drawing the rim down with one hand while the other slides along it.', 'Mulakan dengan menarik rim stereng ke bawah dengan sebelah tangan sementara tangan lain melurut pada rim.', NULL, 'KPP Automatic Driving Curriculum, PDF page 216'),
  ('462b4c26-bc26-55a5-9185-3f9d37fda78b'::uuid, 'traffic-rules', 'quiz-b-2', 17, 'Your car follows a wider arc than you intended through a bend. Which term describes it?', 'Kereta mengambil laluan lebih lebar daripada yang dimaksudkan ketika membelok. Apakah istilahnya?', '["Understeer","Oversteer","Late steering","Early steering"]'::jsonb, '["Kurang putaran stereng","Putaran stereng berlebihan","Putaran stereng lewat","Putaran stereng awal"]'::jsonb, 0, 'In the handbook example, too little steering opens the turn and can carry the car toward the edge of the road.', 'Dalam contoh buku, putaran stereng yang kurang melebarkan belokan dan boleh membawa kereta ke tepi jalan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 260'),
  ('ac1f097c-c1d5-5c6c-bee7-a45d13b4d3df'::uuid, 'traffic-rules', 'quiz-b-2', 18, 'With normal tyre grip, what happens to your turning path if you steer too sharply?', 'Dengan cengkaman tayar biasa, apakah kesan memusing stereng terlalu banyak pada laluan belokan?', '["It tightens","It widens","It stays the same","It straightens"]'::jsonb, '["Lengkok mengecil","Lengkok melebar","Lengkok kekal sama","Laluan menjadi lurus"]'::jsonb, 0, 'Too much steering tightens the arc, potentially taking the vehicle into another lane.', 'Putaran berlebihan mengecilkan lengkok dan boleh membawa kenderaan ke lorong lain.', NULL, 'KPP Automatic Driving Curriculum, PDF page 260'),
  ('7724ad74-32bd-5cd8-a1a5-ffd49af7ebcf'::uuid, 'traffic-rules', 'quiz-b-2', 19, 'You approach a bend on a wet road. How should you adjust your speed?', 'Anda menghampiri selekoh di jalan basah. Bagaimanakah anda patut melaraskan kelajuan?', '["Reduce speed before the bend","Keep the same speed through the bend","Increase speed into the bend","Wait until the exit to slow down"]'::jsonb, '["Kurangkan kelajuan sebelum selekoh","Kekalkan kelajuan sepanjang selekoh","Tambah kelajuan ketika memasuki selekoh","Tunggu sehingga keluar untuk memperlahankan kenderaan"]'::jsonb, 0, 'Wet roads reduce tyre grip. Lower speed helps you maintain control in a bend.', 'Jalan basah mengurangkan cengkaman tayar. Kelajuan lebih rendah membantu mengekalkan kawalan di selekoh.', NULL, 'KPP Automatic Driving Curriculum, PDF page 146'),
  ('a411dc48-a160-5122-9337-acd79a74c97e'::uuid, 'traffic-rules', 'quiz-b-2', 20, 'When entering moving traffic from a slip road, what should your move accomplish?', 'Apabila masuk ke dalam aliran trafik dari jalan susur, apakah tujuan olah gerak anda?', '["Join the flow smoothly","Make traffic behind you slow","Stay beside a car in the next lane","Enter at the same point as the car ahead"]'::jsonb, '["Masuk ke dalam aliran dengan lancar","Paksa trafik di belakang memperlahankan kenderaan","Kekal di sebelah kereta di lorong bersebelahan","Masuk pada tempat yang sama dengan kereta di hadapan"]'::jsonb, 0, 'Merge into a safe gap at a speed and position that suit the traffic.', 'Masuk ke ruang selamat pada kelajuan dan posisi yang sesuai dengan trafik.', NULL, 'KPP Automatic Driving Curriculum, PDF page 117'),
  ('8c81e40d-0e07-529e-9ffb-5bbf63a07012'::uuid, 'traffic-rules', 'quiz-b-2', 21, 'The handbook estimates seven seconds to recover from glare. At 70 km/h, about how far do you travel in that time?', 'Buku menganggarkan tujuh saat untuk pulih daripada silau. Pada 70 km/j, kira-kira sejauh manakah anda bergerak dalam tempoh itu?', '["140 m","70 m","100 m","200 m"]'::jsonb, '["140 m","70 m","100 m","200 m"]'::jsonb, 0, 'At 70 km/h the car travels about 19 metres per second. In seven seconds that is about 140 metres.', 'Pada 70 km/j, kereta bergerak kira-kira 19 meter sesaat. Dalam tujuh saat jaraknya sekitar 140 meter.', NULL, 'KPP Automatic Driving Curriculum, PDF page 122'),
  ('448286e4-75f2-59a3-a1f1-b1685076b257'::uuid, 'traffic-rules', 'quiz-b-2', 22, 'What can you do if an oncoming driver leaves their high beams on?', 'Apakah yang boleh anda lakukan jika pemandu dari arah bertentangan terus menggunakan lampu tinggi?', '["Flash your lights briefly","Hold your high beams on","Turn your headlights off","Switch on your fog lights"]'::jsonb, '["Kelipkan lampu seketika","Biarkan lampu tinggi menyala","Padamkan lampu hadapan","Nyalakan lampu kabus"]'::jsonb, 0, 'A brief flash can remind the other driver to dip their beams.', 'Kelipan seketika boleh mengingatkan pemandu itu supaya merendahkan lampu.', NULL, 'KPP Automatic Driving Curriculum, PDF page 142'),
  ('25533ad6-3ef0-53ec-9a32-85c43d02f581'::uuid, 'traffic-rules', 'quiz-b-2', 23, 'You catch up with another car at night. Which headlights should you use?', 'Anda menghampiri kereta lain pada waktu malam. Lampu manakah patut digunakan?', '["Low beam","High beam","Parking lamps only","Front fog lamps only"]'::jsonb, '["Lampu rendah","Lampu tinggi","Lampu parkir sahaja","Lampu kabus hadapan sahaja"]'::jsonb, 0, 'Use low beam when following a vehicle. High beam can dazzle its driver through the mirrors.', 'Gunakan lampu rendah ketika mengekori kenderaan. Lampu tinggi boleh menyilaukan pemandu melalui cermin.', NULL, 'KPP Automatic Driving Curriculum, PDF page 142'),
  ('aaf18373-b379-56b0-b8b3-ae0f6ac0b496'::uuid, 'traffic-rules', 'quiz-b-2', 24, 'During a headlight check before a night trip, what should you verify besides whether the lights turn on?', 'Semasa memeriksa lampu hadapan sebelum perjalanan malam, apakah yang perlu diperiksa selain sama ada lampu menyala?', '["The beams are aimed correctly","The beams point as high as possible","The beams reach the same height as the mirrors","The beams illuminate the bonnet evenly"]'::jsonb, '["Pancaran dilaras dengan betul","Pancaran dihalakan setinggi mungkin","Pancaran mencapai paras cermin sisi","Pancaran menyinari bonet secara sekata"]'::jsonb, 0, 'Check that the lights work and are adjusted before setting off at night.', 'Pastikan lampu berfungsi dan dilaraskan sebelum memulakan perjalanan pada waktu malam.', NULL, 'KPP Automatic Driving Curriculum, PDF page 142'),
  ('5115fbc5-c43e-58d3-882d-0a3a0c31331b'::uuid, 'traffic-rules', 'quiz-b-2', 25, 'After hitting standing water, a driver briefly loses steering response. What can cause this?', 'Selepas meredah air bertakung, stereng tidak memberi tindak balas seketika. Apakah puncanya?', '["A layer of water lifts the tyres off the road","Water covers the outside of the tyres","Wet tread grips more strongly on one side","Water cools the tyre and improves its grip"]'::jsonb, '["Lapisan air mengangkat tayar dari jalan","Air meliputi permukaan luar tayar","Bunga basah lebih mencengkam di satu sisi","Air menyejukkan tayar dan menambah cengkaman"]'::jsonb, 0, 'Water collects under the tyres. As they lose grip, steering and braking become less effective.', 'Air terkumpul di bawah tayar. Apabila cengkaman hilang, stereng dan brek menjadi kurang berkesan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 146'),
  ('ffe902fd-7396-59cb-8ec1-cff2252f89cd'::uuid, 'traffic-rules', 'quiz-b-3', 1, 'Your tyres begin to aquaplane. What should you do first?', 'Tayar mula menggelungsur di atas air. Apakah tindakan pertama anda?', '["Ease off the accelerator","Brake in short pulses","Steer toward the shoulder","Hold your current speed"]'::jsonb, '["Lepaskan pedal minyak perlahan-lahan","Tekan brek secara berselang","Pusing stereng ke bahu jalan","Kekalkan kelajuan semasa"]'::jsonb, 0, 'Slow gradually by easing off the accelerator. Avoid braking or changing direction until grip returns.', 'Perlahankan kenderaan dengan melepaskan pedal minyak secara beransur-ansur. Elakkan membrek atau menukar arah sehingga tayar kembali mencengkam.', NULL, 'KPP Automatic Driving Curriculum, PDF page 146'),
  ('f3528f4d-4d94-5a3a-8ce8-929ac7d9bee4'::uuid, 'traffic-rules', 'quiz-b-3', 2, 'Rain makes your car hard for other drivers to see. What should you do?', 'Hujan menyebabkan kereta anda sukar dilihat oleh pemandu lain. Apakah tindakan anda?', '["Switch on the headlights","Turn on the cabin light","Leave the lights off","Flash the headlights periodically"]'::jsonb, '["Nyalakan lampu hadapan","Nyalakan lampu kabin","Biarkan lampu terpadam","Kelipkan lampu hadapan sekali-sekala"]'::jsonb, 0, 'Use headlights in poor visibility so other road users can see your vehicle.', 'Gunakan lampu hadapan apabila penglihatan terhad supaya pengguna jalan raya lain dapat melihat kenderaan anda.', NULL, 'KPP Automatic Driving Curriculum, PDF page 146'),
  ('f8670e36-d455-5bf2-88d9-9167c2a8a1fe'::uuid, 'traffic-rules', 'quiz-b-3', 3, 'You have confirmed that the floodwater is shallow enough to cross. How should you drive through?', 'Anda telah memastikan air banjir cukup cetek untuk dilalui. Bagaimanakah anda patut memandu merentasinya?', '["Slowly in a low gear","Slowly in a high gear","Quickly in a low gear","Coasting in neutral"]'::jsonb, '["Perlahan dalam gear rendah","Perlahan dalam gear tinggi","Laju dalam gear rendah","Meluncur dalam gear neutral"]'::jsonb, 0, 'Only cross after assessing the depth. Use a low gear and keep speed low.', 'Lalui hanya selepas menilai kedalaman air. Gunakan gear rendah dan kekalkan kelajuan rendah.', NULL, 'KPP Automatic Driving Curriculum, PDF page 148'),
  ('882c9651-145a-5942-b5a0-69b4a621af1f'::uuid, 'traffic-rules', 'quiz-b-3', 4, 'Floodwater covers the road ahead and you cannot judge its depth. How should you proceed?', 'Air banjir menutupi jalan di hadapan dan kedalamannya tidak dapat dipastikan. Apakah tindakan anda?', '["Turn back and find another route","Wait for a larger vehicle and follow it","Test the water by entering slowly","Cross where the water looks still"]'::jsonb, '["Patah balik dan cari laluan lain","Tunggu kenderaan lebih besar dan ikutinya","Uji air dengan memasuki perlahan-lahan","Lintas di tempat air kelihatan tenang"]'::jsonb, 0, 'Choose another route. Deep water can stall the engine or damage it if water reaches the air intake.', 'Pilih laluan lain. Air dalam boleh mematikan enjin atau merosakkannya jika air masuk melalui salur udara.', NULL, 'KPP Automatic Driving Curriculum, PDF page 148'),
  ('48cbab18-a7b7-54bb-84f9-6db10e84c52f'::uuid, 'traffic-rules', 'quiz-b-3', 5, 'What should you switch on when entering a tunnel?', 'Apakah yang patut dihidupkan apabila memasuki terowong?', '["Headlights","Hazard lights","Interior lights","Rear fog lights"]'::jsonb, '["Lampu hadapan","Lampu kecemasan","Lampu kabin","Lampu kabus belakang"]'::jsonb, 0, 'Use your headlights in the tunnel and leave a safe gap because visibility is limited.', 'Gunakan lampu hadapan di dalam terowong dan kekalkan jarak selamat kerana penglihatan terhad.', NULL, 'KPP Automatic Driving Curriculum, PDF page 139'),
  ('e2214e9a-6d7f-5c7c-a9f4-864d3fbc943b'::uuid, 'traffic-rules', 'quiz-b-3', 6, 'Where should you avoid stopping to pick someone up?', 'Di manakah anda patut mengelak daripada berhenti untuk mengambil penumpang?', '["Beside a fire hydrant","In a designated pickup bay","In a legal parking space","At a passenger drop-off point"]'::jsonb, '["Di sebelah pili bomba","Di petak mengambil penumpang","Di petak parkir yang dibenarkan","Di tempat menurunkan penumpang"]'::jsonb, 0, 'The book lists fire hydrants among places where drivers should avoid stopping.', 'Pili bomba ialah antara tempat yang perlu dielakkan ketika berhenti.', NULL, 'KPP Automatic Driving Curriculum, PDF page 263'),
  ('e7904cb7-0e75-50c8-bcc5-74bd3c90b9ae'::uuid, 'traffic-rules', 'quiz-b-3', 7, 'Which location should you avoid when picking up a passenger?', 'Lokasi manakah patut dielakkan ketika mengambil penumpang?', '["A stop marked for buses","A bay marked for pickups","An open public car park","A lay-by open to cars"]'::jsonb, '["Perhentian bertanda untuk bas","Petak bertanda untuk mengambil penumpang","Tempat letak kereta awam yang dibuka","Ruang berhenti yang terbuka kepada kereta"]'::jsonb, 0, 'The stopping lesson lists bends, junctions, fire hydrants and bus stops as places to avoid.', 'Pelajaran berhenti menyenaraikan selekoh, persimpangan, pili bomba dan perhentian bas sebagai tempat yang perlu dielakkan.', NULL, 'KPP Kelas DA Automatik, PDF 263'),
  ('5c5a348d-f75c-5541-9262-2297997760f2'::uuid, 'traffic-rules', 'quiz-b-3', 8, 'When should you apply the parking brake during the normal stopping routine?', 'Bilakah brek tangan perlu ditarik semasa rutin berhenti biasa?', '["As you release the accelerator","Once the car has stopped","As the car starts to slow","Just before pressing the foot brake"]'::jsonb, '["Semasa melepaskan pemecut","Selepas kereta berhenti","Ketika kereta mula perlahan","Sebelum menekan pedal brek"]'::jsonb, 1, 'The lesson first uses the foot brake to stop the vehicle. It then calls for applying the parking brake once stationary.', 'Pelajaran menggunakan pedal brek dahulu untuk menghentikan kereta. Tarik brek tangan selepas kereta berhenti.', NULL, 'KPP Kelas DA Automatik, PDF 263'),
  ('284da69c-24e2-5b57-8ae6-199963fe0e2c'::uuid, 'traffic-rules', 'quiz-b-3', 9, 'You have applied the parking brake and are about to leave the parked car. What else should you do before getting out?', 'Brek tangan sudah ditarik dan anda hendak meninggalkan kereta. Apakah yang perlu dibuat sebelum keluar?', '["Switch off the engine","Shift into neutral and leave it idling","Wait for the cooling fan to stop","Switch off the lights and leave it idling"]'::jsonb, '["Matikan enjin","Tukar ke neutral dan biarkan enjin melahu","Tunggu kipas penyejuk berhenti","Padam lampu dan biarkan enjin melahu"]'::jsonb, 0, 'The curriculum flags leaving a vehicle without switching off the engine or applying the parking brake.', 'Kurikulum menyenaraikan meninggalkan kenderaan tanpa mematikan enjin atau menggunakan brek tangan sebagai kesalahan.', NULL, 'KPP Kelas DA Automatik, PDF 166'),
  ('3660a861-009c-5913-bfb2-3cad2af1ea79'::uuid, 'traffic-rules', 'quiz-b-3', 10, 'The handbook lists two dangerous-driving offences. What makes the more serious one different?', 'Buku panduan menyenaraikan dua kesalahan memandu secara berbahaya. Apakah yang membezakan kesalahan yang lebih serius?', '["Whether property was damaged","Whether a warning was given","Whether there was a passenger","Whether someone was killed"]'::jsonb, '["Sama ada harta benda rosak","Sama ada amaran diberikan","Sama ada terdapat penumpang","Sama ada terdapat kematian"]'::jsonb, 3, 'The table distinguishes dangerous driving causing death from dangerous driving with no death.', 'Jadual membezakan pemanduan berbahaya yang menyebabkan kematian daripada pemanduan berbahaya tanpa kematian.', NULL, 'KPP Kelas DA Automatik, PDF 162'),
  ('1ef3e6fd-d137-5def-a24e-ee300b8eb208'::uuid, 'traffic-rules', 'quiz-b-3', 11, 'The handbook lists reckless or dangerous driving under two headings. Which outcome distinguishes those headings?', 'Buku panduan menyenaraikan pemanduan melulu atau berbahaya di bawah dua tajuk. Akibat manakah membezakan kedua-dua tajuk itu?', '["A person dies","A person is injured","A vehicle is damaged","Traffic is obstructed"]'::jsonb, '["Seseorang maut","Seseorang cedera","Kenderaan rosak","Trafik terhalang"]'::jsonb, 0, 'The handbook lists reckless or dangerous driving that causes death separately from the offence without that outcome.', 'Buku panduan menyenaraikan pemanduan melulu atau berbahaya yang menyebabkan kematian secara berasingan daripada kesalahan tanpa akibat itu.', NULL, 'KPP Kelas DA Automatik, PDF 162'),
  ('2547e6ee-293f-5342-9adf-fbea6d0dcacb'::uuid, 'traffic-rules', 'quiz-b-3', 12, 'Which section does the curriculum associate with careless and inconsiderate driving?', 'Seksyen manakah dikaitkan dengan pemanduan cuai dan tidak bertimbang rasa dalam kurikulum?', '["Section 41","Section 43","Section 44","Section 46"]'::jsonb, '["Seksyen 41","Seksyen 43","Seksyen 44","Seksyen 46"]'::jsonb, 1, 'The curriculum’s offence table lists careless and inconsiderate driving under Section 43.', 'Jadual kesalahan dalam kurikulum menyenaraikan pemanduan cuai dan tidak bertimbang rasa di bawah Seksyen 43.', NULL, 'KPP Kelas DA Automatik, PDF 163'),
  ('99533a7d-26d8-5782-9948-b80152c96a3c'::uuid, 'traffic-rules', 'quiz-b-3', 13, 'Which fact does the textbook use to identify the offence under Section 45A?', 'Fakta manakah digunakan dalam buku untuk mengenal pasti kesalahan di bawah Seksyen 45A?', '["The driver has no valid licence","The vehicle has no insurance cover","Alcohol exceeds the prescribed limit","The car enters a restricted road"]'::jsonb, '["Pemandu tiada lesen yang sah","Kenderaan tiada perlindungan insurans","Alkohol melebihi had ditetapkan","Kereta memasuki jalan terhad"]'::jsonb, 2, 'The offence table lists driving or being in charge of a motor vehicle with alcohol above the prescribed limit.', 'Jadual menyenaraikan memandu atau menjaga kenderaan motor dengan kepekatan alkohol melebihi had yang ditetapkan.', NULL, 'KPP Kelas DA Automatik, PDF 163'),
  ('0473f3eb-da5d-55bc-bb69-beeb1d3cc5eb'::uuid, 'traffic-rules', 'quiz-b-3', 14, 'Which activity does the curriculum list under Section 81?', 'Aktiviti manakah disenaraikan di bawah Seksyen 81 dalam kurikulum?', '["Ignoring a marked no-entry sign","Passing another car on the left","Blocking a pedestrian crossing","Joining an unapproved road race"]'::jsonb, '["Mengabaikan tanda dilarang masuk","Memotong kereta lain di sebelah kiri","Menghalang lintasan pejalan kaki","Menyertai perlumbaan jalan tanpa kebenaran"]'::jsonb, 3, 'The offence table includes both organising and taking part in an unauthorised road race.', 'Jadual kesalahan merangkumi kedua-dua menaja dan menyertai perlumbaan jalan raya tanpa kebenaran.', NULL, 'KPP Kelas DA Automatik, PDF 164'),
  ('4d6817ad-98d9-5c82-83d3-0df830244be6'::uuid, 'traffic-rules', 'quiz-b-3', 15, 'Which conduct does the curriculum list under Section 79(2)?', 'Perbuatan manakah disenaraikan di bawah Seksyen 79(2) dalam kurikulum?', '["Ignoring a traffic sign","Parking at a bus stop","Driving an uninsured car","Failing to stop at a roadblock"]'::jsonb, '["Ingkar papan tanda lalu lintas","Meletak kereta di perhentian bas","Memandu kereta tanpa insurans","Gagal berhenti di sekatan jalan"]'::jsonb, 0, 'The offence table identifies failing to obey traffic signs. It lists roadblocks and pedestrian crossing offences separately.', 'Jadual menyenaraikan kegagalan mematuhi isyarat lalu lintas. Kesalahan sekatan jalan dan lintasan pejalan kaki disenaraikan berasingan.', NULL, 'KPP Kelas DA Automatik, PDF 164'),
  ('e1955d6b-1c9c-573b-abe5-0109b3f0d0f9'::uuid, 'traffic-rules', 'quiz-b-3', 16, 'You want to return a missed call while driving. When should you use the phone?', 'Anda ingin membalas panggilan yang terlepas ketika memandu. Bilakah anda patut menggunakan telefon?', '["After parking safely","While stopped at a traffic light","While crawling in a queue","While another driver is passing"]'::jsonb, '["Selepas parkir dengan selamat","Semasa berhenti di lampu isyarat","Semasa bergerak perlahan dalam kesesakan","Semasa dipotong oleh pemandu lain"]'::jsonb, 0, 'Using a phone can draw your attention away from the road.', 'Penggunaan telefon boleh mengalihkan perhatian daripada jalan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 78'),
  ('50f47572-5e5e-5183-93d6-bb813dba0c00'::uuid, 'traffic-rules', 'quiz-b-3', 17, 'Your car breaks down on an expressway. Where should you pull over if you can still steer?', 'Kereta anda rosak di lebuh raya. Di manakah anda patut berhenti jika masih boleh mengawal stereng?', '["In the emergency lane","In the left travel lane","In the right travel lane","In the central median"]'::jsonb, '["Di lorong kecemasan","Di lorong perjalanan kiri","Di lorong perjalanan kanan","Di pembahagi jalan"]'::jsonb, 0, 'Signal left, stop in the emergency lane and switch on your hazard lights.', 'Beri isyarat kiri, berhenti di lorong kecemasan dan nyalakan lampu kecemasan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 128'),
  ('db45ce2c-d419-5c05-b528-119d980d9ed8'::uuid, 'traffic-rules', 'quiz-b-3', 18, 'Which side should you normally use on a two-way road in Malaysia?', 'Bahagian manakah yang biasanya digunakan di jalan dua hala di Malaysia?', '["The left side","The right side","The clearer side","The wider side"]'::jsonb, '["Bahagian kiri","Bahagian kanan","Bahagian lebih lapang","Bahagian lebih lebar"]'::jsonb, 0, 'The normal rule is to keep to the left side of the road.', 'Peraturan biasa ialah memandu di sebelah kiri jalan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 165'),
  ('82949816-7a88-5d6a-bcc6-547c346c86e4'::uuid, 'traffic-rules', 'quiz-b-3', 19, 'On an open two-way road, which side should you move to when it is safe to pass a slower vehicle?', 'Di jalan dua hala, di sebelah manakah anda patut bergerak apabila selamat untuk memotong kenderaan yang lebih perlahan?', '["To its right","To its left","To the road shoulder","To the centre without passing"]'::jsonb, '["Ke sebelah kanannya","Ke sebelah kirinya","Ke bahu jalan","Ke tengah tanpa memotong"]'::jsonb, 0, 'The textbook’s overtaking routine calls for checking ahead, behind and beside you before moving to the right.', 'Rutin memotong dalam buku mengarahkan anda menyemak hadapan, belakang dan sisi sebelum bergerak ke kanan.', NULL, 'KPP Kelas DA Automatik, PDF 261'),
  ('542f729c-9ff6-5a5a-82de-ef4abb673cc4'::uuid, 'traffic-rules', 'quiz-b-3', 20, 'After stopping at a crash, when must the driver report it to the police under the rule in the curriculum?', 'Selepas berhenti di tempat kemalangan, bilakah pemandu perlu melaporkannya kepada polis mengikut peraturan dalam kurikulum?', '["Within 48 hours","Within 24 hours","Within 72 hours","Within 7 days"]'::jsonb, '["Dalam masa 48 jam","Dalam masa 24 jam","Dalam masa 72 jam","Dalam masa 7 hari"]'::jsonb, 1, 'The rule lists two duties after a crash: stop and report to the police within 24 hours.', 'Peraturan menyenaraikan dua kewajipan selepas kemalangan: berhenti dan lapor kepada polis dalam masa 24 jam.', NULL, 'KPP Kelas DA Automatik, PDF 164'),
  ('6c4a027f-5d26-590f-9ce1-6592e87e3575'::uuid, 'traffic-rules', 'quiz-b-3', 21, 'A uniformed officer directs you to the roadside. What is the correct response?', 'Seorang pegawai beruniform mengarahkan anda ke tepi jalan. Apakah tindakan yang betul?', '["Slow down and wait for a second signal","Continue to the next staffed checkpoint","Stop where it is safe as directed","Keep going unless other drivers stop"]'::jsonb, '["Perlahankan kenderaan dan tunggu isyarat kedua","Teruskan ke pusat pemeriksaan seterusnya","Berhenti dengan selamat seperti diarahkan","Teruskan kecuali pemandu lain berhenti"]'::jsonb, 2, 'The offence table lists failure to stop when directed by a uniformed officer. Follow the direction and stop safely.', 'Jadual menyenaraikan kesalahan gagal berhenti apabila diarahkan oleh pegawai beruniform. Patuhi arahan dan berhenti dengan selamat.', NULL, 'KPP Kelas DA Automatik, PDF 164'),
  ('fb00d016-563e-5077-ba7d-17c438ca0dd7'::uuid, 'traffic-rules', 'quiz-b-3', 22, 'Your driving licence expired yesterday. What should you do before driving again?', 'Lesen memandu anda tamat tempoh semalam. Apakah yang perlu dibuat sebelum memandu semula?', '["Keep the old licence with you","Carry the vehicle registration","Book a renewal for later","Renew the driving licence"]'::jsonb, '["Bawa lesen lama bersama","Bawa pendaftaran kenderaan","Tempah pembaharuan untuk kemudian","Perbaharui lesen memandu"]'::jsonb, 3, 'The licensing table lists driving on an expired licence as an offence. Renew it before driving.', 'Jadual pelesenan menyenaraikan memandu dengan lesen tamat tempoh sebagai kesalahan. Perbaharui lesen sebelum memandu.', NULL, 'KPP Kelas DA Automatik, PDF 161'),
  ('934d13f0-c2ac-5861-b550-cf569bd37053'::uuid, 'traffic-rules', 'quiz-b-3', 23, 'The handbook lists using a car without insurance as an offence. What kind of cover does it refer to?', 'Buku panduan menyenaraikan penggunaan kereta tanpa insurans sebagai kesalahan. Apakah jenis perlindungan yang dirujuk?', '["Cover for third-party risks","Cover for the driver’s injuries","Cover for damage to your own car","Cover for theft of your own car"]'::jsonb, '["Perlindungan risiko pihak ketiga","Perlindungan kecederaan pemandu","Perlindungan kerosakan kereta sendiri","Perlindungan kecurian kereta sendiri"]'::jsonb, 0, 'The handbook lists driving without third-party risk cover as an offence.', 'Buku panduan menyenaraikan pemanduan tanpa perlindungan risiko pihak ketiga sebagai kesalahan.', NULL, 'KPP Kelas DA Automatik, PDF 168'),
  ('1c139cfe-05b2-58ed-adee-11cc72f449a8'::uuid, 'traffic-rules', 'quiz-b-3', 24, 'A sign prohibits micromobility vehicles. Which of these vehicles falls in that category?', 'Papan tanda melarang kenderaan mikromobiliti. Kenderaan manakah termasuk dalam kategori itu?', '["An electric kick scooter","An electric passenger car","An electric delivery van","An electric motorcycle"]'::jsonb, '["Skuter tendang elektrik","Kereta penumpang elektrik","Van penghantaran elektrik","Motosikal elektrik"]'::jsonb, 0, 'An e-scooter is a micromobility vehicle. Its rider must use an allowed route.', 'Skuter elektrik ialah kenderaan mikromobiliti. Penunggang mesti menggunakan laluan yang dibenarkan.', NULL, 'KPP General, PDF page 58'),
  ('00f68580-d2f0-519b-a651-5fb148b7a799'::uuid, 'traffic-rules', 'quiz-b-3', 25, 'At 20 km/h, the braking distance is 3 m and the total stopping distance is 9 m. How far does the car travel before braking?', 'Pada 20 km/j, jarak membrek ialah 3 m dan jumlah jarak berhenti ialah 9 m. Berapakah jarak yang dilalui sebelum membrek?', '["6 m","3 m","9 m","12 m"]'::jsonb, '["6 m","3 m","9 m","12 m"]'::jsonb, 0, 'Subtract braking distance from total stopping distance: 9 m minus 3 m is 6 m.', 'Tolak jarak membrek daripada jumlah jarak berhenti: 9 m tolak 3 m ialah 6 m.', NULL, 'KPP Automatic Driving Curriculum, PDF page 264'),
  ('1532b093-0e9b-59cb-8732-12e2022fd5ae'::uuid, 'safety-principles', 'quiz-c-d-1', 1, 'What is the minimum age to apply for a motorcycle licence?', 'Berapakah umur minimum untuk memohon lesen motosikal?', '["15 years","17 years","16 years","18 years"]'::jsonb, '["15 tahun","17 tahun","16 tahun","18 tahun"]'::jsonb, 2, 'The curriculum lists 16 as the minimum age for a motorcycle licence.', 'Kurikulum menetapkan umur minimum 16 tahun bagi permohonan lesen motosikal.', NULL, 'KPP General, PDF 9'),
  ('87b76e13-c358-52c8-851b-a03f4325a9e5'::uuid, 'safety-principles', 'quiz-c-d-1', 2, 'What is the minimum age for the motorcar licence classes?', 'Berapakah umur minimum bagi kelas lesen motokar?', '["16 years","18 years","17 years","21 years"]'::jsonb, '["16 tahun","18 tahun","17 tahun","21 tahun"]'::jsonb, 2, 'Applicants for a motorcar licence must be at least 17 years old.', 'Pemohon lesen motokar mestilah berumur sekurang-kurangnya 17 tahun.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('15a1188f-b504-51b8-91ed-fd3b0adb5bcb'::uuid, 'safety-principles', 'quiz-c-d-1', 3, 'What kind of vehicle does the Class E classification cover in this textbook?', 'Apakah jenis kenderaan bagi Kelas E dalam buku ini?', '["A car without a clutch pedal","An adapted motorcycle","A light tracked tractor","A heavy motor vehicle"]'::jsonb, '["Motokar tanpa pedal cekam","Motosikal yang diubah suai","Traktor ringan berantai","Motokar berat"]'::jsonb, 3, 'Class E is listed for heavy motor vehicles over 7,500 kg unladen.', 'Kelas E disenaraikan untuk motokar berat dengan berat tanpa muatan melebihi 7,500 kg.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('4eca0a4c-2ff5-5525-ba65-ce90b5c7c4cc'::uuid, 'safety-principles', 'quiz-c-d-1', 4, 'Which licence category does the handbook list for carrying goods by motorcycle?', 'Kategori lesen manakah disenaraikan oleh buku panduan untuk membawa barangan dengan motosikal?', '["GDL","PSV","Conductor licence","No vocational endorsement"]'::jsonb, '["GDL","PSV","Lesen konduktor","Tiada lesen vokasional"]'::jsonb, 0, 'The vocational categories list goods vehicle licensing, including motorcycles, under GDL.', 'Kategori lesen vokasional menyenaraikan motosikal barangan di bawah lesen GDL.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('7c6c4b24-573d-5060-98dd-c056de095332'::uuid, 'safety-principles', 'quiz-c-d-1', 5, 'Which vehicle does a Class A1 licence cover?', 'Kenderaan manakah yang termasuk dalam lesen Kelas A1?', '["An adapted motorcycle","A light goods vehicle","An adapted motorcar","A three-wheel motorcycle"]'::jsonb, '["Motosikal yang diubah suai","Kenderaan barangan ringan","Motokar yang diubah suai","Motosikal tiga roda"]'::jsonb, 2, 'Class A1 covers adapted motorcars for drivers with disabilities. Class A covers adapted motorcycles.', 'Kelas A1 meliputi motokar yang diubah suai untuk pemandu orang kurang upaya. Kelas A meliputi motosikal yang diubah suai.', NULL, 'KPP Kelas DA Automatik, PDF 17'),
  ('5a6a1e81-44e3-5a1e-9f85-5ae82d4eddc8'::uuid, 'safety-principles', 'quiz-c-d-1', 6, 'What is the engine capacity limit for a Class B2 motorcycle?', 'Berapakah had kapasiti enjin bagi motosikal Kelas B2?', '["150 cc","300 cc","500 cc","250 cc"]'::jsonb, '["150 cc","300 cc","500 cc","250 cc"]'::jsonb, 3, 'Class B2 covers personal motorcycles up to 250 cc.', 'Kelas B2 meliputi motosikal persendirian sehingga 250 cc.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('cc2194b4-08c4-5d6b-8a98-859053a4622d'::uuid, 'safety-principles', 'quiz-c-d-1', 7, 'What is the maximum unladen weight for a Class D or DA motorcar?', 'Berapakah berat tanpa muatan maksimum bagi motokar Kelas D atau DA?', '["2500 kg","5000 kg","7500 kg","3500 kg"]'::jsonb, '["2500 kg","5000 kg","7500 kg","3500 kg"]'::jsonb, 3, 'The Class D and DA classifications both have an unladen weight limit of 3,500 kg.', 'Kelas D dan DA mempunyai had berat tanpa muatan sebanyak 3,500 kg.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('c09e9bbb-24c4-50d8-b46d-6693d9139416'::uuid, 'safety-principles', 'quiz-c-d-1', 8, 'Which group of vehicles is covered by Classes F, G, H and I?', 'Kumpulan kenderaan manakah yang diliputi oleh Kelas F, G, H dan I?', '["Lorries and articulated trailers","Tractors and mobile machinery","Buses and passenger vans","Motorcars and small vans"]'::jsonb, '["Lori dan treler bersendi","Traktor dan jentera bergerak","Bas dan van penumpang","Motokar dan van kecil"]'::jsonb, 1, 'These classes cover tractors and mobile machinery. They distinguish wheels from tracks and lighter from heavier vehicles.', 'Kelas ini meliputi traktor dan jentera bergerak. Kelasnya dibezakan mengikut roda atau rantai serta berat kenderaan.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('503ce92d-9422-5df1-afd6-e2fec6992fdf'::uuid, 'safety-principles', 'quiz-c-d-1', 9, 'How long is the KPP01 course for this class before the Part I test?', 'Berapa lamakah kursus KPP01 bagi kelas ini sebelum Ujian Bahagian I?', '["4 hours","6 hours","5 hours","8 hours"]'::jsonb, '["4 jam","6 jam","5 jam","8 jam"]'::jsonb, 1, 'Candidates attend six hours of KPP01 before taking the Part I test.', 'Calon mengikuti KPP01 selama enam jam sebelum menduduki Ujian Bahagian I.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('08c36aee-c226-5461-8342-d42e7e50a185'::uuid, 'safety-principles', 'quiz-c-d-1', 10, 'Which two environments are covered by the car practical test?', 'Apakah dua persekitaran yang diliputi oleh ujian amali kereta?', '["Circuit and public road","Circuit and computer room","Public road and classroom","Computer room and classroom"]'::jsonb, '["Litar dan jalan raya","Litar dan bilik komputer","Jalan raya dan bilik darjah","Bilik komputer dan bilik darjah"]'::jsonb, 0, 'The car practical test covers the circuit in Part II and the road in Part III.', 'Ujian amali kereta meliputi litar dalam Bahagian II dan jalan raya dalam Bahagian III.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('23b9ebe7-9c75-5c34-a488-cf2fd6c06b51'::uuid, 'safety-principles', 'quiz-c-d-1', 11, 'For how long is a Part I pass valid?', 'Berapa lamakah keputusan lulus Ujian Bahagian I sah?', '["6 months","18 months","24 months","12 months"]'::jsonb, '["6 bulan","18 bulan","24 bulan","12 bulan"]'::jsonb, 3, 'The validity period starts on the day the candidate passes and lasts one year.', 'Tempoh sah bermula pada tarikh calon lulus dan berakhir selepas setahun.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('71fac706-76b7-598d-8c6d-651c46d4a629'::uuid, 'safety-principles', 'quiz-c-d-1', 12, 'What is the left-to-right pedal order in a three-pedal manual car?', 'Apakah susunan pedal dari kiri ke kanan dalam kereta manual tiga pedal?', '["Clutch, brake, accelerator","Brake, clutch, accelerator","Clutch, accelerator, brake","Accelerator, brake, clutch"]'::jsonb, '["Cekam, brek, pemecut","Brek, cekam, pemecut","Cekam, pemecut, brek","Pemecut, brek, cekam"]'::jsonb, 0, 'The diagram shows the clutch on the left, brake in the middle, and accelerator on the right.', 'Rajah menunjukkan pedal cekam di kiri, brek di tengah dan pemecut di kanan.', NULL, 'KPP Kelas D Manual, PDF 218'),
  ('be3d3ad4-9ec2-51db-a409-7fa135906c99'::uuid, 'safety-principles', 'quiz-c-d-1', 13, 'What happens to engine power going to the gearbox when you press the clutch fully?', 'Apakah yang berlaku kepada kuasa enjin ke kotak gear apabila pedal cekam ditekan sepenuhnya?', '["Power is increased","Power is disconnected","Power stays connected","Power changes direction"]'::jsonb, '["Kuasa bertambah","Kuasa diputuskan","Kuasa kekal bersambung","Kuasa bertukar arah"]'::jsonb, 1, 'Pressing the clutch with the left foot disconnects engine power from the gearbox. Releasing it reconnects the power.', 'Menekan cekam dengan kaki kiri memutuskan kuasa enjin ke kotak gear. Melepaskannya menyambungkan semula kuasa.', NULL, 'KPP Kelas D Manual, PDF 215'),
  ('a6e4d877-1ba3-5739-9505-6c90c94cee37'::uuid, 'safety-principles', 'quiz-c-d-1', 14, 'What engine sound can indicate that you have reached the clutch biting point while moving off?', 'Apakah perubahan bunyi enjin yang menunjukkan titik pergerakan cekam ketika mula bergerak?', '["The engine speeds up slightly","The engine holds the same note","The engine slows slightly","The engine goes completely quiet"]'::jsonb, '["Putaran enjin mula meningkat","Bunyi enjin kekal sama","Putaran enjin mula perlahan","Bunyi enjin hilang sepenuhnya"]'::jsonb, 2, 'Raise the clutch slowly with slight accelerator pressure. The book says a drop in engine speed indicates the biting point.', 'Angkat pedal cekam perlahan-lahan sambil menekan pemecut sedikit. Buku menyatakan putaran enjin yang mula perlahan menandakan titik pergerakan.', NULL, 'KPP Kelas D Manual, PDF 216'),
  ('a18b1396-757a-51e0-92f3-df1a1d6b009f'::uuid, 'safety-principles', 'quiz-c-d-1', 15, 'How should you raise the clutch pedal to pull away smoothly?', 'Bagaimanakah pedal cekam perlu diangkat supaya kereta mula bergerak dengan lancar?', '["Raise it in one quick motion","Raise it halfway at once","Pump it up and down","Raise it gradually"]'::jsonb, '["Angkat dengan satu gerakan cepat","Angkat separuh dengan segera","Pam ke atas dan ke bawah","Angkat secara beransur-ansur"]'::jsonb, 3, 'With first gear selected and slight accelerator pressure, raise the clutch gradually to the biting point.', 'Dengan gear satu dipilih dan pemecut ditekan sedikit, angkat pedal cekam secara beransur-ansur hingga titik pergerakan.', NULL, 'KPP Kelas D Manual, PDF 216'),
  ('482626c7-fd1f-5a5c-9213-8a4b723195ff'::uuid, 'safety-principles', 'quiz-c-d-2', 1, 'How are the practical training hours split in this curriculum?', 'Bagaimanakah jam latihan amali dibahagikan dalam kurikulum ini?', '["10 circuit, 5½ road","6 circuit, 10 road","5½ circuit, 10 road","5½ circuit, 8 road"]'::jsonb, '["10 litar, 5½ jalan raya","6 litar, 10 jalan raya","5½ litar, 10 jalan raya","5½ litar, 8 jalan raya"]'::jsonb, 2, 'This curriculum lists five and a half hours of circuit training and ten hours of road training.', 'Kurikulum ini menyenaraikan lima jam setengah di litar dan sepuluh jam di jalan raya.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('032d9db4-6ac2-50ee-9c6d-536112a34828'::uuid, 'safety-principles', 'quiz-c-d-2', 2, 'Your learner licence is still valid. How long must you have held it before you can take the practical tests in this curriculum?', 'Lesen belajar anda masih sah. Berapa lamakah lesen itu mesti dipegang sebelum menduduki ujian amali mengikut kurikulum ini?', '["More than 14 days","More than 21 days","More than 60 days","More than 30 days"]'::jsonb, '["Lebih daripada 14 hari","Lebih daripada 21 hari","Lebih daripada 60 hari","Lebih daripada 30 hari"]'::jsonb, 3, 'Before Parts II and III, the learner licence must still be valid and more than 30 days must have passed since issue.', 'Sebelum Ujian Bahagian II dan III, lesen belajar mesti masih sah dan lebih daripada 30 hari telah berlalu sejak tarikh ia dikeluarkan.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('367dbd33-f423-5634-9920-f717497cadb0'::uuid, 'safety-principles', 'quiz-c-d-2', 3, 'What is the maximum total validity of a learner licence from its first issue?', 'Berapakah tempoh sah keseluruhan maksimum lesen belajar memandu dari tarikh pertama dikeluarkan?', '["12 months","18 months","36 months","24 months"]'::jsonb, '["12 bulan","18 bulan","36 bulan","24 bulan"]'::jsonb, 3, 'Learner licences can be renewed for three or six months at a time, up to two years from the first issue.', 'Lesen belajar memandu boleh diperbaharui untuk tiga atau enam bulan pada satu masa, sehingga dua tahun dari tarikh pertama dikeluarkan.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('ca5db830-332f-5f02-ad61-8949ea5ccf17'::uuid, 'safety-principles', 'quiz-c-d-2', 4, 'Who must accompany a learner driving a motorcar on an L licence?', 'Siapakah yang mesti menemani pemegang lesen L semasa memandu motokar?', '["Any competent licence holder","A driving institute instructor","A parent or guardian","A probationary licence holder"]'::jsonb, '["Mana-mana pemegang lesen kompeten","Pengajar institut memandu","Ibu bapa atau penjaga","Pemegang lesen percubaan"]'::jsonb, 1, 'A learner motorcar driver must drive with a driving institute instructor.', 'Pemegang lesen L bagi motokar mesti memandu bersama pengajar institut memandu.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('4c3ba8ae-3188-5576-a108-70e026925e53'::uuid, 'safety-principles', 'quiz-c-d-2', 5, 'Where are L signs displayed on a learner’s motorcar?', 'Di manakah tanda L dipamerkan pada motokar pelajar?', '["At the front and left","At the front and rear","At the rear and right","At the left and right"]'::jsonb, '["Di hadapan dan kiri","Di hadapan dan belakang","Di belakang dan kanan","Di kiri dan kanan"]'::jsonb, 1, 'A learner motorcar displays an L sign at the front and rear.', 'Motokar pelajar mempamerkan tanda L di bahagian hadapan dan belakang.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('5a837190-b917-5df6-9bb9-60a4f7823bc5'::uuid, 'safety-principles', 'quiz-c-d-2', 6, 'How soon after passing the practical test should you apply for a probationary licence?', 'Dalam tempoh berapakah selepas lulus ujian praktikal anda perlu memohon lesen memandu percubaan?', '["6 months","18 months","12 months","24 months"]'::jsonb, '["6 bulan","18 bulan","12 bulan","24 bulan"]'::jsonb, 2, 'The practical test pass is valid for one year. Apply for the probationary licence within that period.', 'Keputusan lulus ujian praktikal sah selama setahun. Mohon lesen memandu percubaan dalam tempoh itu.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('b9670e16-85cf-5b76-8bcf-26021bc747e6'::uuid, 'safety-principles', 'quiz-c-d-2', 7, 'How long is the probation period for a new probationary licence?', 'Berapa lamakah tempoh percubaan bagi lesen memandu percubaan yang baharu?', '["12 months","18 months","36 months","24 months"]'::jsonb, '["12 bulan","18 bulan","36 bulan","24 bulan"]'::jsonb, 3, 'The probationary licence gives new drivers two years to build experience under probation conditions.', 'Lesen memandu percubaan memberi pemandu baharu dua tahun untuk menimba pengalaman di bawah syarat percubaan.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('1b4d817d-002f-5fbf-8c8d-b913fb7676c6'::uuid, 'safety-principles', 'quiz-c-d-2', 8, 'Where should you display the P signs on a motorcar?', 'Di manakah tanda P perlu dipamerkan pada motokar?', '["Upper right on both windscreens","Upper left on both windscreens","Lower left on both windscreens","Lower right on both windscreens"]'::jsonb, '["Kanan atas pada kedua-dua cermin","Kiri atas pada kedua-dua cermin","Kiri bawah pada kedua-dua cermin","Kanan bawah pada kedua-dua cermin"]'::jsonb, 1, 'Display a P sign at the upper left corner of both the front and rear windscreens.', 'Pamerkan tanda P di penjuru kiri atas cermin hadapan dan belakang.', NULL, 'KPP Kelas DA Automatik, PDF 21'),
  ('a147cc55-afa1-548b-91cf-bf55d35b7058'::uuid, 'safety-principles', 'quiz-c-d-2', 9, 'What alcohol level does this curriculum specify for a P licence holder while driving?', 'Apakah kadar alkohol yang ditetapkan dalam kurikulum ini bagi pemegang lesen P semasa memandu?', '["0.02%","0.05%","0.00%","0.08%"]'::jsonb, '["0.02%","0.05%","0.00%","0.08%"]'::jsonb, 2, 'The probationary licence conditions specify 0.00% alcohol in breath, blood and urine.', 'Syarat lesen percubaan menetapkan 0.00% alkohol dalam nafas, darah dan air kencing.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('9203c254-a475-57bb-bf1f-e5ecad90f947'::uuid, 'safety-principles', 'quiz-c-d-2', 10, 'How long after a probationary licence expires can you apply to convert it to a competent licence?', 'Berapa lamakah selepas lesen percubaan tamat tempoh anda boleh memohon pertukaran kepada lesen kompeten?', '["3 months","6 months","12 months","24 months"]'::jsonb, '["3 bulan","6 bulan","12 bulan","24 bulan"]'::jsonb, 2, 'Apply within one year of the probationary licence expiry date.', 'Buat permohonan dalam tempoh setahun daripada tarikh tamat lesen percubaan.', NULL, 'KPP Kelas DA Automatik, PDF 22'),
  ('0d983059-ac29-516c-9a63-680dde825282'::uuid, 'safety-principles', 'quiz-c-d-2', 11, 'How long after expiry does this textbook list for automatic cancellation of a competent licence?', 'Berapa lamakah selepas tamat tempoh lesen kompeten terbatal secara automatik mengikut buku ini?', '["More than 1 year","More than 2 years","More than 5 years","More than 3 years"]'::jsonb, '["Melebihi 1 tahun","Melebihi 2 tahun","Melebihi 5 tahun","Melebihi 3 tahun"]'::jsonb, 3, 'The table lists cancellation once a competent licence has remained expired for more than three years.', 'Jadual menyenaraikan pembatalan apabila lesen kompeten telah tamat tempoh melebihi tiga tahun.', NULL, 'KPP Kelas DA Automatik, PDF 25'),
  ('2fc35aef-0cbf-5085-ac34-fe669a226b23'::uuid, 'safety-principles', 'quiz-c-d-2', 12, 'How far should you press the clutch before changing gear?', 'Sejauh manakah pedal cekam perlu ditekan sebelum menukar gear?', '["All the way down","About halfway down","Just past the free play","Only to the biting point"]'::jsonb, '["Tekan sepenuhnya","Tekan kira-kira separuh","Tekan sedikit melepasi ruang bebas","Tekan hingga titik pergerakan"]'::jsonb, 0, 'Press the clutch all the way down before shifting, then release it to reconnect power.', 'Tekan cekam sepenuhnya sebelum menukar gear, kemudian lepaskan untuk menyambungkan kuasa semula.', NULL, 'KPP Kelas D Manual, PDF 215'),
  ('dd3ef893-5cfc-55a1-a8eb-5ed50ca701c1'::uuid, 'safety-principles', 'quiz-c-d-2', 13, 'How do you check that the gear lever is in Neutral before starting a manual car?', 'Bagaimanakah anda memastikan tombol gear dalam kedudukan bebas sebelum menghidupkan kereta manual?', '["Move it forward and back","Move it side to side","Push it toward first gear","Pull it toward reverse"]'::jsonb, '["Gerakkan ke depan dan belakang","Gerakkan ke kiri dan kanan","Tolak ke arah gear satu","Tarik ke arah gear undur"]'::jsonb, 1, 'In Neutral, the lever moves freely from side to side.', 'Dalam kedudukan bebas, tombol gear boleh bergerak dengan bebas ke kiri dan ke kanan.', NULL, 'KPP Kelas D Manual, PDF 200'),
  ('411409cc-ac49-5a1e-84df-2c6df832a02e'::uuid, 'safety-principles', 'quiz-c-d-2', 14, 'A manual car is stationary in neutral. Which pedal action prepares you to select reverse?', 'Sebuah kereta manual berhenti dalam gear neutral. Tindakan pada pedal manakah yang menyediakan anda untuk memilih gear undur?', '["Press and hold the clutch","Press and hold the brake","Release the clutch slowly","Press the accelerator lightly"]'::jsonb, '["Tekan dan tahan pedal cekam","Tekan dan tahan pedal brek","Lepaskan cekam perlahan-lahan","Tekan sedikit pedal pemecut"]'::jsonb, 0, 'Start in neutral and press the clutch fully before selecting reverse.', 'Mulakan pada gear neutral dan tekan pedal cekam sepenuhnya sebelum memilih gear undur.', NULL, 'KPP Kelas D Manual, PDF 214'),
  ('fcf4adf9-c85d-5336-b379-90a786d85441'::uuid, 'safety-principles', 'quiz-c-d-2', 15, 'Which gear does the manual curriculum use to start moving forward from a standstill?', 'Gear manakah yang digunakan dalam kurikulum manual untuk mula bergerak ke hadapan dari keadaan berhenti?', '["Second gear","Third gear","Fourth gear","First gear"]'::jsonb, '["Gear dua","Gear tiga","Gear empat","Gear satu"]'::jsonb, 3, 'Select first gear before balancing the clutch and accelerator to move off.', 'Pilih gear satu sebelum mengimbangi cekam dan pemecut untuk mula bergerak.', NULL, 'KPP Kelas D Manual, PDF 216'),
  ('bf4e1555-926a-5741-aa09-fe70164f6dd8'::uuid, 'safety-principles', 'quiz-c-d-3', 1, 'Which licence follows the probationary licence in the curriculum’s licensing process?', 'Lesen manakah menyusuli lesen percubaan dalam proses pelesenan yang diterangkan?', '["Learner’s driving licence","Competent driving licence","Vocational driving licence","International driving permit"]'::jsonb, '["Lesen belajar memandu","Lesen memandu kompeten","Lesen memandu vokasional","Permit memandu antarabangsa"]'::jsonb, 1, 'Drivers who complete probation apply to change from a probationary to a competent driving licence.', 'Pemandu yang menamatkan tempoh percubaan memohon pertukaran daripada lesen percubaan kepada lesen kompeten.', NULL, 'KPP Kelas DA Automatik, PDF 22'),
  ('37f51327-d949-53d9-bf1c-346e75f1599a'::uuid, 'safety-principles', 'quiz-c-d-3', 2, 'Under this curriculum, what can a driver skip when adding a class from the same licence group?', 'Mengikut kurikulum ini, apakah yang boleh dikecualikan apabila menambah kelas daripada kumpulan lesen yang sama?', '["The practical training and tests","The practical tests only","The road training only","The theory course and test"]'::jsonb, '["Latihan dan ujian amali","Ujian amali sahaja","Latihan jalan raya sahaja","Kursus dan ujian teori"]'::jsonb, 3, 'The same-group exemption covers the KPP01 course and Part I theory test. Practical training and tests still apply.', 'Pengecualian bagi kumpulan yang sama meliputi kursus KPP01 dan ujian teori Bahagian I. Latihan dan ujian amali masih diperlukan.', NULL, 'KPP Kelas DA Automatik, PDF 14'),
  ('7bad7ac8-836a-5bb8-8a57-bbc78a58b573'::uuid, 'safety-principles', 'quiz-c-d-3', 3, 'Which licence category covers driving a bus with fare-paying passengers?', 'Kategori lesen manakah meliputi pemanduan bas yang membawa penumpang berbayar?', '["PSV","GDL","CDL alone","PDL alone"]'::jsonb, '["PSV","GDL","CDL sahaja","PDL sahaja"]'::jsonb, 0, 'PSV covers public service vehicles, including buses. GDL is for goods vehicles.', 'PSV meliputi kenderaan perkhidmatan awam termasuk bas. GDL ialah lesen untuk kenderaan barangan.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('01cbf84c-a04c-5f7e-bbf4-5b5f15240c92'::uuid, 'safety-principles', 'quiz-c-d-3', 4, 'Which specific vision check appears in the handbook’s eligibility requirements?', 'Pemeriksaan penglihatan khusus manakah dinyatakan dalam syarat kelayakan buku panduan?', '["Colour vision","Peripheral vision","Night vision","Depth perception"]'::jsonb, '["Penglihatan warna","Penglihatan sisi","Penglihatan malam","Persepsi kedalaman"]'::jsonb, 0, 'Eligibility includes being able to see ahead for 23 metres and not being colour blind.', 'Kelayakan termasuk boleh melihat ke hadapan sejauh 23 meter dan tidak buta warna.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('a418d181-ae9a-5506-80ac-40eb01f4eed6'::uuid, 'safety-principles', 'quiz-c-d-3', 5, 'What does the name KEJARA stand for?', 'Apakah nama penuh KEJARA?', '["Sistem Kelayakan Jalan Raya","Sistem Keselamatan Jalan Raya","Sistem Kesalahan Jalan Raya","Sistem Kawalan Jalan Raya"]'::jsonb, '["Sistem Kelayakan Jalan Raya","Sistem Keselamatan Jalan Raya","Sistem Kesalahan Jalan Raya","Sistem Kawalan Jalan Raya"]'::jsonb, 1, 'KEJARA is short for Sistem Keselamatan Jalan Raya. It assigns demerit points for scheduled offences.', 'KEJARA ialah singkatan bagi Sistem Keselamatan Jalan Raya. Sistem ini memberikan mata demerit bagi kesalahan terjadual.', NULL, 'KPP General, PDF 93'),
  ('6b09e828-9940-5fde-8859-d94a8b9d0013'::uuid, 'safety-principles', 'quiz-c-d-3', 6, 'What does this curriculum say happens to a P licence at 20 demerit points?', 'Apakah kesan 20 mata demerit pada lesen P mengikut kurikulum ini?', '["The licence is suspended","A warning is issued","The licence is cancelled","A course is required"]'::jsonb, '["Lesen digantung","Amaran dikeluarkan","Lesen dibatalkan","Kursus diwajibkan"]'::jsonb, 2, 'The P licence conditions state that reaching 20 points or more results in cancellation.', 'Syarat lesen P menyatakan bahawa 20 mata atau lebih mengakibatkan lesen dibatalkan.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('79c8a23d-76fc-5412-b3ff-85ef5fc6ce5d'::uuid, 'safety-principles', 'quiz-c-d-3', 7, 'What is the first action shown in the KEJARA schedule when a competent licence holder reaches 20 points?', 'Apakah tindakan pertama dalam jadual KEJARA apabila pemegang lesen kompeten mencapai 20 mata?', '["A suspension","A cancellation","A course referral","A warning"]'::jsonb, '["Penggantungan","Pembatalan","Rujukan kursus","Amaran"]'::jsonb, 3, 'The first threshold shown in the schedule results in a warning.', 'Ambang kali pertama dalam jadual ini membawa kepada amaran.', NULL, 'KPP General, PDF 95'),
  ('896ad58f-d6e5-5456-a45c-28cf062f40f7'::uuid, 'safety-principles', 'quiz-c-d-3', 8, 'A competent licence holder has already received one KEJARA warning and reaches another 20 points. What suspension range applies in the handbook table?', 'Pemegang lesen kompeten telah menerima satu amaran KEJARA dan mencapai 20 mata lagi. Apakah julat penggantungan dalam jadual buku panduan?', '["6–8 months","4–6 months","8–10 months","10–12 months"]'::jsonb, '["6–8 bulan","4–6 bulan","8–10 bulan","10–12 bulan"]'::jsonb, 0, 'The table shows a first suspension of six to eight months for the second threshold.', 'Jadual menunjukkan penggantungan pertama selama enam hingga lapan bulan bagi ambang kali kedua.', NULL, 'KPP General, PDF 95'),
  ('447f0a7e-3ccb-533a-912c-f6fde03a5115'::uuid, 'safety-principles', 'quiz-c-d-3', 9, 'A competent licence holder receives a second suspension under the handbook KEJARA schedule. Which range applies?', 'Pemegang lesen kompeten menerima penggantungan kali kedua mengikut jadual KEJARA. Apakah julatnya?', '["8–10 months","4–6 months","6–8 months","10–12 months"]'::jsonb, '["8–10 bulan","4–6 bulan","6–8 bulan","10–12 bulan"]'::jsonb, 0, 'The third threshold in the table can result in a suspension of eight to ten months.', 'Ambang kali ketiga dalam jadual boleh menyebabkan penggantungan lapan hingga sepuluh bulan.', NULL, 'KPP General, PDF 95'),
  ('4c2b11c1-d72e-5973-b6cd-0c183db41328'::uuid, 'safety-principles', 'quiz-c-d-3', 10, 'What action can follow three licence suspensions within five years?', 'Apakah tindakan yang boleh diambil selepas tiga penggantungan lesen dalam tempoh lima tahun?', '["An additional warning","A driving course referral","Licence cancellation","Automatic licence renewal"]'::jsonb, '["Amaran tambahan","Rujukan kursus memandu","Pembatalan lesen","Pembaharuan lesen automatik"]'::jsonb, 2, 'The KEJARA schedule describes cancellation action after three suspensions within five years.', 'Jadual KEJARA menerangkan tindakan pembatalan selepas tiga penggantungan dalam tempoh lima tahun.', NULL, 'KPP General, PDF 95'),
  ('b67eec19-9d94-5751-8c71-7489f91728fa'::uuid, 'safety-principles', 'quiz-c-d-3', 11, 'What reduction can be considered after 12 months without a scheduled offence?', 'Apakah pengurangan yang boleh dipertimbangkan selepas 12 bulan tanpa kesalahan terjadual?', '["Up to a quarter of the points","Half of the court fine","All points immediately","Up to half the points"]'::jsonb, '["Sehingga suku mata","Separuh denda mahkamah","Semua mata serta-merta","Sehingga separuh mata"]'::jsonb, 3, 'The schedule lists a possible deduction of up to half the accumulated demerit points.', 'Jadual menyenaraikan potongan sehingga separuh daripada mata demerit yang terkumpul.', NULL, 'KPP General, PDF 95'),
  ('302fae59-32e1-52fb-b688-03fc81398b25'::uuid, 'safety-principles', 'quiz-c-d-3', 12, 'On a conventional H-pattern with first and second in the left gate, how do you move from first to second?', 'Pada corak H biasa dengan gear pertama dan kedua di laluan kiri, bagaimanakah anda menukar dari gear pertama ke kedua?', '["Back through Neutral","Forward through Neutral","Right and then forward","Right and then back"]'::jsonb, '["Ke belakang melalui kedudukan bebas","Ke hadapan melalui kedudukan bebas","Ke kanan dan kemudian ke hadapan","Ke kanan dan kemudian ke belakang"]'::jsonb, 0, 'With the clutch fully pressed, move the lever back through Neutral into second.', 'Tekan cekam sepenuhnya, kemudian tarik tombol ke belakang melalui kedudukan bebas hingga gear dua.', NULL, 'KPP Kelas D Manual, PDF 213'),
  ('2e846637-b19f-54b6-855d-a90e1035d934'::uuid, 'safety-principles', 'quiz-c-d-3', 13, 'From second gear, what is the final lever movement after crossing to the third-gear gate?', 'Dari gear dua, apakah gerakan akhir tombol selepas masuk ke laluan gear tiga?', '["Pull the lever back","Push the lever forward","Push the lever left","Push the lever right"]'::jsonb, '["Tarik tombol ke belakang","Tolak tombol ke hadapan","Tolak tombol ke kiri","Tolak tombol ke kanan"]'::jsonb, 1, 'The illustrated second-to-third shift passes through Neutral and then goes forward into third.', 'Pertukaran yang ditunjukkan melalui kedudukan bebas sebelum tombol ditolak ke hadapan ke gear tiga.', NULL, 'KPP Kelas D Manual, PDF 213'),
  ('822a1ecc-0f75-50df-81e7-074da3a7ca7a'::uuid, 'safety-principles', 'quiz-c-d-3', 14, 'On a five-speed H-pattern with third and fourth in the centre gate, how do you shift from third to fourth?', 'Pada corak H lima kelajuan dengan gear ketiga dan keempat di laluan tengah, bagaimanakah anda menukar dari gear ketiga ke keempat?', '["Straight ahead through Neutral","Left and then back","Straight back through Neutral","Right and then back"]'::jsonb, '["Lurus ke hadapan melalui kedudukan bebas","Ke kiri dan kemudian ke belakang","Lurus ke belakang melalui kedudukan bebas","Ke kanan dan kemudian ke belakang"]'::jsonb, 2, 'Press the clutch fully and move the lever straight back through Neutral.', 'Tekan cekam sepenuhnya dan tarik tombol lurus ke belakang melalui kedudukan bebas.', NULL, 'KPP Kelas D Manual, PDF 214'),
  ('8c4ff22f-50f4-582f-a613-57711ec04a69'::uuid, 'safety-principles', 'quiz-c-d-3', 15, 'On a conventional five-speed H-pattern, how do you move the lever from neutral into fifth?', 'Pada corak H lima kelajuan biasa, bagaimanakah tuil digerakkan dari neutral ke gear kelima?', '["Right, then back","Left, then forward","Left, then back","Right, then forward"]'::jsonb, '["Ke kanan, kemudian ke belakang","Ke kiri, kemudian ke hadapan","Ke kiri, kemudian ke belakang","Ke kanan, kemudian ke hadapan"]'::jsonb, 3, 'For the illustrated fourth-to-fifth shift, move from Neutral to the right and then forward.', 'Untuk pertukaran dari gear empat ke gear lima dalam rajah, gerakkan tombol ke kanan dari kedudukan bebas, kemudian ke hadapan.', NULL, 'KPP Kelas D Manual, PDF 214'),
  ('30ae9870-dfdb-53aa-9d91-bdd14a9a2517'::uuid, 'safety-principles', 'quiz-c-da-1', 1, 'What is the minimum age to apply for a motorcycle licence?', 'Berapakah umur minimum untuk memohon lesen motosikal?', '["15 years","17 years","16 years","18 years"]'::jsonb, '["15 tahun","17 tahun","16 tahun","18 tahun"]'::jsonb, 2, 'The curriculum lists 16 as the minimum age for a motorcycle licence.', 'Kurikulum menetapkan umur minimum 16 tahun bagi permohonan lesen motosikal.', NULL, 'KPP General, PDF 9'),
  ('14ad2e95-f559-5964-995d-8acc655d0c86'::uuid, 'safety-principles', 'quiz-c-da-1', 2, 'What is the minimum age for the motorcar licence classes?', 'Berapakah umur minimum bagi kelas lesen motokar?', '["16 years","18 years","17 years","21 years"]'::jsonb, '["16 tahun","18 tahun","17 tahun","21 tahun"]'::jsonb, 2, 'Applicants for a motorcar licence must be at least 17 years old.', 'Pemohon lesen motokar mestilah berumur sekurang-kurangnya 17 tahun.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('14223139-d594-5ac2-8a70-25f73f764700'::uuid, 'safety-principles', 'quiz-c-da-1', 3, 'What kind of vehicle does the Class E classification cover in this textbook?', 'Apakah jenis kenderaan bagi Kelas E dalam buku ini?', '["A car without a clutch pedal","An adapted motorcycle","A light tracked tractor","A heavy motor vehicle"]'::jsonb, '["Motokar tanpa pedal cekam","Motosikal yang diubah suai","Traktor ringan berantai","Motokar berat"]'::jsonb, 3, 'Class E is listed for heavy motor vehicles over 7,500 kg unladen.', 'Kelas E disenaraikan untuk motokar berat dengan berat tanpa muatan melebihi 7,500 kg.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('2182f30b-272f-57e4-a54b-156e508a3388'::uuid, 'safety-principles', 'quiz-c-da-1', 4, 'Which licence category does the handbook list for carrying goods by motorcycle?', 'Kategori lesen manakah disenaraikan oleh buku panduan untuk membawa barangan dengan motosikal?', '["GDL","PSV","Conductor licence","No vocational endorsement"]'::jsonb, '["GDL","PSV","Lesen konduktor","Tiada lesen vokasional"]'::jsonb, 0, 'The vocational categories list goods vehicle licensing, including motorcycles, under GDL.', 'Kategori lesen vokasional menyenaraikan motosikal barangan di bawah lesen GDL.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('403a8a24-ae8b-5275-9863-b1558d155746'::uuid, 'safety-principles', 'quiz-c-da-1', 5, 'Which vehicle does a Class A1 licence cover?', 'Kenderaan manakah yang termasuk dalam lesen Kelas A1?', '["An adapted motorcycle","A light goods vehicle","An adapted motorcar","A three-wheel motorcycle"]'::jsonb, '["Motosikal yang diubah suai","Kenderaan barangan ringan","Motokar yang diubah suai","Motosikal tiga roda"]'::jsonb, 2, 'Class A1 covers adapted motorcars for drivers with disabilities. Class A covers adapted motorcycles.', 'Kelas A1 meliputi motokar yang diubah suai untuk pemandu orang kurang upaya. Kelas A meliputi motosikal yang diubah suai.', NULL, 'KPP Kelas DA Automatik, PDF 17'),
  ('988e8088-940b-5fbc-8399-b73e10181cd4'::uuid, 'safety-principles', 'quiz-c-da-1', 6, 'What is the engine capacity limit for a Class B2 motorcycle?', 'Berapakah had kapasiti enjin bagi motosikal Kelas B2?', '["150 cc","300 cc","500 cc","250 cc"]'::jsonb, '["150 cc","300 cc","500 cc","250 cc"]'::jsonb, 3, 'Class B2 covers personal motorcycles up to 250 cc.', 'Kelas B2 meliputi motosikal persendirian sehingga 250 cc.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('9f938747-0f20-5d41-bf10-51783a315f19'::uuid, 'safety-principles', 'quiz-c-da-1', 7, 'What is the maximum unladen weight for a Class D or DA motorcar?', 'Berapakah berat tanpa muatan maksimum bagi motokar Kelas D atau DA?', '["2500 kg","5000 kg","7500 kg","3500 kg"]'::jsonb, '["2500 kg","5000 kg","7500 kg","3500 kg"]'::jsonb, 3, 'The Class D and DA classifications both have an unladen weight limit of 3,500 kg.', 'Kelas D dan DA mempunyai had berat tanpa muatan sebanyak 3,500 kg.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('465b5662-6db9-52d5-9b13-f10f2001e782'::uuid, 'safety-principles', 'quiz-c-da-1', 8, 'Which group of vehicles is covered by Classes F, G, H and I?', 'Kumpulan kenderaan manakah yang diliputi oleh Kelas F, G, H dan I?', '["Lorries and articulated trailers","Tractors and mobile machinery","Buses and passenger vans","Motorcars and small vans"]'::jsonb, '["Lori dan treler bersendi","Traktor dan jentera bergerak","Bas dan van penumpang","Motokar dan van kecil"]'::jsonb, 1, 'These classes cover tractors and mobile machinery. They distinguish wheels from tracks and lighter from heavier vehicles.', 'Kelas ini meliputi traktor dan jentera bergerak. Kelasnya dibezakan mengikut roda atau rantai serta berat kenderaan.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('68cebec4-0d28-5ecd-93fe-aa9f49f3b84b'::uuid, 'safety-principles', 'quiz-c-da-1', 9, 'How long is the KPP01 course for this class before the Part I test?', 'Berapa lamakah kursus KPP01 bagi kelas ini sebelum Ujian Bahagian I?', '["4 hours","6 hours","5 hours","8 hours"]'::jsonb, '["4 jam","6 jam","5 jam","8 jam"]'::jsonb, 1, 'Candidates attend six hours of KPP01 before taking the Part I test.', 'Calon mengikuti KPP01 selama enam jam sebelum menduduki Ujian Bahagian I.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('6b31aba9-cc8a-52c3-88fc-f34d0f7652fb'::uuid, 'safety-principles', 'quiz-c-da-1', 10, 'Which two environments are covered by the car practical test?', 'Apakah dua persekitaran yang diliputi oleh ujian amali kereta?', '["Circuit and public road","Circuit and computer room","Public road and classroom","Computer room and classroom"]'::jsonb, '["Litar dan jalan raya","Litar dan bilik komputer","Jalan raya dan bilik darjah","Bilik komputer dan bilik darjah"]'::jsonb, 0, 'The car practical test covers the circuit in Part II and the road in Part III.', 'Ujian amali kereta meliputi litar dalam Bahagian II dan jalan raya dalam Bahagian III.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('fc4c76f3-c49b-51ed-9689-bd4b197eb929'::uuid, 'safety-principles', 'quiz-c-da-1', 11, 'For how long is a Part I pass valid?', 'Berapa lamakah keputusan lulus Ujian Bahagian I sah?', '["6 months","18 months","24 months","12 months"]'::jsonb, '["6 bulan","18 bulan","24 bulan","12 bulan"]'::jsonb, 3, 'The validity period starts on the day the candidate passes and lasts one year.', 'Tempoh sah bermula pada tarikh calon lulus dan berakhir selepas setahun.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('a403644c-d4cb-5f19-bc67-02e9b8f68ea1'::uuid, 'safety-principles', 'quiz-c-da-1', 12, 'Which selector position should you use before leaving an automatic car?', 'Kedudukan gear manakah yang patut dipilih sebelum meninggalkan kereta automatik?', '["P","N","R","D"]'::jsonb, '["P","N","R","D"]'::jsonb, 0, 'Park keeps the car from moving and is used when leaving it.', 'Kedudukan P menghalang kereta daripada bergerak dan digunakan apabila meninggalkannya.', NULL, 'KPP Kelas DA Automatik, PDF 210'),
  ('ab0ccd2e-cc7b-59dc-8b89-6271c0479f66'::uuid, 'safety-principles', 'quiz-c-da-1', 13, 'In the handbook’s automatic selector routine, how should you hold the brake before selecting Park?', 'Dalam rutin pemilih gear automatik buku panduan, bagaimanakah anda patut menekan brek sebelum memilih Park?', '["Press it lightly","Press it fully","Pump it twice","Release it first"]'::jsonb, '["Tekan sedikit","Tekan sepenuhnya","Pam dua kali","Lepaskan dahulu"]'::jsonb, 1, 'Stop the car, press the brake pedal fully, and press the selector lock button when selecting P.', 'Hentikan kereta, tekan pedal brek sepenuhnya dan tekan butang pengunci ketika memilih kedudukan P.', NULL, 'KPP Kelas DA Automatik, PDF 215'),
  ('889be359-c027-5356-bc37-8879860ec96a'::uuid, 'safety-principles', 'quiz-c-da-1', 14, 'Which selector position moves an automatic car backwards?', 'Kedudukan gear manakah yang menggerakkan kereta automatik ke belakang?', '["N","L","R","D"]'::jsonb, '["N","L","R","D"]'::jsonb, 2, 'Select R to move the car backwards.', 'Pilih R untuk menggerakkan kereta ke belakang.', NULL, 'KPP Kelas DA Automatik, PDF 210'),
  ('bb3f096b-74b6-5a77-850d-532cee4bdb3c'::uuid, 'safety-principles', 'quiz-c-da-1', 15, 'What is the transmission doing when the selector is in N?', 'Apakah keadaan transmisi apabila tombol gear berada pada kedudukan N?', '["First gear is held","Reverse is engaged","Forward gears alternate","No gear is engaged"]'::jsonb, '["Gear satu dikekalkan","Gear undur dipilih","Gear hadapan bertukar","Tiada gear dipilih"]'::jsonb, 3, 'In Neutral, no drive gear is engaged. The book uses it as one option when starting the engine or stopping briefly.', 'Pada kedudukan N, tiada gear pemacu dipilih. Buku menyatakan kedudukan ini boleh digunakan ketika menghidupkan enjin atau berhenti seketika.', NULL, 'KPP Kelas DA Automatik, PDF 211'),
  ('307ca457-7884-5db3-a017-cc3e0e015ce0'::uuid, 'safety-principles', 'quiz-c-da-2', 1, 'How are the practical training hours split in this curriculum?', 'Bagaimanakah jam latihan amali dibahagikan dalam kurikulum ini?', '["10 circuit, 5½ road","6 circuit, 10 road","5½ circuit, 10 road","5½ circuit, 8 road"]'::jsonb, '["10 litar, 5½ jalan raya","6 litar, 10 jalan raya","5½ litar, 10 jalan raya","5½ litar, 8 jalan raya"]'::jsonb, 2, 'This curriculum lists five and a half hours of circuit training and ten hours of road training.', 'Kurikulum ini menyenaraikan lima jam setengah di litar dan sepuluh jam di jalan raya.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('366cfe73-2d16-5b85-a6c9-edfb63207b54'::uuid, 'safety-principles', 'quiz-c-da-2', 2, 'Your learner licence is still valid. How long must you have held it before you can take the practical tests in this curriculum?', 'Lesen belajar anda masih sah. Berapa lamakah lesen itu mesti dipegang sebelum menduduki ujian amali mengikut kurikulum ini?', '["More than 14 days","More than 21 days","More than 60 days","More than 30 days"]'::jsonb, '["Lebih daripada 14 hari","Lebih daripada 21 hari","Lebih daripada 60 hari","Lebih daripada 30 hari"]'::jsonb, 3, 'Before Parts II and III, the learner licence must still be valid and more than 30 days must have passed since issue.', 'Sebelum Ujian Bahagian II dan III, lesen belajar mesti masih sah dan lebih daripada 30 hari telah berlalu sejak tarikh ia dikeluarkan.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('1ddaf8c1-191a-541f-b955-cc77b60a5be0'::uuid, 'safety-principles', 'quiz-c-da-2', 3, 'What is the maximum total validity of a learner licence from its first issue?', 'Berapakah tempoh sah keseluruhan maksimum lesen belajar memandu dari tarikh pertama dikeluarkan?', '["12 months","18 months","36 months","24 months"]'::jsonb, '["12 bulan","18 bulan","36 bulan","24 bulan"]'::jsonb, 3, 'Learner licences can be renewed for three or six months at a time, up to two years from the first issue.', 'Lesen belajar memandu boleh diperbaharui untuk tiga atau enam bulan pada satu masa, sehingga dua tahun dari tarikh pertama dikeluarkan.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('389db7a7-b8c6-566e-9030-92ee2fe9cd6c'::uuid, 'safety-principles', 'quiz-c-da-2', 4, 'Who must accompany a learner driving a motorcar on an L licence?', 'Siapakah yang mesti menemani pemegang lesen L semasa memandu motokar?', '["Any competent licence holder","A driving institute instructor","A parent or guardian","A probationary licence holder"]'::jsonb, '["Mana-mana pemegang lesen kompeten","Pengajar institut memandu","Ibu bapa atau penjaga","Pemegang lesen percubaan"]'::jsonb, 1, 'A learner motorcar driver must drive with a driving institute instructor.', 'Pemegang lesen L bagi motokar mesti memandu bersama pengajar institut memandu.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('df588a0d-8bd0-5e12-8df5-96ef41e07583'::uuid, 'safety-principles', 'quiz-c-da-2', 5, 'Where are L signs displayed on a learner’s motorcar?', 'Di manakah tanda L dipamerkan pada motokar pelajar?', '["At the front and left","At the front and rear","At the rear and right","At the left and right"]'::jsonb, '["Di hadapan dan kiri","Di hadapan dan belakang","Di belakang dan kanan","Di kiri dan kanan"]'::jsonb, 1, 'A learner motorcar displays an L sign at the front and rear.', 'Motokar pelajar mempamerkan tanda L di bahagian hadapan dan belakang.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('ea75edcc-523a-57bd-a8aa-51f2d3ce3d78'::uuid, 'safety-principles', 'quiz-c-da-2', 6, 'How soon after passing the practical test should you apply for a probationary licence?', 'Dalam tempoh berapakah selepas lulus ujian praktikal anda perlu memohon lesen memandu percubaan?', '["6 months","18 months","12 months","24 months"]'::jsonb, '["6 bulan","18 bulan","12 bulan","24 bulan"]'::jsonb, 2, 'The practical test pass is valid for one year. Apply for the probationary licence within that period.', 'Keputusan lulus ujian praktikal sah selama setahun. Mohon lesen memandu percubaan dalam tempoh itu.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('2ceb9828-d702-5867-9422-5111788f61f9'::uuid, 'safety-principles', 'quiz-c-da-2', 7, 'How long is the probation period for a new probationary licence?', 'Berapa lamakah tempoh percubaan bagi lesen memandu percubaan yang baharu?', '["12 months","18 months","36 months","24 months"]'::jsonb, '["12 bulan","18 bulan","36 bulan","24 bulan"]'::jsonb, 3, 'The probationary licence gives new drivers two years to build experience under probation conditions.', 'Lesen memandu percubaan memberi pemandu baharu dua tahun untuk menimba pengalaman di bawah syarat percubaan.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('87a19d36-c8e1-54f6-aea7-7376f5ba211f'::uuid, 'safety-principles', 'quiz-c-da-2', 8, 'Where should you display the P signs on a motorcar?', 'Di manakah tanda P perlu dipamerkan pada motokar?', '["Upper right on both windscreens","Upper left on both windscreens","Lower left on both windscreens","Lower right on both windscreens"]'::jsonb, '["Kanan atas pada kedua-dua cermin","Kiri atas pada kedua-dua cermin","Kiri bawah pada kedua-dua cermin","Kanan bawah pada kedua-dua cermin"]'::jsonb, 1, 'Display a P sign at the upper left corner of both the front and rear windscreens.', 'Pamerkan tanda P di penjuru kiri atas cermin hadapan dan belakang.', NULL, 'KPP Kelas DA Automatik, PDF 21'),
  ('71bc0954-24cd-5791-9946-87ce6c45c9b9'::uuid, 'safety-principles', 'quiz-c-da-2', 9, 'What alcohol level does this curriculum specify for a P licence holder while driving?', 'Apakah kadar alkohol yang ditetapkan dalam kurikulum ini bagi pemegang lesen P semasa memandu?', '["0.02%","0.05%","0.00%","0.08%"]'::jsonb, '["0.02%","0.05%","0.00%","0.08%"]'::jsonb, 2, 'The probationary licence conditions specify 0.00% alcohol in breath, blood and urine.', 'Syarat lesen percubaan menetapkan 0.00% alkohol dalam nafas, darah dan air kencing.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('ec06b292-cf09-5014-92d9-3f0d8aabeeb2'::uuid, 'safety-principles', 'quiz-c-da-2', 10, 'How long after a probationary licence expires can you apply to convert it to a competent licence?', 'Berapa lamakah selepas lesen percubaan tamat tempoh anda boleh memohon pertukaran kepada lesen kompeten?', '["3 months","6 months","12 months","24 months"]'::jsonb, '["3 bulan","6 bulan","12 bulan","24 bulan"]'::jsonb, 2, 'Apply within one year of the probationary licence expiry date.', 'Buat permohonan dalam tempoh setahun daripada tarikh tamat lesen percubaan.', NULL, 'KPP Kelas DA Automatik, PDF 22'),
  ('3d90970a-a1b0-533d-8d4c-41cb12979203'::uuid, 'safety-principles', 'quiz-c-da-2', 11, 'How long after expiry does this textbook list for automatic cancellation of a competent licence?', 'Berapa lamakah selepas tamat tempoh lesen kompeten terbatal secara automatik mengikut buku ini?', '["More than 1 year","More than 2 years","More than 5 years","More than 3 years"]'::jsonb, '["Melebihi 1 tahun","Melebihi 2 tahun","Melebihi 5 tahun","Melebihi 3 tahun"]'::jsonb, 3, 'The table lists cancellation once a competent licence has remained expired for more than three years.', 'Jadual menyenaraikan pembatalan apabila lesen kompeten telah tamat tempoh melebihi tiga tahun.', NULL, 'KPP Kelas DA Automatik, PDF 25'),
  ('2fe239d6-4fb7-53de-bb9e-d06c5a86a2f9'::uuid, 'safety-principles', 'quiz-c-da-2', 12, 'You are on a level road in an automatic car and speed varies with traffic. How are forward gears selected in the normal selector position?', 'Anda memandu kereta automatik di jalan rata dan kelajuan berubah mengikut trafik. Bagaimanakah gear hadapan dipilih pada kedudukan pemanduan biasa?', '["The car selects them","The driver selects each one","The car holds one gear","The driver must stop to shift"]'::jsonb, '["Kereta memilih gear","Pemandu memilih setiap gear","Kereta kekal pada satu gear","Pemandu mesti berhenti untuk menukar gear"]'::jsonb, 0, 'The transmission selects a gear to suit vehicle speed and the power needed.', 'Transmisi memilih gear mengikut kelajuan kenderaan dan kuasa yang diperlukan.', NULL, 'KPP Kelas DA Automatik, PDF 211'),
  ('617e5d81-c3f7-5c48-b667-e35682082ec7'::uuid, 'safety-principles', 'quiz-c-da-2', 13, 'In an automatic with a 3 position, which gears are available when you select it?', 'Bagi kereta automatik dengan kedudukan 3, gear manakah yang boleh digunakan apabila kedudukan itu dipilih?', '["Gear 3 only","Gears 1 to 3","Gears 2 and 3","All forward gears"]'::jsonb, '["Gear 3 sahaja","Gear 1 hingga 3","Gear 2 dan 3","Semua gear hadapan"]'::jsonb, 1, 'Position 3 allows gears 1, 2 and 3. The book gives downhill driving as one example of its use.', 'Kedudukan 3 membenarkan gear 1, 2 dan 3. Buku memberikan pemanduan menuruni bukit sebagai satu contoh penggunaannya.', NULL, 'KPP Kelas DA Automatik, PDF 212'),
  ('9062ee2a-b27f-5edc-b5dd-9ccc8bc0b0ad'::uuid, 'safety-principles', 'quiz-c-da-2', 14, 'Why might you select 2 on a steep descent in an automatic with that selector position?', 'Mengapakah kedudukan 2 boleh dipilih ketika menuruni cerun curam dengan kereta automatik yang mempunyai pilihan itu?', '["For less engine braking","To let the car coast","For more engine braking","To allow higher gears"]'::jsonb, '["Untuk mengurangkan brek enjin","Untuk membiarkan kereta meluncur","Untuk menambah brek enjin","Untuk membenarkan gear lebih tinggi"]'::jsonb, 2, 'The book describes using position 2 on steep descents to increase engine braking.', 'Buku menerangkan penggunaan kedudukan 2 ketika menuruni cerun curam untuk menambah kesan brek enjin.', NULL, 'KPP Kelas DA Automatik, PDF 212'),
  ('fe6eff64-3b49-5265-9d87-c9eb4d443694'::uuid, 'safety-principles', 'quiz-c-da-2', 15, 'With the selector in L, which behaviour should you expect?', 'Dengan pemilih gear pada L, apakah tindak balas yang patut dijangka?', '["The transmission stays in its lowest range","The transmission steps through the forward ranges","The transmission disengages drive","The transmission shifts straight into top gear"]'::jsonb, '["Transmisi kekal dalam julat terendah","Transmisi bertukar melalui julat hadapan","Transmisi memutuskan pacuan","Transmisi terus menukar ke gear tertinggi"]'::jsonb, 0, 'L holds the transmission in low gear. The book uses it for very steep slopes.', 'Kedudukan L mengekalkan gear rendah. Buku menerangkan penggunaannya pada cerun yang sangat curam.', NULL, 'KPP Kelas DA Automatik, PDF 213'),
  ('1a41d36b-9838-58a4-97c4-1c0ccbf016c8'::uuid, 'safety-principles', 'quiz-c-da-3', 1, 'Which licence follows the probationary licence in the curriculum’s licensing process?', 'Lesen manakah menyusuli lesen percubaan dalam proses pelesenan yang diterangkan?', '["Learner’s driving licence","Competent driving licence","Vocational driving licence","International driving permit"]'::jsonb, '["Lesen belajar memandu","Lesen memandu kompeten","Lesen memandu vokasional","Permit memandu antarabangsa"]'::jsonb, 1, 'Drivers who complete probation apply to change from a probationary to a competent driving licence.', 'Pemandu yang menamatkan tempoh percubaan memohon pertukaran daripada lesen percubaan kepada lesen kompeten.', NULL, 'KPP Kelas DA Automatik, PDF 22'),
  ('61301589-fc11-5283-b867-8f24c91e0834'::uuid, 'safety-principles', 'quiz-c-da-3', 2, 'Under this curriculum, what can a driver skip when adding a class from the same licence group?', 'Mengikut kurikulum ini, apakah yang boleh dikecualikan apabila menambah kelas daripada kumpulan lesen yang sama?', '["The practical training and tests","The practical tests only","The road training only","The theory course and test"]'::jsonb, '["Latihan dan ujian amali","Ujian amali sahaja","Latihan jalan raya sahaja","Kursus dan ujian teori"]'::jsonb, 3, 'The same-group exemption covers the KPP01 course and Part I theory test. Practical training and tests still apply.', 'Pengecualian bagi kumpulan yang sama meliputi kursus KPP01 dan ujian teori Bahagian I. Latihan dan ujian amali masih diperlukan.', NULL, 'KPP Kelas DA Automatik, PDF 14'),
  ('0949895f-9228-52c6-b01f-56b3e67a628d'::uuid, 'safety-principles', 'quiz-c-da-3', 3, 'Which licence category covers driving a bus with fare-paying passengers?', 'Kategori lesen manakah meliputi pemanduan bas yang membawa penumpang berbayar?', '["PSV","GDL","CDL alone","PDL alone"]'::jsonb, '["PSV","GDL","CDL sahaja","PDL sahaja"]'::jsonb, 0, 'PSV covers public service vehicles, including buses. GDL is for goods vehicles.', 'PSV meliputi kenderaan perkhidmatan awam termasuk bas. GDL ialah lesen untuk kenderaan barangan.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('c5a67b24-68a3-52b9-9bf5-91a727b86c52'::uuid, 'safety-principles', 'quiz-c-da-3', 4, 'Which specific vision check appears in the handbook’s eligibility requirements?', 'Pemeriksaan penglihatan khusus manakah dinyatakan dalam syarat kelayakan buku panduan?', '["Colour vision","Peripheral vision","Night vision","Depth perception"]'::jsonb, '["Penglihatan warna","Penglihatan sisi","Penglihatan malam","Persepsi kedalaman"]'::jsonb, 0, 'Eligibility includes being able to see ahead for 23 metres and not being colour blind.', 'Kelayakan termasuk boleh melihat ke hadapan sejauh 23 meter dan tidak buta warna.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('9ed30234-6567-5a65-8730-1175df00a96b'::uuid, 'safety-principles', 'quiz-c-da-3', 5, 'What does the name KEJARA stand for?', 'Apakah nama penuh KEJARA?', '["Sistem Kelayakan Jalan Raya","Sistem Keselamatan Jalan Raya","Sistem Kesalahan Jalan Raya","Sistem Kawalan Jalan Raya"]'::jsonb, '["Sistem Kelayakan Jalan Raya","Sistem Keselamatan Jalan Raya","Sistem Kesalahan Jalan Raya","Sistem Kawalan Jalan Raya"]'::jsonb, 1, 'KEJARA is short for Sistem Keselamatan Jalan Raya. It assigns demerit points for scheduled offences.', 'KEJARA ialah singkatan bagi Sistem Keselamatan Jalan Raya. Sistem ini memberikan mata demerit bagi kesalahan terjadual.', NULL, 'KPP General, PDF 93'),
  ('3aa09fe1-a4de-506e-a3e5-a5135fe23b9c'::uuid, 'safety-principles', 'quiz-c-da-3', 6, 'What does this curriculum say happens to a P licence at 20 demerit points?', 'Apakah kesan 20 mata demerit pada lesen P mengikut kurikulum ini?', '["The licence is suspended","A warning is issued","The licence is cancelled","A course is required"]'::jsonb, '["Lesen digantung","Amaran dikeluarkan","Lesen dibatalkan","Kursus diwajibkan"]'::jsonb, 2, 'The P licence conditions state that reaching 20 points or more results in cancellation.', 'Syarat lesen P menyatakan bahawa 20 mata atau lebih mengakibatkan lesen dibatalkan.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('644c2720-f22c-5723-b84f-b1fdb445e0e1'::uuid, 'safety-principles', 'quiz-c-da-3', 7, 'What is the first action shown in the KEJARA schedule when a competent licence holder reaches 20 points?', 'Apakah tindakan pertama dalam jadual KEJARA apabila pemegang lesen kompeten mencapai 20 mata?', '["A suspension","A cancellation","A course referral","A warning"]'::jsonb, '["Penggantungan","Pembatalan","Rujukan kursus","Amaran"]'::jsonb, 3, 'The first threshold shown in the schedule results in a warning.', 'Ambang kali pertama dalam jadual ini membawa kepada amaran.', NULL, 'KPP General, PDF 95'),
  ('570b097b-57be-5bf9-90e8-417d01290fc9'::uuid, 'safety-principles', 'quiz-c-da-3', 8, 'A competent licence holder has already received one KEJARA warning and reaches another 20 points. What suspension range applies in the handbook table?', 'Pemegang lesen kompeten telah menerima satu amaran KEJARA dan mencapai 20 mata lagi. Apakah julat penggantungan dalam jadual buku panduan?', '["6–8 months","4–6 months","8–10 months","10–12 months"]'::jsonb, '["6–8 bulan","4–6 bulan","8–10 bulan","10–12 bulan"]'::jsonb, 0, 'The table shows a first suspension of six to eight months for the second threshold.', 'Jadual menunjukkan penggantungan pertama selama enam hingga lapan bulan bagi ambang kali kedua.', NULL, 'KPP General, PDF 95'),
  ('cdcaa97a-c612-5231-a71c-aeab15386075'::uuid, 'safety-principles', 'quiz-c-da-3', 9, 'A competent licence holder receives a second suspension under the handbook KEJARA schedule. Which range applies?', 'Pemegang lesen kompeten menerima penggantungan kali kedua mengikut jadual KEJARA. Apakah julatnya?', '["8–10 months","4–6 months","6–8 months","10–12 months"]'::jsonb, '["8–10 bulan","4–6 bulan","6–8 bulan","10–12 bulan"]'::jsonb, 0, 'The third threshold in the table can result in a suspension of eight to ten months.', 'Ambang kali ketiga dalam jadual boleh menyebabkan penggantungan lapan hingga sepuluh bulan.', NULL, 'KPP General, PDF 95'),
  ('1151c489-8fb0-540a-96b1-951c280ae482'::uuid, 'safety-principles', 'quiz-c-da-3', 10, 'What action can follow three licence suspensions within five years?', 'Apakah tindakan yang boleh diambil selepas tiga penggantungan lesen dalam tempoh lima tahun?', '["An additional warning","A driving course referral","Licence cancellation","Automatic licence renewal"]'::jsonb, '["Amaran tambahan","Rujukan kursus memandu","Pembatalan lesen","Pembaharuan lesen automatik"]'::jsonb, 2, 'The KEJARA schedule describes cancellation action after three suspensions within five years.', 'Jadual KEJARA menerangkan tindakan pembatalan selepas tiga penggantungan dalam tempoh lima tahun.', NULL, 'KPP General, PDF 95'),
  ('dc877c0e-2e5a-5c34-b0d0-9171bb32aafd'::uuid, 'safety-principles', 'quiz-c-da-3', 11, 'What reduction can be considered after 12 months without a scheduled offence?', 'Apakah pengurangan yang boleh dipertimbangkan selepas 12 bulan tanpa kesalahan terjadual?', '["Up to a quarter of the points","Half of the court fine","All points immediately","Up to half the points"]'::jsonb, '["Sehingga suku mata","Separuh denda mahkamah","Semua mata serta-merta","Sehingga separuh mata"]'::jsonb, 3, 'The schedule lists a possible deduction of up to half the accumulated demerit points.', 'Jadual menyenaraikan potongan sehingga separuh daripada mata demerit yang terkumpul.', NULL, 'KPP General, PDF 95'),
  ('24a7d974-4d7d-5f22-ba42-83d30a9eb19b'::uuid, 'safety-principles', 'quiz-c-da-3', 12, 'Why does the automatic selector have a button you must press for some movements?', 'Mengapa pemilih gear automatik mempunyai butang yang perlu ditekan bagi sesetengah pergerakan?', '["To stop certain shifts happening by accident","To help the selector move more quickly","To make selected gears easier to read","To let the driver skip every other position"]'::jsonb, '["Untuk mengelakkan pertukaran tertentu secara tidak sengaja","Untuk membantu tuil bergerak lebih pantas","Untuk memudahkan bacaan gear terpilih","Untuk membolehkan pemandu melangkau kedudukan tertentu"]'::jsonb, 0, 'The lock helps prevent accidental selection of positions that need extra care.', 'Pengunci membantu mengelakkan pemilihan gear yang memerlukan perhatian tambahan secara tidak sengaja.', NULL, 'KPP Kelas DA Automatik, PDF 213'),
  ('cf3f3eea-c51e-5447-a72a-35df8d5bbfe6'::uuid, 'safety-principles', 'quiz-c-da-3', 13, 'On the automatic selector described in the handbook, which pair requires pressing the lock button?', 'Pada pemilih gear automatik yang diterangkan dalam buku panduan, pasangan kedudukan manakah memerlukan butang pengunci ditekan?', '["N and D","P and R","D and 3","N and 3"]'::jsonb, '["N dan D","P dan R","D dan 3","N dan 3"]'::jsonb, 1, 'The book says to press the button when selecting P or R. It also describes using the button for low positions 2 and L.', 'Buku menyatakan butang perlu ditekan apabila memilih P atau R. Butang juga digunakan bagi kedudukan rendah 2 dan L.', NULL, 'KPP Kelas DA Automatik, PDF 214'),
  ('298552f9-2475-520c-a335-5c75e87d100a'::uuid, 'safety-principles', 'quiz-c-da-3', 14, 'You move the selector while stopped. Which readout confirms the transmission is in the intended range?', 'Anda menggerakkan pemilih semasa berhenti. Paparan manakah mengesahkan transmisi berada dalam julat yang dimaksudkan?', '["The P/R/N/D indicator","The engine speed reading","The speedometer reading","The parking brake warning lamp"]'::jsonb, '["Penunjuk P/R/N/D","Bacaan putaran enjin","Bacaan meter laju","Lampu amaran brek parkir"]'::jsonb, 0, 'Check the gear position on the instrument display. Avoid looking down at the gear lever while driving.', 'Semak kedudukan gear pada paparan panel meter. Elakkan melihat ke bawah pada tombol gear semasa memandu.', NULL, 'KPP Kelas DA Automatik, PDF 215'),
  ('623e6fb6-3f4a-517a-990a-e9cc460d8a63'::uuid, 'safety-principles', 'quiz-c-da-3', 15, 'During the pre-drive routine, how should you use the accelerator when starting an automatic car?', 'Semasa rutin sebelum memandu, bagaimanakah pedal pemecut perlu digunakan ketika menghidupkan kereta automatik?', '["Press it slightly","Press it fully","Pump it once","Leave it released"]'::jsonb, '["Tekan sedikit","Tekan sepenuhnya","Pam sekali","Biarkan tanpa ditekan"]'::jsonb, 3, 'The pre-drive routine says to start the engine without pressing the accelerator.', 'Rutin sebelum memandu menyatakan enjin perlu dihidupkan tanpa menekan pedal pemecut.', NULL, 'KPP Kelas DA Automatik, PDF 208'),
  ('a3db8f0b-79ba-4d2d-84ca-06f029e03869'::uuid, 'road-signs', 'mock-d-combined-1', 1, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on the left","Pass on the right","Use the left lane ahead","Turn left at the junction"]'::jsonb, '["Lalu di sebelah kiri","Lalu di sebelah kanan","Gunakan lorong kiri di hadapan","Belok kiri di persimpangan"]'::jsonb, 0, 'This sign means pass on the left.', 'Papan tanda ini bermaksud lalu di sebelah kiri.', '/signs/24dc89f9e7127cca.svg', 'KPP General PDF page 64'),
  ('2d16bd05-8759-43c5-ae52-9063980e23d6'::uuid, 'road-signs', 'mock-d-combined-1', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on the right","Pass on the left","Turn right ahead","Keep to the right lane"]'::jsonb, '["Lalu di sebelah kanan","Lalu di sebelah kiri","Belok kanan di hadapan","Kekal di lorong kanan"]'::jsonb, 0, 'This sign means pass on the right.', 'Papan tanda ini bermaksud lalu di sebelah kanan.', '/signs/a50c8dd8a202a25e.svg', 'KPP General PDF page 64'),
  ('e3655f19-1562-44c0-8414-ed25135fdd85'::uuid, 'road-signs', 'mock-d-combined-1', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on either side","Pass on the left","Keep to the centre","Use the left branch only"]'::jsonb, '["Lalu di mana-mana sisi","Lalu di sebelah kiri","Kekal di tengah","Gunakan cabang kiri sahaja"]'::jsonb, 0, 'This sign means pass on either side.', 'Papan tanda ini bermaksud lalu di mana-mana sisi.', '/signs/6103dff69316bf86.svg', 'KPP General PDF page 64'),
  ('0b3f246b-27af-4deb-9b93-7592a6112c73'::uuid, 'road-signs', 'mock-d-combined-1', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for motorcycles","Lane for bicycles","Lane for taxis","Lane for buses"]'::jsonb, '["Lorong untuk motosikal","Lorong untuk basikal","Lorong untuk teksi","Lorong untuk bas"]'::jsonb, 0, 'This sign means lane for motorcycles.', 'Papan tanda ini bermaksud lorong untuk motosikal.', '/signs/e0389a069e72ed52.png', 'KPP General PDF page 65'),
  ('5a986375-f63a-475e-8067-1d2f7fadcac6'::uuid, 'road-signs', 'mock-d-combined-1', 5, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for bicycles","Lane for motorcycles","Lane for trishaws","Lane for pedestrians"]'::jsonb, '["Lorong untuk basikal","Lorong untuk motosikal","Lorong untuk beca","Lorong untuk pejalan kaki"]'::jsonb, 0, 'This sign means lane for bicycles.', 'Papan tanda ini bermaksud lorong untuk basikal.', '/signs/e86785fec1877d75.png', 'KPP General PDF page 65'),
  ('826dd4b4-d351-4c47-9d72-b4734c920e85'::uuid, 'road-signs', 'mock-d-combined-1', 6, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No right turn","No left turn","No U-turn","Turn right only"]'::jsonb, '["Dilarang belok kanan","Dilarang belok kiri","Dilarang membuat pusingan U","Belok kanan sahaja"]'::jsonb, 0, 'The crossed right arrow bans a right turn at that junction.', 'Anak panah kanan yang dipalang melarang pemandu membelok ke kanan di simpang itu.', '/signs/2eee15e55fa0ef48.svg', 'KPP General PDF page 57'),
  ('2d61e95d-ed70-4729-8006-2c1a7e29a84b'::uuid, 'road-signs', 'mock-d-combined-1', 7, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for bicycles","Lane for trishaws","Lane for buses","Lane for taxis"]'::jsonb, '["Lorong untuk basikal","Lorong untuk beca","Lorong untuk bas","Lorong untuk teksi"]'::jsonb, 1, 'This sign means lane for trishaws.', 'Papan tanda ini bermaksud lorong untuk beca.', '/signs/fad437bbc08b75fa.png', 'KPP General PDF page 65'),
  ('1bfd62a7-92a8-4d29-ab37-03ef25cca394'::uuid, 'road-signs', 'mock-d-combined-1', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Medical clinic","Public telephone","Hospital","Bus stop"]'::jsonb, '["Klinik perubatan","Telefon awam","Hospital","Perhentian bas"]'::jsonb, 2, 'This sign means hospital.', 'Papan tanda ini bermaksud hospital.', '/signs/dde5874c6044c5f3.svg', 'KPP General PDF page 67'),
  ('7cda3fa2-5e1c-4d7c-ba26-cb0548d8f17e'::uuid, 'road-signs', 'mock-d-combined-1', 9, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Vehicle parking","Medical clinic","JPJ weighing station","Public telephone"]'::jsonb, '["Tempat letak kenderaan","Klinik perubatan","Stesen timbang JPJ","Telefon awam"]'::jsonb, 0, 'This sign means vehicle parking.', 'Papan tanda ini bermaksud tempat letak kenderaan.', '/signs/f6459f68e216bc5d.svg', 'KPP General PDF page 67'),
  ('91029a30-2822-4e78-a7fa-0a638a190656'::uuid, 'road-signs', 'mock-d-combined-1', 10, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Distance to a destination exit","Directions at a junction ahead","Distances to upcoming destinations","Road with no through access"]'::jsonb, '["Jarak ke susur keluar destinasi","Arah di simpang yang akan datang","Jarak ke destinasi seterusnya","Jalan buntu di hadapan"]'::jsonb, 3, 'This sign means road with no through access. The road does not continue through to another route.', 'Papan tanda ini bermaksud jalan buntu di hadapan. Jalan itu tidak bersambung dengan laluan lain.', '/signs/082877f6ec086be6.svg', 'KPP General PDF page 68'),
  ('2e798684-96d2-4ef0-a5a5-354e940413dd'::uuid, 'road-signs', 'mock-d-combined-1', 11, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Designated U-turn","Designated P-turn","Road with no through access","Directions at a junction ahead"]'::jsonb, '["Tempat pusingan U","Tempat pusingan P","Jalan buntu di hadapan","Arah di simpang yang akan datang"]'::jsonb, 0, 'This sign means designated U-turn. It marks a place to turn around. Give way to oncoming traffic before turning.', 'Papan tanda ini bermaksud tempat pusingan U. Tanda ini menunjukkan tempat untuk berpatah balik. Beri laluan kepada trafik dari arah bertentangan sebelum membelok.', '/signs/8956fe8a103938b3.svg', 'KPP General PDF page 69'),
  ('9bc55720-9eb3-4489-ad21-4dbbba79c4c9'::uuid, 'road-signs', 'mock-d-combined-1', 12, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No vehicle entry","No overtaking","No stopping","No through road"]'::jsonb, '["Kenderaan dilarang masuk","Dilarang memotong","Dilarang berhenti","Jalan buntu"]'::jsonb, 0, 'This sign means no vehicle entry.', 'Papan tanda ini bermaksud kenderaan dilarang masuk.', '/signs/9a316a4baac9f49a.svg', 'KPP General PDF page 57'),
  ('85921637-d9b0-4fc1-a411-49fcd5acc52d'::uuid, 'road-signs', 'mock-d-combined-1', 13, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No U-turn","No right turn","No left turn","Right turn only"]'::jsonb, '["Dilarang membuat pusingan U","Dilarang membelok ke kanan","Dilarang membelok ke kiri","Belok kanan sahaja"]'::jsonb, 0, 'This sign means no U-turn.', 'Papan tanda ini bermaksud dilarang membuat pusingan U.', '/signs/a299aef5bccc0fca.svg', 'KPP General PDF page 58'),
  ('604123c1-30cb-4ddb-ba5e-a10e160e17bb'::uuid, 'road-signs', 'mock-d-combined-1', 14, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No vehicle entry","No right turn","No U-turn","No left turn"]'::jsonb, '["Kenderaan dilarang masuk","Dilarang membelok ke kanan","Dilarang membuat pusingan U","Dilarang membelok ke kiri"]'::jsonb, 3, 'You must use a route that does not require turning left here.', 'Gunakan laluan yang tidak memerlukan anda membelok ke kiri di sini.', '/signs/ef495735d6870ce2.svg', 'KPP General PDF page 57'),
  ('474de3af-f9fe-4686-a96a-a45ded3a541c'::uuid, 'road-signs', 'mock-d-combined-1', 15, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No parking","No stopping","No entry","No waiting at the junction"]'::jsonb, '["Dilarang meletak kenderaan","Dilarang berhenti","Dilarang masuk","Dilarang menunggu di persimpangan"]'::jsonb, 0, 'This sign means no parking.', 'Papan tanda ini bermaksud dilarang meletak kenderaan.', '/signs/fbd415b24ab21b44.svg', 'KPP General PDF page 58'),
  ('17df082e-fa2d-4185-b851-27b406e30262'::uuid, 'road-signs', 'mock-d-combined-1', 16, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Left lane closes ahead","Keep right of an obstacle","Traffic merges from the right","Route changes direction to the right"]'::jsonb, '["Lorong kiri ditutup di hadapan","Lalu di kanan halangan","Trafik bercantum dari kanan","Laluan berubah arah ke kanan"]'::jsonb, 3, 'The single orange chevron points the way when the route changes direction in a work zone.', 'Satu tanda serong jingga menunjukkan arah apabila laluan berubah dalam zon kerja.', '/signs/263bc825012bcc83.svg', 'KPP General PDF page 76'),
  ('e040820e-d105-439d-b01a-e00f0f2eef05'::uuid, 'road-signs', 'mock-d-combined-1', 17, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No stopping","No overtaking","No left turn","No parking"]'::jsonb, '["Dilarang berhenti","Dilarang memotong","Dilarang membelok ke kiri","Dilarang meletak kenderaan"]'::jsonb, 0, 'This sign means no stopping.', 'Papan tanda ini bermaksud dilarang berhenti.', '/signs/ecd3d648f3d4a187.svg', 'KPP General PDF page 59'),
  ('d47c0e5b-8e18-407f-942a-d54652321ed0'::uuid, 'road-signs', 'mock-d-combined-1', 18, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No sounding the horn","No stopping","No motor vehicle entry","No overtaking"]'::jsonb, '["Dilarang membunyikan hon","Dilarang berhenti","Kenderaan bermotor dilarang masuk","Dilarang memotong"]'::jsonb, 0, 'This sign means no sounding the horn.', 'Papan tanda ini bermaksud dilarang membunyikan hon.', '/signs/ce55b86645694f5d.svg', 'KPP General PDF page 57'),
  ('8788d8ea-cab1-4ca2-abd1-fedbcc3625bc'::uuid, 'road-signs', 'mock-d-combined-1', 19, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Four-way intersection","Slippery road surface","Risk of falling rocks","Direction of a sharp bend"]'::jsonb, '["Persimpangan empat hala","Permukaan jalan licin","Risiko runtuhan batu","Arah selekoh yang tajam"]'::jsonb, 0, 'The cross symbol warns that another road crosses yours. Check both sides on approach.', 'Simbol silang memberi amaran bahawa jalan lain merentasi laluan anda. Periksa kedua-dua sisi apabila menghampiri.', '/signs/4a3491aff2749365.svg', 'KPP General PDF page 40'),
  ('9f545df8-3019-40c0-ae03-a511c015d8a4'::uuid, 'road-signs', 'mock-d-combined-1', 20, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Side road to the left","Side road to the right","Two-way traffic ahead","Gated rail crossing"]'::jsonb, '["Simpang jalan di sebelah kiri","Simpang jalan di sebelah kanan","Lalu lintas dua hala di hadapan","Lintasan kereta api berpagar"]'::jsonb, 0, 'The side branch on the left warns of a road joining from that side.', 'Cabang di sebelah kiri memberi amaran tentang jalan yang bercantum dari arah itu.', '/signs/e22292f492beec26.svg', 'KPP General PDF page 42'),
  ('4e9d6695-dc9b-4ae6-870a-83676193263b'::uuid, 'road-signs', 'mock-d-combined-1', 21, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Side road to the right","Side road to the left","Two-way traffic ahead","Road narrows on the left"]'::jsonb, '["Simpang jalan di sebelah kanan","Simpang jalan di sebelah kiri","Lalu lintas dua hala di hadapan","Jalan menyempit di sebelah kiri"]'::jsonb, 0, 'The branch on the right warns of traffic that may enter from a side road there.', 'Cabang di sebelah kanan memberi amaran tentang trafik yang mungkin masuk dari jalan sisi itu.', '/signs/12e8b0d727c5bdf1.svg', 'KPP General PDF page 42'),
  ('b5fdad05-db5f-4eb6-b96c-9f04cb02f6d7'::uuid, 'traffic-rules', 'mock-d-combined-1', 22, 'Your mirrors are clear before you move into the next lane. What final check covers the area beside the car?', 'Cermin menunjukkan laluan lapang sebelum anda berpindah ke lorong sebelah. Apakah semakan terakhir meliputi kawasan di sisi kereta?', '["Glance over the shoulder toward that lane","Look again in the interior mirror","Check the centre of the windscreen","Watch the car immediately ahead"]'::jsonb, '["Toleh ke bahu menghala ke lorong itu","Lihat semula cermin pandang belakang","Periksa bahagian tengah cermin hadapan","Perhatikan kereta tepat di hadapan"]'::jsonb, 0, 'A vehicle on the right can be hidden from both mirrors. Check that area directly before moving.', 'Kenderaan di kanan boleh terlindung daripada kedua-dua cermin. Periksa kawasan itu secara langsung sebelum bergerak.', NULL, 'KPP_D_Manual.pdf PDF page 99'),
  ('678c195a-2674-4335-8561-49d379931556'::uuid, 'traffic-rules', 'mock-d-combined-1', 23, 'Why leave space before pulling in ahead of a lorry?', 'Mengapa perlu tinggalkan ruang sebelum masuk ke hadapan lori?', '["It needs more stopping room","It needs more turning room","It needs more passing room","It needs more merging room"]'::jsonb, '["Lori perlu ruang berhenti lebih panjang","Lori perlu ruang membelok lebih luas","Lori perlu ruang memotong lebih luas","Lori perlu ruang mencelah lebih luas"]'::jsonb, 0, 'Cutting in reduces the space the heavy vehicle has to stop.', 'Memotong masuk secara rapat mengurangkan ruang lori untuk berhenti.', NULL, 'KPP_D_Manual.pdf PDF page 89'),
  ('2a6aa17a-b5a4-444f-9ba5-5cb2f3e649ed'::uuid, 'traffic-rules', 'mock-d-combined-1', 24, 'A child is cycling along the kerb. Which sudden turn could require you to brake?', 'Seorang kanak-kanak berbasikal di tepi bebendul. Belokan mengejut manakah yang mungkin memerlukan anda membrek?', '["Turning towards the footpath","Turning away into a driveway","Turning towards your lane","Turning to follow the kerb"]'::jsonb, '["Membelok ke laluan pejalan kaki","Membelok menjauhi jalan ke laluan masuk","Membelok ke arah lorong anda","Membelok mengikut bebendul"]'::jsonb, 2, 'A cyclist may turn into your path. Anticipate the movement and be ready to brake.', 'Penunggang basikal mungkin membelok ke laluan anda. Jangkakan pergerakan itu dan bersedia untuk membrek.', NULL, 'KPP_D_Manual.pdf PDF page 85'),
  ('4c96979c-15bf-488b-aa63-83e56fa5bdd9'::uuid, 'traffic-rules', 'mock-d-combined-1', 25, 'A schoolchild steps onto the road with no crossing guard present. What do you do?', 'Seorang murid melangkah ke jalan tanpa pengawal lintasan. Apakah tindakan anda?', '["Slow and pass behind the child","Stop and let the child cross","Stop only when signalled","Slow and signal the child to wait"]'::jsonb, '["Perlahankan kenderaan dan lalu di belakang murid","Berhenti dan beri laluan kepada murid","Berhenti hanya jika diberi isyarat","Perlahankan kenderaan dan isyaratkan murid supaya menunggu"]'::jsonb, 1, 'Stop as the child steps onto the road. Wait until the crossing is clear.', 'Berhenti apabila murid melangkah ke jalan. Tunggu sehingga lintasan kosong.', NULL, 'KPP_D_Manual.pdf PDF page 81'),
  ('e07aa1fc-fa05-4b00-8625-699c1fc63cb2'::uuid, 'traffic-rules', 'mock-d-combined-1', 26, 'A bus is stopped at the kerb. What can the bus hide from view?', 'Sebuah bas berhenti di tepi jalan. Apakah yang mungkin terlindung di sebalik bas?', '["Drivers joining from a junction","Passengers crossing the road","Cyclists waiting in a side lane","Vehicles turning into a car park"]'::jsonb, '["Pemandu yang keluar dari simpang","Penumpang yang melintas jalan","Penunggang basikal yang menunggu di lorong sisi","Kenderaan yang masuk ke tempat letak kereta"]'::jsonb, 1, 'Passengers may cross from directly in front of or behind the bus, where you cannot see them.', 'Penumpang mungkin melintas dari hadapan atau belakang bas, di tempat yang terlindung daripada pandangan anda.', NULL, 'KPP_D_Manual.pdf PDF page 82'),
  ('29c852eb-0367-40d7-ac2f-57c52be0b28b'::uuid, 'traffic-rules', 'mock-d-combined-1', 27, 'An L-plate car ahead keeps slowing. How should you follow?', 'Kereta berpelekat L di hadapan kerap memperlahankan kelajuan. Bagaimanakah anda patut mengekorinya?', '["Leave room for a sudden stop","Close the gap to discourage braking","Follow closer at low speed","Use the horn to keep it moving"]'::jsonb, '["Tinggalkan ruang jika kereta berhenti mengejut","Rapatkan jarak supaya kereta kurang membrek","Ikut lebih rapat pada kelajuan rendah","Bunyikan hon supaya kereta terus bergerak"]'::jsonb, 0, 'A learner may stop unexpectedly. Leave a gap and give them time.', 'Pemandu pelajar mungkin berhenti tanpa dijangka. Tinggalkan jarak dan beri mereka masa.', NULL, 'KPP_D_Manual.pdf PDF page 87'),
  ('8ecb9504-3956-4d52-82bb-17d95b35839e'::uuid, 'traffic-rules', 'mock-d-combined-1', 28, 'You have right of way when an ambulance approaches with its siren on. What should you do?', 'Anda mempunyai hak laluan apabila ambulans menghampiri dengan siren berbunyi. Apakah tindakan anda?', '["Keep going before it arrives","Give the ambulance room","Wait for its driver to wave","Hold your lane and speed"]'::jsonb, '["Teruskan sebelum ambulans tiba","Beri ruang kepada ambulans","Tunggu pemandunya melambai","Kekalkan lorong dan kelajuan"]'::jsonb, 1, 'Give priority to an emergency vehicle sounding its siren, even if you ordinarily have right of way.', 'Beri keutamaan kepada kenderaan kecemasan yang membunyikan siren walaupun anda biasanya mempunyai hak laluan.', NULL, 'KPP_D_Manual.pdf PDF page 90'),
  ('4edcf0a5-dd27-45b2-b93b-9e50b2a93e69'::uuid, 'traffic-rules', 'mock-d-combined-1', 29, 'When can the radio interfere with your observation of the road?', 'Bilakah penggunaan radio boleh mengganggu pemerhatian anda terhadap jalan?', '["When it masks traffic sounds","When it is louder than conversation","When it is louder than the engine","When it makes directions hard to hear"]'::jsonb, '["Apabila bunyi trafik tidak kedengaran","Apabila radio lebih kuat daripada perbualan","Apabila radio lebih kuat daripada enjin","Apabila arahan sukar didengar"]'::jsonb, 0, 'Keep the radio low enough to hear what is happening outside the vehicle.', 'Rendahkan kelantangan radio supaya bunyi di luar kenderaan dapat didengar.', NULL, 'KPP_D_Manual.pdf PDF page 93'),
  ('f630c854-1029-46d1-80c2-e941cbcb78fb'::uuid, 'traffic-rules', 'mock-d-combined-1', 30, 'How should a higher driving speed change where you look?', 'Bagaimanakah kelajuan yang lebih tinggi patut mengubah arah tumpuan anda?', '["Look longer in the mirrors","Focus closer to the bonnet","Scan more often to the side","Scan farther down the road"]'::jsonb, '["Lihat cermin lebih lama","Tumpukan lebih dekat dengan bonet","Imbas ke sisi dengan lebih kerap","Imbas lebih jauh ke hadapan"]'::jsonb, 3, 'Speed leaves less time to react, so look farther ahead to spot problems early.', 'Kelajuan mengurangkan masa untuk bertindak. Lihat lebih jauh ke hadapan supaya bahaya dikesan awal.', NULL, 'KPP_D_Manual.pdf PDF page 97'),
  ('fced948d-bd8e-48b5-9bc7-ca62056487ea'::uuid, 'traffic-rules', 'mock-d-combined-1', 31, 'What makes a good marker for timing a following gap?', 'Apakah penanda yang sesuai untuk mengukur jarak mengekor dengan masa?', '["A cloud above the road","A moving car beside you","A passing motorcycle","A fixed lamp post"]'::jsonb, '["Awan di atas jalan","Kereta yang bergerak di sebelah","Motosikal yang sedang memotong","Tiang lampu yang tetap"]'::jsonb, 3, 'Start counting when the vehicle ahead passes a fixed marker. Compare that with when you pass the same marker.', 'Mula mengira apabila kenderaan di hadapan melepasi penanda tetap. Bandingkan dengan masa anda melepasi penanda yang sama.', NULL, 'KPP_D_Manual.pdf PDF page 101'),
  ('39bb659a-9dc4-47f5-8f37-594b51fe5be9'::uuid, 'traffic-rules', 'mock-d-combined-1', 32, 'A driver is following your car too closely. What gap does the handbook advise you to leave ahead?', 'Pemandu di belakang mengekori kereta anda terlalu rapat. Apakah jarak masa di hadapan yang disarankan oleh buku panduan?', '["Four seconds","Two seconds","Three seconds","Five seconds"]'::jsonb, '["Empat saat","Dua saat","Tiga saat","Lima saat"]'::jsonb, 0, 'A longer following gap gives you and the driver behind more room to stop in an emergency.', 'Jarak mengekori yang lebih jauh memberikan anda dan pemandu di belakang lebih banyak ruang untuk berhenti semasa kecemasan.', NULL, 'KPP_D_Manual.pdf PDF page 103'),
  ('a74faff9-2e9f-492e-b9c2-532a412d20f8'::uuid, 'traffic-rules', 'mock-d-combined-1', 33, 'Why allow more following distance when towing?', 'Mengapa jarak mengekor perlu ditambah ketika menunda?', '["The extra weight takes more room to stop","The extra length takes more room to turn","The added mirrors widen the blind spot","The tow connection changes the steering angle"]'::jsonb, '["Berat tambahan memerlukan ruang berhenti lebih panjang","Panjang tambahan memerlukan ruang membelok lebih luas","Cermin tambahan meluaskan titik buta","Sambungan tunda mengubah sudut stereng"]'::jsonb, 0, 'The towing vehicle and load need enough time and distance to stop together.', 'Kenderaan dan beban yang ditunda memerlukan masa dan jarak yang mencukupi untuk berhenti bersama.', NULL, 'KPP_D_Manual.pdf PDF page 105'),
  ('6fe03828-3431-49dd-b8a5-09590c06c0a7'::uuid, 'traffic-rules', 'mock-d-combined-1', 34, 'A car ahead is slow near the crest of a hill. When should you pass?', 'Kereta di hadapan bergerak perlahan berhampiran puncak bukit. Bilakah anda patut memotong?', '["When the vehicle ahead clears the crest","When you can see the road beyond the crest","When your mirrors show no traffic behind","When you have room to pull out before the crest"]'::jsonb, '["Apabila kenderaan di hadapan melepasi puncak","Apabila jalan selepas puncak dapat dilihat","Apabila tiada trafik di belakang dalam cermin","Apabila ada ruang untuk keluar sebelum puncak"]'::jsonb, 1, 'Avoid overtaking at a hill crest. Wait until you are past it and the road is clear.', 'Elakkan memotong di puncak bukit. Tunggu sehingga anda melepasi puncak dan laluan jelas.', NULL, 'KPP_D_Manual.pdf PDF page 107'),
  ('0b4f7159-c139-4250-a993-cee60a5ce5f3'::uuid, 'traffic-rules', 'mock-d-combined-1', 35, 'The brake pedal drops to the floor on a level road. What can you try first to restore pressure?', 'Pedal brek jatuh ke lantai di jalan rata. Apakah yang boleh dicuba dahulu untuk memulihkan tekanan?', '["Press the clutch pedal","Hold the brake pedal down","Pump the brake pedal","Pull the handbrake fully"]'::jsonb, '["Tekan pedal cekam","Tekan pedal brek tanpa dilepaskan","Pam pedal brek","Tarik brek tangan sepenuhnya"]'::jsonb, 2, 'Pumping may restore hydraulic pressure. If it does not, the book advises a lower gear and gradual handbrake use where safe.', 'Mengepam pedal mungkin memulihkan tekanan hidraulik. Jika gagal, gunakan gear rendah dan tarik brek tangan beransur-ansur apabila selamat.', NULL, 'KPP_D_Manual.pdf PDF page 126'),
  ('e19f9c42-fbc7-4c5c-a19a-16ab7f6099c7'::uuid, 'traffic-rules', 'mock-d-combined-1', 36, 'A tyre bursts while you are driving. What should you do with the controls?', 'Tayar pecah ketika anda memandu. Bagaimanakah anda patut mengawal kenderaan?', '["Brake hard and steer toward the kerb","Hold the wheel firmly and slow gently","Ease off and steer sharply to the left","Accelerate briefly and then pull over"]'::jsonb, '["Brek kuat dan hala ke bebendul","Pegang stereng erat dan perlahankan kenderaan","Lepaskan pemecut dan belok tajam ke kiri","Pecut seketika dan kemudian berhenti di tepi"]'::jsonb, 1, 'Keep the car stable and slow progressively. Find a flat, safe place to stop.', 'Pastikan kenderaan stabil dan kurangkan kelajuan beransur-ansur. Cari tempat rata dan selamat untuk berhenti.', NULL, 'KPP_D_Manual.pdf PDF page 127'),
  ('d27c6db1-4853-4e8a-959f-401dcd2abf6b'::uuid, 'traffic-rules', 'mock-d-combined-1', 37, 'Both headlights fail at night. What should you do next?', 'Kedua-dua lampu hadapan terpadam pada waktu malam. Apakah tindakan seterusnya?', '["Follow another car to your destination","Slow and find a safe place to stop","Hold speed and follow the edge line","Stop immediately in the traffic lane"]'::jsonb, '["Ikut kereta lain hingga ke destinasi","Perlahankan kenderaan dan cari tempat selamat untuk berhenti","Kekalkan kelajuan dan ikut garisan tepi","Berhenti serta-merta di lorong trafik"]'::jsonb, 1, 'Use hazard lights to warn others and get out of moving traffic safely.', 'Gunakan lampu kecemasan untuk memberi amaran dan keluar daripada aliran trafik dengan selamat.', NULL, 'KPP_D_Manual.pdf PDF page 128'),
  ('c383bb51-ae59-41a2-bab2-23b626ac9326'::uuid, 'traffic-rules', 'mock-d-combined-1', 38, 'Your car breaks down on an expressway. Where should passengers wait?', 'Kereta anda rosak di lebuh raya. Di manakah penumpang patut menunggu?', '["Behind the car''s rear lights","Away from moving traffic","Beside the driver''s door","In front of the warning sign"]'::jsonb, '["Di belakang lampu belakang kereta","Jauh daripada aliran trafik","Di sebelah pintu pemandu","Di hadapan tanda amaran"]'::jsonb, 1, 'Move passengers away from traffic. Keep the vehicle''s lights visible to approaching drivers.', 'Bawa penumpang jauh daripada trafik. Pastikan lampu kenderaan dapat dilihat oleh pemandu yang menghampiri.', NULL, 'KPP_D_Manual.pdf PDF page 129'),
  ('f657923f-8ba6-462f-997d-6476a9578a86'::uuid, 'traffic-rules', 'mock-d-combined-1', 39, 'The engine overheats. When may you open the radiator cap?', 'Enjin menjadi terlalu panas. Bilakah penutup radiator boleh dibuka?', '["After the fan stops turning","After the engine stops","After opening the bonnet","After the radiator cools"]'::jsonb, '["Selepas kipas berhenti berpusing","Selepas enjin berhenti","Selepas bonet dibuka","Selepas radiator sejuk"]'::jsonb, 3, 'Stop safely and switch off the engine. Let the radiator cool before opening its cap.', 'Berhenti di tempat selamat dan matikan enjin. Tunggu radiator sejuk sebelum membuka penutupnya.', NULL, 'KPP_D_Manual.pdf PDF page 131'),
  ('678b3c77-15b4-4189-a803-b77e09006bc1'::uuid, 'traffic-rules', 'mock-d-combined-1', 40, 'When should you first loosen the wheel nuts during a tyre change?', 'Bilakah nat roda patut dilonggarkan buat kali pertama ketika menukar tayar?', '["After removing the wheel","As the jack starts lifting","Once the wheel is raised","Before lifting the car"]'::jsonb, '["Selepas roda ditanggalkan","Ketika jek mula mengangkat","Sebaik roda terangkat","Sebelum mengangkat kereta"]'::jsonb, 3, 'Break the nuts loose with the wheel on the ground, then lift the vehicle at the correct jacking point.', 'Longgarkan nat ketika roda masih di atas tanah, kemudian angkat kenderaan pada titik jek yang betul.', NULL, 'KPP_D_Manual.pdf PDF page 132'),
  ('7fcfb582-e9b5-4f2b-94c6-2c3ec7cc7133'::uuid, 'traffic-rules', 'mock-d-combined-1', 41, 'When stopping in a queue, what part of the car ahead should still be visible?', 'Apabila berhenti dalam barisan, bahagian manakah pada kereta hadapan yang masih perlu kelihatan?', '["Its rear window","Its rear lamps","Its number plate","Its rear tyres"]'::jsonb, '["Cermin belakangnya","Lampu belakangnya","Plat nombornya","Tayar belakangnya"]'::jsonb, 3, 'Seeing the rear tyres leaves some room to move out if the vehicle ahead cannot move.', 'Jika tayar belakang masih kelihatan, anda mempunyai sedikit ruang untuk keluar jika kenderaan di hadapan tidak dapat bergerak.', NULL, 'KPP_D_Manual.pdf PDF page 134'),
  ('70aee5d2-0a2a-4407-84dd-254a09ac5c45'::uuid, 'traffic-rules', 'mock-d-combined-1', 42, 'You spot your toll lane late. What should you avoid?', 'Anda lewat menyedari lorong tol yang diperlukan. Apakah yang perlu dielakkan?', '["Switching lanes at the last moment","Slowing on the toll approach","Checking for traffic beside you","Following the lane you are in"]'::jsonb, '["Menukar lorong pada saat akhir","Memperlahankan kenderaan sebelum tol","Memeriksa trafik di sebelah anda","Meneruskan perjalanan di lorong semasa"]'::jsonb, 0, 'Choose the correct lane early. A sudden lane change at the plaza can put you in another driver''s path.', 'Pilih lorong yang betul lebih awal. Pertukaran lorong mengejut di plaza boleh memotong laluan kenderaan lain.', NULL, 'KPP_D_Manual.pdf PDF page 136'),
  ('0f973ee1-b7ca-4c8d-bfa1-dc5913c07dde'::uuid, 'traffic-rules', 'mock-d-combined-1', 43, 'Goats are crossing a village road ahead. What should you do?', 'Kambing sedang melintas di jalan kampung di hadapan. Apakah tindakan anda?', '["Slow and let them cross","Sound the horn and hold speed","Pass behind the nearest animal","Steer around them into the other lane"]'::jsonb, '["Perlahankan kenderaan dan beri laluan","Bunyikan hon dan kekalkan kelajuan","Lalu di belakang haiwan paling hampir","Elak haiwan dengan masuk ke lorong sebelah"]'::jsonb, 0, 'Allow the animals to clear the road. A horn may startle them.', 'Tunggu haiwan selesai melintas. Bunyi hon boleh mengejutkannya.', NULL, 'KPP_D_Manual.pdf PDF page 137'),
  ('fe719004-6ddf-4438-a774-055a8a625f6e'::uuid, 'traffic-rules', 'mock-d-combined-1', 44, 'What should you switch on when driving in a tunnel?', 'Apakah yang perlu dihidupkan semasa memandu di dalam terowong?', '["Headlights","Hazard lights","Cabin lights","Rear fog lights"]'::jsonb, '["Lampu hadapan","Lampu kecemasan","Lampu kabin","Lampu kabus belakang"]'::jsonb, 0, 'Visibility is more limited in a tunnel. Use headlights and keep a safe following distance.', 'Penglihatan lebih terhad di dalam terowong. Gunakan lampu hadapan dan kekalkan jarak mengekor yang selamat.', NULL, 'KPP_D_Manual.pdf PDF page 140'),
  ('f35a3267-6756-4097-b8a5-43702a2242a8'::uuid, 'traffic-rules', 'mock-d-combined-1', 45, 'Rain starts on the expressway. Which lights should you use as you keep driving?', 'Hujan mula turun di lebuh raya. Lampu manakah patut digunakan semasa meneruskan pemanduan?', '["Use the parking lights","Use the hazard lights","Use the headlights","Use the cabin lights"]'::jsonb, '["Gunakan lampu parkir","Gunakan lampu kecemasan","Gunakan lampu hadapan","Gunakan lampu kabin"]'::jsonb, 2, 'Headlights make you more visible. Keep hazard lights for emergencies.', 'Lampu hadapan memudahkan kenderaan dilihat. Gunakan lampu kecemasan apabila berlaku kecemasan.', NULL, 'KPP_D_Manual.pdf PDF page 142'),
  ('ff530954-f1ec-4b90-a5c4-0709402dbeca'::uuid, 'traffic-rules', 'mock-d-combined-1', 46, 'You catch up with a car at night. How should you set your headlamps?', 'Anda menghampiri kereta di hadapan pada waktu malam. Bagaimanakah lampu hadapan perlu dilaraskan?', '["Flash full beam continuously","Keep full beam on","Switch to parking lights","Switch to dipped beam"]'::jsonb, '["Kelipkan lampu tinggi berterusan","Kekalkan lampu tinggi","Tukar kepada lampu parkir","Tukar kepada lampu rendah"]'::jsonb, 3, 'Full beam can dazzle the driver ahead through their mirrors.', 'Lampu tinggi boleh menyilaukan pemandu di hadapan melalui cerminnya.', NULL, 'KPP_D_Manual.pdf PDF page 143'),
  ('ac3b5d34-1c85-49b8-b8ba-9899c1d6a6cd'::uuid, 'traffic-rules', 'mock-d-combined-1', 47, 'You are driving through a housing estate. Which hazard does the handbook single out there?', 'Anda sedang memandu melalui kawasan perumahan. Bahaya manakah yang diberi perhatian khusus dalam buku panduan?', '["Children entering the road suddenly","Passengers crossing by a stopped bus","Workers stepping into a traffic lane","Drivers joining from a slip road"]'::jsonb, '["Kanak-kanak tiba-tiba memasuki jalan","Penumpang melintas dekat bas yang berhenti","Pekerja melangkah masuk ke lorong trafik","Pemandu masuk dari susur masuk"]'::jsonb, 0, 'In a residential area, look out for children who might step into your path suddenly.', 'Di kawasan perumahan, awasi kanak-kanak yang mungkin tiba-tiba memasuki laluan anda.', NULL, 'KPP_D_Manual.pdf PDF page 83'),
  ('52c095c6-2054-4191-a76f-6b99d2035aa3'::uuid, 'traffic-rules', 'mock-d-combined-1', 48, 'How can bad weather change pedestrian behaviour?', 'Bagaimanakah cuaca buruk boleh mengubah tingkah laku pejalan kaki?', '["They may cross in a hurry","They may wait longer at kerbs","They may walk in larger groups","They may move closer to walls"]'::jsonb, '["Mereka mungkin melintas tergesa-gesa","Mereka mungkin menunggu lebih lama di tepi jalan","Mereka mungkin berjalan dalam kumpulan besar","Mereka mungkin berjalan lebih dekat dengan dinding"]'::jsonb, 0, 'Expect distracted pedestrians while your own visibility is reduced.', 'Jangkakan pejalan kaki kurang memberi perhatian ketika penglihatan anda juga terhad.', NULL, 'KPP_D_Manual.pdf PDF page 84'),
  ('febf6965-aec3-4ae0-804d-fdbd92fe6194'::uuid, 'traffic-rules', 'mock-d-combined-1', 49, 'You are about to leave a parking bay. What lets a cyclist see your intention?', 'Anda hendak keluar dari petak parkir. Apakah yang membantu penunggang basikal memahami niat anda?', '["A short flash of the headlights","A clear turn signal","A tap on the brake pedal","A slight movement of the car"]'::jsonb, '["Kelipan singkat lampu hadapan","Isyarat membelok yang jelas","Tekanan ringan pada pedal brek","Pergerakan kecil kereta"]'::jsonb, 1, 'Signal clearly and check that the lane is safe before pulling out.', 'Beri isyarat dengan jelas dan pastikan lorong selamat sebelum keluar.', NULL, 'KPP_D_Manual.pdf PDF page 85'),
  ('13c9fe98-def0-4cc1-9a78-813ffdd9967c'::uuid, 'traffic-rules', 'mock-d-combined-1', 50, 'Why avoid using the horn unnecessarily while passing a motorcyclist?', 'Mengapa perlu elakkan membunyikan hon tanpa perlu ketika memotong motosikal?', '["The rider could swerve","The rider could look ahead","The rider could signal left","The rider could maintain speed"]'::jsonb, '["Penunggang mungkin terpesong","Penunggang mungkin melihat ke hadapan","Penunggang mungkin memberi isyarat kiri","Penunggang mungkin mengekalkan kelajuan"]'::jsonb, 0, 'A horn can startle a rider and cause them to move out of their line.', 'Hon boleh mengejutkan penunggang dan menyebabkan mereka terkeluar daripada laluan.', NULL, 'KPP_D_Manual.pdf PDF page 86'),
  ('b069d9ea-59f8-4053-a5cd-53df4b4c672e'::uuid, 'traffic-rules', 'mock-d-combined-1', 51, 'A tractor is holding up traffic. What is the best time to pass?', 'Traktor memperlahankan aliran trafik. Bilakah masa terbaik untuk memotong?', '["When the queue draws close","When the tractor is slowest","When a car behind starts passing","When passing is permitted and clear"]'::jsonb, '["Apabila barisan kenderaan semakin rapat","Apabila traktor bergerak paling perlahan","Apabila kereta di belakang mula memotong","Apabila memotong dibenarkan dan laluan jelas"]'::jsonb, 3, 'Follow cautiously until an allowed, safe overtaking opportunity appears.', 'Ikut dengan berhati-hati sehingga terdapat peluang memotong yang dibenarkan dan selamat.', NULL, 'KPP_D_Manual.pdf PDF page 88'),
  ('4e246c9f-ce63-4cde-a219-16b2e59ca6a5'::uuid, 'traffic-rules', 'mock-d-combined-1', 52, 'Which blind-spot difference matters when you pass a lorry?', 'Apakah perbezaan titik buta yang penting ketika memotong lori?', '["The lorry has larger blind spots","The lorry has blind spots only behind","The lorry has blind spots only on one side","The lorry has smaller blind spots"]'::jsonb, '["Lori mempunyai titik buta lebih besar","Titik buta lori hanya di belakang","Titik buta lori hanya di sebelah sisi","Lori mempunyai titik buta lebih kecil"]'::jsonb, 0, 'The larger hidden areas make it harder for a lorry driver to see a car alongside.', 'Kawasan terlindung yang lebih besar menyukarkan pemandu lori melihat kereta di sebelahnya.', NULL, 'KPP_D_Manual.pdf PDF page 89'),
  ('df44cf20-ce85-45c0-9edd-870caef7837e'::uuid, 'traffic-rules', 'mock-d-combined-1', 53, 'Which information helps decide which hazard needs attention first?', 'Maklumat manakah membantu menentukan bahaya yang perlu ditangani dahulu?', '["How fast you are closing on it","How long you have been driving","How many times you have used the route","How close you are to your destination"]'::jsonb, '["Kelajuan anda menghampirinya","Tempoh anda sudah memandu","Bilangan kali anda menggunakan laluan itu","Jarak anda dari destinasi"]'::jsonb, 0, 'How quickly you approach a hazard affects the time you have to respond.', 'Kelajuan menghampiri bahaya menentukan masa yang ada untuk bertindak.', NULL, 'KPP_D_Manual.pdf PDF page 97'),
  ('deef9945-11f6-4054-84fd-587bc59d5927'::uuid, 'traffic-rules', 'mock-d-combined-1', 54, 'What happens to your stopping distance as your speed rises?', 'Apakah yang berlaku kepada jarak berhenti apabila kelajuan meningkat?', '["It gets shorter","It stays the same","It gets longer","It depends only on the gear"]'::jsonb, '["Jarak menjadi lebih pendek","Jarak kekal sama","Jarak bertambah panjang","Jarak bergantung pada gear sahaja"]'::jsonb, 2, 'At higher speeds you need more distance to stop if traffic ahead brakes suddenly.', 'Pada kelajuan lebih tinggi, anda memerlukan jarak lebih panjang untuk berhenti jika trafik di hadapan membrek mengejut.', NULL, 'KPP_D_Manual.pdf PDF page 100'),
  ('892428ad-2e78-4c5f-bcb0-1849a8460f10'::uuid, 'traffic-rules', 'mock-d-combined-1', 55, 'What is an airbag designed to do in a collision?', 'Apakah tujuan beg udara apabila berlaku perlanggaran?', '["Keep the doors from unlocking","Stop the tyres from skidding","Hold the steering wheel straight","Reduce the force on occupants"]'::jsonb, '["Menghalang pintu daripada terbuka kunci","Menghalang tayar daripada tergelincir","Memastikan stereng kekal lurus","Mengurangkan daya pada penumpang"]'::jsonb, 3, 'The airbag cushions occupants against the impact of a collision.', 'Beg udara membantu mengurangkan kesan hentaman perlanggaran pada penghuni kenderaan.', NULL, 'KPP_D_Manual.pdf PDF page 160'),
  ('0fa3b704-b7df-4c48-90af-ae6d9b909139'::uuid, 'traffic-rules', 'mock-d-combined-1', 56, 'How does leaving a gap improve what you can see?', 'Bagaimanakah meninggalkan jarak membantu pandangan anda?', '["It makes signals behind clearer","It eliminates the side blind spots","It removes glare from your mirrors","It opens your view ahead"]'::jsonb, '["Ia menjelaskan isyarat di belakang","Ia menghapuskan titik buta di sisi","Ia menghilangkan silau pada cermin","Ia meluaskan pandangan ke hadapan"]'::jsonb, 3, 'Following too closely lets the vehicle ahead block your view of the surrounding road.', 'Mengekor terlalu rapat membolehkan kenderaan di hadapan menghalang pandangan anda terhadap keadaan jalan sekeliling.', NULL, 'KPP_D_Manual.pdf PDF page 105'),
  ('7f5c10dd-a7c7-4fc1-8c01-077b5f988647'::uuid, 'safety-principles', 'mock-d-combined-1', 57, 'Which licence does the curriculum require for ordinary GDL or PSV applications?', 'Lesen manakah diperlukan untuk permohonan GDL atau PSV biasa mengikut kurikulum ini?', '["A learner driving licence","A competent driving licence","A probationary driving licence","An international driving permit"]'::jsonb, '["Lesen belajar memandu","Lesen memandu kompeten","Lesen memandu percubaan","Permit memandu antarabangsa"]'::jsonb, 1, 'The vocational application requirements list a competent driving licence. The probationary licence exception is for Class C only.', 'Syarat permohonan lesen vokasional menyenaraikan lesen memandu kompeten. Pengecualian untuk lesen percubaan hanya bagi Kelas C.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('95ec5a02-6dc7-4615-8321-73f03dccec5c'::uuid, 'safety-principles', 'mock-d-combined-1', 58, 'A PSV bus applicant has completed the course and wants to book the practical test. Which result is needed first?', 'Pemohon PSV bas telah mengikuti kursus dan ingin menempah ujian amali. Keputusan manakah diperlukan dahulu?', '["A pass in vocational theory","A pass in the motorcar theory test alone","A pass in the ordinary road test","A pass in a driving institute trial run"]'::jsonb, '["Lulus ujian teori vokasional","Lulus ujian teori motokar sahaja","Lulus ujian jalan raya biasa","Lulus percubaan di institut memandu"]'::jsonb, 0, 'Vocational practical tests take place after a theory pass. PSV bus applicants are one of the groups required to take a practical test.', 'Ujian amali lesen vokasional dijalankan selepas lulus ujian teori. Pemohon PSV bas ialah antara kumpulan yang perlu menjalani ujian amali.', NULL, 'KPP Kelas DA Automatik, PDF 24'),
  ('69378df3-f033-4069-be53-9eded1dd636c'::uuid, 'safety-principles', 'mock-d-combined-1', 59, 'What does this curriculum say happens to a vocational licence that stays expired for over three years?', 'Apakah yang berlaku kepada lesen vokasional yang tamat tempoh melebihi tiga tahun mengikut kurikulum ini?', '["It is put on probation","It is suspended for a year","It is renewed for a year","It is cancelled"]'::jsonb, '["Lesen diletak dalam percubaan","Lesen digantung setahun","Lesen diperbaharui setahun","Lesen dibatalkan"]'::jsonb, 3, 'The curriculum lists automatic cancellation for a vocational licence that has been expired for more than three years.', 'Kurikulum menyenaraikan pembatalan automatik bagi lesen vokasional yang tamat tempoh melebihi tiga tahun.', NULL, 'KPP Kelas DA Automatik, PDF 25'),
  ('82d20a9d-82bd-46c2-8e61-dceddb3c8769'::uuid, 'safety-principles', 'mock-d-combined-1', 60, 'Which part of the driving test assesses practical driving on public roads?', 'Bahagian ujian memandu manakah menilai pemanduan amali di jalan raya?', '["Part III","Part II","Part I","The theory course"]'::jsonb, '["Bahagian III","Bahagian II","Bahagian I","Kursus teori"]'::jsonb, 0, 'Part II tests circuit skills. Part III tests applying safe driving skills on the road.', 'Bahagian II menguji kemahiran di litar. Bahagian III menguji amalan pemanduan selamat di jalan raya.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('faa3272b-81e4-4890-beec-1f14d7388956'::uuid, 'safety-principles', 'mock-d-combined-1', 61, 'How long must a candidate wait after failing the circuit and road practical tests before retesting, according to this curriculum?', 'Berapa lamakah calon perlu menunggu selepas gagal ujian amali litar dan jalan raya sebelum mengulang ujian mengikut kurikulum ini?', '["One day","One week","Two weeks","One month"]'::jsonb, '["Satu hari","Satu minggu","Dua minggu","Satu bulan"]'::jsonb, 1, 'The book lists a one-week wait after failing the practical driving test before a candidate can retest.', 'Buku menetapkan tempoh menunggu seminggu selepas gagal ujian amali sebelum calon boleh mengulang ujian.', NULL, 'KPP Kelas DA Automatik, PDF 17'),
  ('f1cd2f97-d372-40c8-a097-112e14304bb9'::uuid, 'safety-principles', 'mock-d-combined-1', 62, 'Which form records the training the institute confirms for a practical test booking?', 'Borang manakah merekodkan latihan yang disahkan oleh institut untuk tempahan ujian amali?', '["SM4","A copy of the LDL","The theory test result sheet","The practical test booking slip"]'::jsonb, '["SM4","Salinan LDL","Slip keputusan ujian teori","Slip tempahan ujian amali"]'::jsonb, 0, 'The booking requirements include a copy of the learner licence and the SM4 driving training record.', 'Syarat tempahan termasuk salinan lesen belajar memandu dan rekod latihan memandu SM4.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('8b3ca32d-8c19-4144-92f5-df065e15bb6e'::uuid, 'safety-principles', 'mock-d-combined-1', 63, 'Where does a licence applicant with a disability obtain the medical verification specified in the handbook?', 'Di manakah pemohon lesen yang mempunyai ketidakupayaan mendapatkan pengesahan kesihatan yang dinyatakan dalam buku panduan?', '["A government clinic","The driving institute","A JPJ testing centre","An optical shop"]'::jsonb, '["Klinik kerajaan","Institut memandu","Pusat ujian JPJ","Kedai optik"]'::jsonb, 0, 'The curriculum requires medical verification by a medical officer at a government health clinic.', 'Kurikulum memerlukan pengesahan oleh pegawai perubatan di klinik kesihatan kerajaan.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('d31881b8-9141-44ba-87d6-bbfe40fc1359'::uuid, 'safety-principles', 'mock-d-combined-1', 64, 'When are demerit points counted for a scheduled offence?', 'Bilakah mata demerit dikira bagi kesalahan terjadual?', '["When the summons is issued","After payment of the penalty","When the licence is renewed","When a hearing is scheduled"]'::jsonb, '["Apabila saman dikeluarkan","Selepas penalti dibayar","Apabila lesen diperbaharui","Apabila perbicaraan dijadualkan"]'::jsonb, 1, 'The curriculum ties demerit points to a scheduled offence after the compound payment or court fine has been paid.', 'Kurikulum mengaitkan mata demerit bagi kesalahan terjadual dengan pembayaran kompaun atau denda mahkamah.', NULL, 'KPP General, PDF 93'),
  ('a36f38e3-7abd-4e52-aa10-aef72b072b61'::uuid, 'safety-principles', 'mock-d-combined-1', 65, 'During the manual hill exercise, what must line up with the yellow marking when you stop?', 'Semasa latihan bukit dengan kereta manual, apakah yang perlu berada pada garisan kuning apabila berhenti?', '["The rear wheels","The front wheels","The front bumper","The driver’s door"]'::jsonb, '["Roda belakang","Roda hadapan","Bampar hadapan","Pintu pemandu"]'::jsonb, 1, 'Stop with the front wheels on the yellow line and apply the parking brake. In the test, raise your hand when ready and wait for the instruction to move.', 'Berhenti dengan roda hadapan di atas garisan kuning dan tarik brek tangan. Semasa ujian, angkat tangan apabila sedia dan tunggu arahan untuk bergerak.', NULL, 'KPP Kelas D Manual, PDF 278'),
  ('2c5e480d-8dcc-46f1-8a25-4dcf06c802e8'::uuid, 'safety-principles', 'mock-d-combined-1', 66, 'You are choosing a gear after the traffic ahead slows. What should guide your choice?', 'Anda memilih gear selepas trafik di hadapan memperlahankan kenderaan. Apakah yang patut menentukan pilihan anda?', '["Current speed and power needed","The posted limit and gear last used","The number of lanes and road width","The gear used by the car ahead"]'::jsonb, '["Kelajuan semasa dan kuasa diperlukan","Had tertera dan gear terakhir digunakan","Bilangan lorong dan lebar jalan","Gear yang digunakan oleh kereta di hadapan"]'::jsonb, 0, 'The book says to change gear according to vehicle speed and the power needed.', 'Buku menyatakan gear perlu ditukar mengikut kelajuan dan kuasa yang diperlukan.', NULL, 'KPP Kelas D Manual, PDF 211'),
  ('a1f4f907-588d-4411-8bc8-2b8794196996'::uuid, 'safety-principles', 'mock-d-combined-1', 67, 'What is one purpose of the KEJARA system?', 'Apakah satu tujuan sistem KEJARA?', '["Track vehicle ownership","Set road speed limits","Reduce repeat offences","Manage driving-test bookings"]'::jsonb, '["Merekod pemilikan kenderaan","Menetapkan had laju jalan","Mengurangkan kesalahan berulang","Mengurus tempahan ujian memandu"]'::jsonb, 2, 'One purpose is to discourage repeat offences by educating and disciplining drivers.', 'Antara tujuannya ialah mengurangkan kesalahan berulang dengan mendidik dan mendisiplinkan pemandu.', NULL, 'KPP General, PDF 94'),
  ('c6ccffd4-cb6c-4ad0-a8f5-972ec8c5b87e'::uuid, 'safety-principles', 'mock-d-combined-1', 68, 'A driver with a competent licence reaches 20 KEJARA points for the first time. What does the schedule show?', 'Pemegang lesen kompeten mencapai 20 mata KEJARA buat kali pertama. Apakah tindakan dalam jadual?', '["A suspension","A cancellation","A course referral","A warning"]'::jsonb, '["Penggantungan","Pembatalan","Rujukan kursus","Amaran"]'::jsonb, 3, 'The first 20-point threshold shown in the schedule results in a warning.', 'Ambang 20 mata kali pertama dalam jadual ini membawa kepada amaran.', NULL, 'KPP General, PDF 95'),
  ('00c0f2d4-6f25-4da8-81a2-8c43aef2290b'::uuid, 'safety-principles', 'mock-d-combined-1', 69, 'What kind of offence can lead to KEJARA points?', 'Apakah jenis kesalahan yang boleh menyebabkan mata KEJARA dikenakan?', '["A scheduled traffic offence","An internal parking charge","An insurance contract breach","A missed service appointment"]'::jsonb, '["Kesalahan trafik terjadual","Caj parkir dalaman","Pelanggaran kontrak insurans","Janji temu servis terlepas"]'::jsonb, 0, 'KEJARA applies to scheduled offences under the road transport rules.', 'KEJARA terpakai kepada kesalahan terjadual di bawah peraturan pengangkutan jalan.', NULL, 'KPP General, PDF 93'),
  ('bcbe2526-bf36-4c49-8ffa-5ef19e4a9de3'::uuid, 'safety-principles', 'mock-d-combined-1', 70, 'If a KEJARA points deduction is granted under the handbook’s conditions, what is the upper limit?', 'Jika pengurangan mata KEJARA diberikan mengikut syarat buku panduan, berapakah hadnya?', '["25%","50%","60%","75%"]'::jsonb, '["25%","50%","60%","75%"]'::jsonb, 1, 'The curriculum describes a possible reduction of up to 50% of the demerit points under the listed conditions.', 'Kurikulum menerangkan potongan sehingga 50% daripada mata demerit tertakluk pada syarat yang disenaraikan.', NULL, 'KPP General, PDF 95'),
  ('7395281e-9581-4704-8ce4-f9b64f7aa08d'::uuid, 'road-signs', 'mock-d-combined-2', 1, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["T-junction ahead","Divided road ends","Stop sign ahead","Sharp right bend"]'::jsonb, '["Persimpangan T di hadapan","Jalan terbahagi dua tamat","Tanda berhenti di hadapan","Selekoh tajam ke kanan"]'::jsonb, 0, 'The T shows that your road meets a crossroad and does not continue straight.', 'Bentuk T menunjukkan bahawa jalan anda bertemu jalan melintang dan tidak bersambung lurus.', '/signs/e3ccd470b3c6bc8e.svg', 'KPP General PDF page 42'),
  ('89ec99c0-652d-4c84-9ce1-ce413e5b7b74'::uuid, 'road-signs', 'mock-d-combined-2', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass either side of the island","Pass the island on the left","Pass the island on the right","Merge into a single lane"]'::jsonb, '["Lalui pulau dari mana-mana sisi","Lalui pulau di sebelah kiri","Lalui pulau di sebelah kanan","Bercantum ke satu lorong"]'::jsonb, 0, 'The arrows split around the island. Choose the side that leads to your destination.', 'Anak panah berpecah di sekeliling pulau. Pilih sisi yang menuju ke destinasi anda.', '/signs/322e269754adeff6.svg', 'KPP General PDF page 44'),
  ('672679cb-2cc4-4d5f-b052-b8f04a24f093'::uuid, 'road-signs', 'mock-d-combined-2', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Sharp left bend","Sharp right bend","Roundabout ahead","Stop sign ahead"]'::jsonb, '["Selekoh tajam ke kiri","Selekoh tajam ke kanan","Bulatan di hadapan","Tanda berhenti di hadapan"]'::jsonb, 0, 'The arrow turns sharply left. Reduce speed before the road bends.', 'Anak panah membelok tajam ke kiri. Kurangkan kelajuan sebelum selekoh.', '/signs/194637442da016e5.svg', 'KPP General PDF page 47'),
  ('dce08c59-39dd-43bc-a34a-cca2fe2a03b3'::uuid, 'road-signs', 'mock-d-combined-2', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Sharp right bend","Sharp left bend","Other hazard ahead","T-junction ahead"]'::jsonb, '["Selekoh tajam ke kanan","Selekoh tajam ke kiri","Bahaya lain di hadapan","Persimpangan T di hadapan"]'::jsonb, 0, 'The arrow turns sharply right. Reduce speed before reaching that bend.', 'Anak panah membelok tajam ke kanan. Kurangkan kelajuan sebelum tiba di selekoh itu.', '/signs/8c4124b32afd3704.svg', 'KPP General PDF page 47'),
  ('0ee143f6-d2a2-4df0-9b94-ad375a1247ca'::uuid, 'road-signs', 'mock-d-combined-2', 5, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Direction of a sharp bend","Four-way intersection","Steep downhill stretch","Slippery road surface"]'::jsonb, '["Arah selekoh yang tajam","Persimpangan empat hala","Jalan menurun dengan curam","Permukaan jalan licin"]'::jsonb, 0, 'The chevron points in the direction of the sharp turn. Follow its direction through the bend.', 'Chevron menunjukkan arah belokan tajam. Ikuti arah itu semasa melalui selekoh.', '/signs/b716cb9e685088a5.svg', 'KPP General PDF page 47'),
  ('aac98a7d-f362-4ed4-86ae-d5bedad585e0'::uuid, 'road-signs', 'mock-d-combined-2', 6, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Divided road ends","T-junction ahead","Stop sign ahead","Narrow bridge ahead"]'::jsonb, '["Jalan terbahagi dua tamat","Persimpangan T di hadapan","Tanda berhenti di hadapan","Jambatan sempit di hadapan"]'::jsonb, 0, 'The two sides come together where the divider ends. Watch for vehicles coming toward you.', 'Kedua-dua sisi bertemu apabila pembahagi tamat. Awasi kenderaan dari arah bertentangan.', '/signs/b12139221efc15b6.svg', 'KPP General PDF page 48'),
  ('cb7ff119-7d6b-4d5f-920f-fb356c33a5a3'::uuid, 'road-signs', 'mock-d-combined-2', 7, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Divided road begins","Divided road ends","Two-way traffic ahead","Road narrows on both sides"]'::jsonb, '["Jalan terbahagi dua bermula","Jalan terbahagi dua tamat","Lalu lintas dua hala di hadapan","Jalan menyempit di kedua-dua sisi"]'::jsonb, 0, 'The symbol shows a divider starting between the opposite directions of travel.', 'Simbol menunjukkan pembahagi bermula di antara dua arah perjalanan.', '/signs/788d475c2d05336c.svg', 'KPP General PDF page 48'),
  ('0cde5e5d-e2c0-4d6a-a2aa-c6d9e7cced31'::uuid, 'road-signs', 'mock-d-combined-2', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Roundabout ahead","Sharp left bend","Sharp right bend","Other hazard ahead"]'::jsonb, '["Bulatan di hadapan","Selekoh tajam ke kiri","Selekoh tajam ke kanan","Bahaya lain di hadapan"]'::jsonb, 0, 'The circular arrows indicate a roundabout. Choose your lane before entering and give way to circulating traffic.', 'Anak panah bulat menunjukkan bulatan. Pilih lorong sebelum masuk dan beri laluan kepada trafik yang beredar.', '/signs/d26a8ccc75c5a905.svg', 'KPP General PDF page 48'),
  ('73c2e8c4-e31f-4b84-bf90-11e17804fd36'::uuid, 'road-signs', 'mock-d-combined-2', 9, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Two-way traffic ahead","Side road to the left","Side road to the right","Road narrows on the left"]'::jsonb, '["Lalu lintas dua hala di hadapan","Simpang jalan di sebelah kiri","Simpang jalan di sebelah kanan","Jalan menyempit di sebelah kiri"]'::jsonb, 0, 'The opposite arrows warn that traffic runs in both directions on the road ahead.', 'Anak panah bertentangan memberi amaran bahawa trafik bergerak dalam kedua-dua arah di jalan hadapan.', '/signs/ea082fc0b4c65733.svg', 'KPP General PDF page 49'),
  ('eb4bb394-d027-454e-83ce-a1efdebfbad8'::uuid, 'road-signs', 'mock-d-combined-2', 10, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on both sides","Road narrows on the left","Road narrows on the right","A divided road begins"]'::jsonb, '["Jalan menyempit di kedua-dua sisi","Jalan menyempit di sebelah kiri","Jalan menyempit di sebelah kanan","Jalan terbahagi dua bermula"]'::jsonb, 0, 'Both edges of the symbol move inward, so the available width decreases on both sides.', 'Kedua-dua tepi simbol menuju ke dalam, jadi lebar jalan berkurang pada kedua-dua sisi.', '/signs/ce68f8896451a2c9.svg', 'KPP General PDF page 50'),
  ('3385adfc-5a07-4fc3-ac34-65da8685daab'::uuid, 'road-signs', 'mock-d-combined-2', 11, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on the left","Road narrows on the right","Side road to the right","Two-way traffic ahead"]'::jsonb, '["Jalan menyempit di sebelah kiri","Jalan menyempit di sebelah kanan","Simpang jalan di sebelah kanan","Lalu lintas dua hala di hadapan"]'::jsonb, 0, 'The left edge moves inward while the right edge stays straight. The narrowing is on the left.', 'Tepi kiri menuju ke dalam manakala tepi kanan kekal lurus. Penyempitan berlaku di kiri.', '/signs/2be93e13645351ef.svg', 'KPP General PDF page 50'),
  ('f09d5ff7-fb2e-43e2-9af7-d85b56324139'::uuid, 'road-signs', 'mock-d-combined-2', 12, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on the right","Road narrows on both sides","Road narrows on the left","Side road to the right"]'::jsonb, '["Jalan menyempit di sebelah kanan","Jalan menyempit di kedua-dua sisi","Jalan menyempit di sebelah kiri","Simpang jalan di sebelah kanan"]'::jsonb, 0, 'The right edge moves inward while the left edge stays straight. The narrowing is on the right.', 'Tepi kanan menuju ke dalam manakala tepi kiri kekal lurus. Penyempitan berlaku di kanan.', '/signs/e08ca85fb4d9816f.svg', 'KPP General PDF page 50'),
  ('3bccc627-484c-442e-bead-033b74c1dbf8'::uuid, 'road-signs', 'mock-d-combined-2', 13, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Steep uphill stretch","Narrow bridge ahead","Divided road begins","Steep downhill stretch"]'::jsonb, '["Jalan mendaki dengan curam","Jambatan sempit di hadapan","Jalan terbahagi dua bermula","Jalan menurun dengan curam"]'::jsonb, 0, 'The incline rises in your direction of travel. A lower gear can help on the climb.', 'Cerun naik mengikut arah perjalanan anda. Gear rendah boleh membantu ketika mendaki.', '/signs/fa01479a3e275ae3.svg', 'KPP General PDF page 50'),
  ('36c7b03b-e4aa-4738-8783-627787e0005e'::uuid, 'road-signs', 'mock-d-combined-2', 14, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Steep downhill stretch","Steep uphill stretch","Narrow bridge ahead","Four-way intersection"]'::jsonb, '["Jalan menurun dengan curam","Jalan mendaki dengan curam","Jambatan sempit di hadapan","Persimpangan empat hala"]'::jsonb, 0, 'The incline falls in your direction of travel. A lower gear can help control speed downhill.', 'Cerun menurun mengikut arah perjalanan anda. Gear rendah boleh membantu mengawal kelajuan ketika menurun.', '/signs/eb9c555ec03577f6.svg', 'KPP General PDF page 50'),
  ('8d515960-5fbc-4a96-8aea-7f4a4f24ed5d'::uuid, 'road-signs', 'mock-d-combined-2', 15, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Narrow bridge ahead","A steep descent ahead","Road narrows on the left","Road narrows on the right"]'::jsonb, '["Jambatan sempit di hadapan","Jalan menurun curam di hadapan","Jalan menyempit di sebelah kiri","Jalan menyempit di sebelah kanan"]'::jsonb, 0, 'The bridge symbol warns of limited width. Slow down and check for oncoming traffic before crossing.', 'Simbol jambatan memberi amaran tentang lebar yang terhad. Perlahankan kenderaan dan periksa trafik bertentangan sebelum melintas.', '/signs/d1e9a6d6aab128b3.svg', 'KPP General PDF page 51'),
  ('df5b879d-882b-4d90-bea2-94c9c53ab6d9'::uuid, 'road-signs', 'mock-d-combined-2', 16, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Slippery road surface","Uneven road ahead","Winding road ahead","Soft road shoulder"]'::jsonb, '["Permukaan jalan licin","Jalan tidak rata di hadapan","Jalan berliku di hadapan","Bahu jalan lembut"]'::jsonb, 0, 'The sign warns of a slippery stretch. Brake carefully and keep control of the steering.', 'Tanda ini memberi amaran tentang jalan licin. Brek dengan berhati-hati dan kekalkan kawalan stereng.', '/signs/9702f462c37241a4.svg', 'KPP General PDF page 51'),
  ('2ccbb7b9-b9c1-4567-a5c0-a090efce789b'::uuid, 'road-signs', 'mock-d-combined-2', 17, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Stop sign ahead","T-junction ahead","Divided road ends","Sharp left bend"]'::jsonb, '["Tanda berhenti di hadapan","Persimpangan T di hadapan","Jalan terbahagi dua tamat","Selekoh tajam ke kiri"]'::jsonb, 0, 'The warning is in advance of a stop sign. Slow down so you can stop at the sign itself.', 'Amaran ini diletakkan sebelum tanda berhenti. Perlahankan kenderaan supaya anda boleh berhenti pada tanda sebenar.', '/signs/add368369889404d.svg', 'KPP General PDF page 52'),
  ('5019f572-47b7-4490-ab09-bd4b6305f0ab'::uuid, 'road-signs', 'mock-d-combined-2', 18, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Other hazard ahead","Sharp right bend","Four-way intersection","Sharp left bend"]'::jsonb, '["Bahaya lain di hadapan","Selekoh tajam ke kanan","Persimpangan empat hala","Selekoh tajam ke kiri"]'::jsonb, 0, 'The exclamation mark warns of an unspecified danger ahead. Proceed with care.', 'Tanda seru memberi amaran tentang bahaya yang tidak dinyatakan jenisnya. Pandu dengan berhati-hati.', '/signs/3f13bbd2ffe5c466.svg', 'KPP General PDF page 52'),
  ('9aa3c800-a778-467d-ba52-1bb9b7419e42'::uuid, 'road-signs', 'mock-d-combined-2', 19, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Risk of falling rocks","Steep slope ahead","Soft road shoulder","Loose surface ahead"]'::jsonb, '["Risiko runtuhan batu","Cerun curam di hadapan","Bahu jalan lembut","Permukaan longgar di hadapan"]'::jsonb, 0, 'The rocks shown falling from a slope warn that debris may reach the roadway.', 'Batu yang ditunjukkan jatuh dari cerun memberi amaran bahawa runtuhan mungkin sampai ke jalan.', '/signs/adc5145404e740b4.svg', 'KPP General PDF page 53'),
  ('6033ffb5-a63d-440b-8759-d1330a7e36bd'::uuid, 'road-signs', 'mock-d-combined-2', 20, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Blind pedestrians may cross","Direction of a sharp bend","Steep downhill stretch","Pass either side of the island"]'::jsonb, '["Orang buta mungkin melintas","Arah selekoh yang tajam","Jalan menurun dengan curam","Lalui pulau dari mana-mana sisi"]'::jsonb, 0, 'The sign alerts you to people with impaired vision who may be crossing. Slow and give them time.', 'Tanda ini memberi amaran bahawa orang kurang upaya penglihatan mungkin melintas. Perlahankan kenderaan dan beri mereka masa.', '/signs/f986766e1fca4c02.svg', 'KPP General PDF page 54'),
  ('072bf436-4565-4626-b631-8854f59bd459'::uuid, 'road-signs', 'mock-d-combined-2', 21, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Gated rail crossing","Divided road begins","Narrow bridge ahead","Side road to the left"]'::jsonb, '["Lintasan kereta api berpagar","Jalan terbahagi dua bermula","Jambatan sempit di hadapan","Simpang jalan di sebelah kiri"]'::jsonb, 0, 'The symbol indicates a railway crossing with gates. Wait for the gates to open before proceeding.', 'Simbol menunjukkan lintasan kereta api berpagar. Tunggu pagar dibuka sebelum meneruskan perjalanan.', '/signs/e846f69e41c180a7.svg', 'KPP General PDF page 56'),
  ('e5e5c6b5-0cf3-4011-8235-87628413eba1'::uuid, 'traffic-rules', 'mock-d-combined-2', 22, 'A pedestrian crossing lies ahead of a slower car. What should you do about passing?', 'Lintasan pejalan kaki terletak di hadapan kereta yang lebih perlahan. Apakah tindakan anda mengenai memotong?', '["Wait until after the crossing","Pass just before the crossing","Pass as the car reaches the crossing","Pass if you signal early"]'::jsonb, '["Tunggu sehingga melepasi lintasan","Potong sebelum tiba di lintasan","Potong ketika kereta tiba di lintasan","Potong jika memberi isyarat awal"]'::jsonb, 0, 'Avoid overtaking on the approach to a pedestrian crossing.', 'Elakkan memotong ketika menghampiri lintasan pejalan kaki.', NULL, 'KPP_D_Manual.pdf PDF page 107'),
  ('e78f308b-ad50-414f-8d75-b85a9d4c96eb'::uuid, 'traffic-rules', 'mock-d-combined-2', 23, 'The rear of the car begins to skid while your foot is still on the accelerator. What does the handbook say to do with the pedal?', 'Bahagian belakang kereta mula terbabas semasa kaki anda masih pada pedal pemecut. Apakah tindakan pada pedal yang disarankan oleh buku panduan?', '["Keep the accelerator steady","Release the accelerator promptly","Press the accelerator slightly farther","Add power as the rear moves"]'::jsonb, '["Kekalkan tekanan pada pemecut","Lepaskan pemecut dengan segera","Tekan pedal pemecut sedikit lagi","Tambah kuasa semasa bahagian belakang bergerak"]'::jsonb, 1, 'The handbook says to release the accelerator immediately and steer in the direction the rear is skidding. Straighten as the vehicle recovers.', 'Buku panduan menyatakan supaya pemecut dilepaskan serta-merta dan stereng dipusing mengikut arah bahagian belakang yang terbabas. Luruskan semula apabila kenderaan kembali terkawal.', NULL, 'KPP_D_Manual.pdf PDF page 127'),
  ('72e8b298-4df6-4963-934d-3b47dfa62377'::uuid, 'traffic-rules', 'mock-d-combined-2', 24, 'You see smoke from the engine and suspect a fire. What takes priority?', 'Anda melihat asap dari enjin dan mengesyaki kebakaran. Apakah keutamaannya?', '["Stop safely and get people out","Open the bonnet before stopping","Keep driving to the nearest workshop","Wait inside for the smoke to clear"]'::jsonb, '["Berhenti dengan selamat dan keluarkan semua orang","Buka bonet sebelum berhenti","Terus memandu ke bengkel terdekat","Tunggu di dalam sehingga asap hilang"]'::jsonb, 0, 'Stop, turn off the engine and get passengers out before dealing with the fire.', 'Berhenti, matikan enjin dan keluarkan penumpang sebelum menangani kebakaran.', NULL, 'KPP_D_Manual.pdf PDF page 128'),
  ('4600e390-767c-46df-bc0c-de44801d05c9'::uuid, 'traffic-rules', 'mock-d-combined-2', 25, 'The bonnet opens and blocks your view. How should you slow down?', 'Bonet terbuka dan menghalang pandangan. Bagaimanakah anda patut memperlahankan kenderaan?', '["Keep your speed constant","Brake hard immediately","Brake progressively","Accelerate briefly first"]'::jsonb, '["Kekalkan kelajuan yang sama","Brek kuat serta-merta","Brek secara beransur-ansur","Pecut sebentar dahulu"]'::jsonb, 2, 'Slow gradually and use the side window for guidance as you move to a safe place.', 'Perlahankan kenderaan beransur-ansur dan gunakan tingkap sisi sebagai panduan untuk bergerak ke tempat selamat.', NULL, 'KPP_D_Manual.pdf PDF page 129'),
  ('6dbc9fe5-7ae3-4cd2-9aa0-75f570b224e3'::uuid, 'traffic-rules', 'mock-d-combined-2', 26, 'Where is the safest place to stop for a tyre change?', 'Di manakah tempat paling selamat untuk berhenti bagi menukar tayar?', '["A bend with a wider shoulder","A sloped shoulder beside traffic","A level area away from traffic","A level area in the traffic lane"]'::jsonb, '["Selekoh dengan bahu jalan lebih lebar","Bahu jalan bercerun di sebelah trafik","Kawasan rata jauh daripada trafik","Kawasan rata di dalam lorong trafik"]'::jsonb, 2, 'Level ground helps keep the vehicle stable on a jack. Leave enough space from moving traffic.', 'Permukaan rata membantu memastikan kenderaan stabil pada jek. Tinggalkan ruang yang cukup daripada trafik bergerak.', NULL, 'KPP_D_Manual.pdf PDF page 131'),
  ('4534aaea-98b0-436c-8bcd-37c592f46ee7'::uuid, 'traffic-rules', 'mock-d-combined-2', 27, 'What should you avoid while the car is supported by a jack?', 'Apakah yang perlu dielakkan ketika kereta disokong oleh jek?', '["Checking the jacking point","Fitting the spare wheel","Going underneath the car","Hand-tightening the wheel nuts"]'::jsonb, '["Memeriksa titik jek","Memasang roda ganti","Masuk ke bawah kereta","Mengetatkan nat roda dengan tangan"]'::jsonb, 2, 'A jack can fail or tip. Keep your body out from underneath the vehicle.', 'Jek boleh gagal atau terbalik. Jangan letakkan badan di bawah kenderaan.', NULL, 'KPP_D_Manual.pdf PDF page 132'),
  ('2bad1502-711f-4253-be54-05907686e6a3'::uuid, 'traffic-rules', 'mock-d-combined-2', 28, 'What extra hazard can a narrow rural bend hide?', 'Apakah bahaya tambahan yang mungkin terlindung di selekoh sempit di luar bandar?', '["Following traffic entering a lay-by","Oncoming traffic entering your lane","Parked traffic facing away from you","Traffic joining behind your car"]'::jsonb, '["Trafik di belakang memasuki ruang rehat","Trafik bertentangan memasuki lorong anda","Kenderaan diparkir menghadap arah lain","Trafik masuk di belakang kereta anda"]'::jsonb, 1, 'A vehicle coming the other way may use part of your lane on a narrow bend.', 'Kenderaan dari arah bertentangan mungkin menggunakan sebahagian lorong anda di selekoh sempit.', NULL, 'KPP_D_Manual.pdf PDF page 136'),
  ('712c1c97-a76d-47da-8fb1-409d4eba8b6f'::uuid, 'traffic-rules', 'mock-d-combined-2', 29, 'Why avoid driving too fast on a dark rural road?', 'Mengapa perlu elakkan memandu terlalu laju di jalan luar bandar yang gelap?', '["You may spend longer in low gear","You may use your headlights too long","You may meet fewer passing places","You may see a hazard too late"]'::jsonb, '["Anda mungkin lebih lama menggunakan gear rendah","Lampu hadapan mungkin digunakan terlalu lama","Tempat berselisih mungkin semakin kurang","Bahaya mungkin kelihatan terlalu lewat"]'::jsonb, 3, 'Use a speed that lets you stop if an unseen pedestrian or animal appears.', 'Pilih kelajuan yang membolehkan anda berhenti jika pejalan kaki atau haiwan yang tidak kelihatan muncul.', NULL, 'KPP_D_Manual.pdf PDF page 138'),
  ('150bc84a-ea3b-4011-81ab-38571f4101a1'::uuid, 'traffic-rules', 'mock-d-combined-2', 30, 'What should you do in a busy market area with pedestrians nearby?', 'Apakah yang patut dilakukan di kawasan pasar sibuk dengan pejalan kaki berhampiran?', '["Move closer to the kerb","Hold speed and sound the horn","Slow down and watch for crossings","Focus on the vehicle ahead"]'::jsonb, '["Gerakkan kenderaan lebih dekat dengan bebendul","Kekalkan kelajuan dan bunyikan hon","Perlahankan kenderaan dan awasi orang melintas","Tumpukan pada kenderaan di hadapan"]'::jsonb, 2, 'People may cross in busy areas. Be ready to give way and obey any crossing signals.', 'Orang mungkin melintas di kawasan sibuk. Bersedia untuk memberi laluan dan patuhi lampu isyarat lintasan.', NULL, 'KPP_D_Manual.pdf PDF page 140'),
  ('4a320e91-d623-4b08-a60b-84ab93ca9b5c'::uuid, 'traffic-rules', 'mock-d-combined-2', 31, 'What should you check on the tyres before a long expressway trip?', 'Apakah yang perlu diperiksa pada tayar sebelum perjalanan jauh di lebuh raya?', '["Their pressure and condition","Their pressure after the trip","Their valve caps only","Their surface after the first stop"]'::jsonb, '["Tekanan dan keadaannya","Tekanan selepas perjalanan","Penutup injap sahaja","Permukaan selepas hentian pertama"]'::jsonb, 0, 'Check tyre condition and inflation before setting out.', 'Periksa keadaan dan tekanan angin tayar sebelum memulakan perjalanan.', NULL, 'KPP_D_Manual.pdf PDF page 141'),
  ('08fbc6ba-2e8d-4156-9f66-66e9caede690'::uuid, 'traffic-rules', 'mock-d-combined-2', 32, 'Where should you go after finishing an expressway overtake?', 'Ke manakah anda perlu bergerak selepas selesai memotong di lebuh raya?', '["Stay between the two lanes","Remain in the overtaking lane","Move into the emergency lane","Back to the driving lane"]'::jsonb, '["Kekal di antara kedua-dua lorong","Kekal di lorong memotong","Masuk ke lorong kecemasan","Kembali ke lorong pemanduan"]'::jsonb, 3, 'Use an overtaking lane to pass. Return to the normal driving lane when safe.', 'Gunakan lorong memotong untuk mendahului. Kembali ke lorong pemanduan apabila selamat.', NULL, 'KPP_D_Manual.pdf PDF page 142'),
  ('6cc4f877-667b-4473-829a-f723bcb1f6fb'::uuid, 'traffic-rules', 'mock-d-combined-2', 33, 'Your engine loses power on an expressway, and you cannot continue to the next exit. Where should you stop?', 'Enjin hilang kuasa di lebuh raya dan anda tidak dapat meneruskan perjalanan ke susur keluar seterusnya. Di manakah anda patut berhenti?', '["In the emergency lane","Beside the central divider","In the left traffic lane","In the marked entry lane"]'::jsonb, '["Di lorong kecemasan","Di sebelah pembahagi tengah","Di lorong trafik kiri","Di lorong masuk bertanda"]'::jsonb, 0, 'The shoulder is reserved for emergencies. A slow queue does not justify using it.', 'Lorong kecemasan dikhaskan untuk keadaan kecemasan. Barisan trafik yang perlahan bukan alasan untuk menggunakannya.', NULL, 'KPP Kelas D Manual, PDF pages 129 and 142'),
  ('ba363e1e-960a-43ab-96e4-d2437bfb26ff'::uuid, 'traffic-rules', 'mock-d-combined-2', 34, 'Bright sunlight is scattering across the glass in front of you. What preparation helps reduce it?', 'Cahaya matahari terang berselerak pada kaca di hadapan anda. Persediaan apakah membantu mengurangkannya?', '["Remove dirt from the glass","Raise the rear-view mirror","Move the visor up","Close both side windows"]'::jsonb, '["Bersihkan kotoran pada kaca","Naikkan cermin pandang belakang","Naikkan pengadang matahari","Tutup kedua-dua tingkap sisi"]'::jsonb, 0, 'Clean glass helps reduce glare. Keep enough washer fluid to clean it when needed.', 'Cermin yang bersih membantu mengurangkan silau. Pastikan cecair pencuci mencukupi.', NULL, 'KPP_D_Manual.pdf PDF page 146'),
  ('13cc1f48-1e68-4de1-a3b2-b7bb7a6df227'::uuid, 'traffic-rules', 'mock-d-combined-2', 35, 'You feel too tired to concentrate before leaving. What should you do?', 'Anda terlalu letih untuk memberi tumpuan sebelum bertolak. Apakah tindakan anda?', '["Choose a route with fewer turns","Drive more slowly than usual","Keep a larger gap while driving","Delay the drive until rested"]'::jsonb, '["Pilih laluan yang kurang selekoh","Pandu lebih perlahan daripada biasa","Kekalkan jarak lebih jauh semasa memandu","Tangguhkan perjalanan sehingga segar"]'::jsonb, 3, 'Fatigue undermines concentration. Rest before driving.', 'Keletihan menjejaskan tumpuan. Berehat sebelum memandu.', NULL, 'KPP_D_Manual.pdf PDF page 78'),
  ('5787cce9-79ca-48ec-9c65-d4eda5b0a785'::uuid, 'traffic-rules', 'mock-d-combined-2', 36, 'A driver cuts in front of you and gestures angrily. How should you respond to the gesture?', 'Seorang pemandu masuk ke hadapan anda secara tiba-tiba dan membuat isyarat marah. Bagaimanakah anda patut memberi respons kepada isyarat itu?', '["Flash your headlights once","Raise a hand to question it","Keep driving without responding","Sound a short warning on the horn"]'::jsonb, '["Kelipkan lampu hadapan sekali","Angkat tangan untuk mempersoalkannya","Teruskan pemanduan tanpa membalas","Bunyikan hon seketika sebagai amaran"]'::jsonb, 2, 'Keep calm. The handbook advises against retaliating when another driver behaves aggressively.', 'Bertenang. Buku panduan menasihatkan supaya tidak membalas tindakan pemandu lain yang agresif.', NULL, 'KPP_D_Manual.pdf PDF page 80'),
  ('a052066f-174e-4c57-a485-2cc5ad0c5f98'::uuid, 'traffic-rules', 'mock-d-combined-2', 37, 'Before moving right to overtake, you find traffic coming up behind you. What should you do?', 'Sebelum bergerak ke kanan untuk memotong, anda nampak trafik menghampiri dari belakang. Apakah tindakan anda?', '["Wait until it is safe to move","Move right while signalling","Accelerate into the next lane","Move right as the vehicle draws level"]'::jsonb, '["Tunggu sehingga selamat untuk bergerak","Bergerak ke kanan sambil memberi isyarat","Pecut ke lorong sebelah","Bergerak ke kanan ketika kenderaan berada di sisi"]'::jsonb, 0, 'Check behind and beside you before moving right. Change lanes only when it is safe.', 'Periksa belakang dan sisi sebelum bergerak ke kanan. Tukar lorong hanya apabila selamat.', NULL, 'KPP_D_Manual.pdf PDF page 106'),
  ('cdcd343a-5b0a-41f0-b832-71a0cb275096'::uuid, 'traffic-rules', 'mock-d-combined-2', 38, 'You need more power before passing. What gear change can help?', 'Anda memerlukan lebih kuasa sebelum memotong. Pertukaran gear manakah boleh membantu?', '["Shift briefly to neutral","Select a higher gear","Select a lower gear","Hold the clutch halfway down"]'::jsonb, '["Tukar seketika ke gear bebas","Pilih gear lebih tinggi","Pilih gear lebih rendah","Tekan cekam separuh"]'::jsonb, 2, 'A suitable lower gear can supply more power for the manoeuvre.', 'Gear rendah yang sesuai boleh memberikan lebih kuasa untuk olah gerak itu.', NULL, 'KPP_D_Manual.pdf PDF page 106'),
  ('f9aa61d9-5548-4d77-865b-8a0a6fe305e9'::uuid, 'traffic-rules', 'mock-d-combined-2', 39, 'Before returning left after overtaking, where should the front of the vehicle you passed be visible according to the handbook?', 'Sebelum kembali ke kiri selepas memotong, di manakah bahagian hadapan kenderaan yang dipotong patut kelihatan menurut buku panduan?', '["Right side mirror","Left side mirror","Interior rear-view mirror","Wide-angle parking mirror"]'::jsonb, '["Cermin sisi kanan","Cermin sisi kiri","Cermin pandang belakang dalam","Cermin parkir sudut lebar"]'::jsonb, 1, 'Check the left side mirror for the front of the vehicle you passed. Use CITO before returning.', 'Periksa cermin sisi kiri untuk melihat bahagian hadapan kenderaan yang dipotong. Gunakan CITO sebelum kembali.', NULL, 'KPP_D_Manual.pdf PDF page 106'),
  ('372bf1be-6605-4980-825c-580e46eb66b1'::uuid, 'traffic-rules', 'mock-d-combined-2', 40, 'You are following a slow car into a blind bend. What should you do?', 'Anda mengekori kereta perlahan memasuki selekoh terlindung. Apakah tindakan anda?', '["Stay back until the road opens up","Pass before entering the bend","Move out briefly to check ahead","Pass when the car slows further"]'::jsonb, '["Kekal di belakang sehingga jalan jelas","Potong sebelum memasuki selekoh","Keluar sebentar untuk melihat ke hadapan","Potong apabila kereta lebih perlahan"]'::jsonb, 0, 'Do not overtake at a bend where you cannot see approaching traffic.', 'Jangan memotong di selekoh apabila trafik dari arah bertentangan tidak dapat dilihat.', NULL, 'KPP_D_Manual.pdf PDF page 107'),
  ('af2d18c2-aaed-4ba5-bf1c-16e221339f38'::uuid, 'traffic-rules', 'mock-d-combined-2', 41, 'An oncoming car crosses into your lane. What should you do about speed?', 'Kereta dari arah bertentangan masuk ke lorong anda. Apakah tindakan terhadap kelajuan?', '["Ease off and slow down","Hold your present speed","Speed up to pass sooner","Coast with no braking"]'::jsonb, '["Lepaskan pemecut dan perlahankan kenderaan","Kekalkan kelajuan semasa","Pecut untuk berselisih lebih awal","Luncur tanpa membrek"]'::jsonb, 0, 'Reduce speed while keeping control. Check that it is safe before moving left.', 'Kurangkan kelajuan sambil mengekalkan kawalan. Pastikan selamat sebelum bergerak ke kiri.', NULL, 'KPP_D_Manual.pdf PDF page 108'),
  ('7b0d31d1-748d-4361-8b75-ae5bc0a3de0d'::uuid, 'traffic-rules', 'mock-d-combined-2', 42, 'You have priority at a junction. How should you approach it?', 'Anda mempunyai keutamaan di persimpangan. Bagaimanakah anda patut menghampirinya?', '["Wait until the junction is behind you to slow","Maintain speed until traffic enters","Accelerate to clear it quickly","Slow and watch for other traffic"]'::jsonb, '["Tunggu sehingga melepasi simpang sebelum memperlahankan kenderaan","Kekalkan kelajuan sehingga trafik masuk","Pecut untuk melepasi simpang dengan cepat","Perlahankan kenderaan dan awasi trafik lain"]'::jsonb, 3, 'Priority does not prevent another road user from entering your path.', 'Keutamaan tidak menghalang pengguna jalan lain daripada memasuki laluan anda.', NULL, 'KPP_D_Manual.pdf PDF page 109'),
  ('c458b798-894d-4823-bc9a-c7c971364efe'::uuid, 'traffic-rules', 'mock-d-combined-2', 43, 'At a roundabout entry, which approaching traffic should you give way to?', 'Di pintu masuk bulatan, kepada trafik dari arah mana anda patut beri laluan?', '["Traffic from the right","Traffic from the left","Traffic behind you","Traffic waiting opposite"]'::jsonb, '["Trafik dari arah kanan","Trafik dari arah kiri","Trafik di belakang anda","Trafik yang menunggu bertentangan"]'::jsonb, 0, 'Select the correct lane before entering and give priority to traffic approaching from the right.', 'Pilih lorong yang betul sebelum masuk dan beri keutamaan kepada trafik dari arah kanan.', NULL, 'KPP_D_Manual.pdf PDF page 115'),
  ('f35701ca-2039-4ed2-b09b-629a52727b3f'::uuid, 'traffic-rules', 'mock-d-combined-2', 44, 'What do you use to warn traffic when forced to stop at the roadside in an emergency?', 'Apakah yang digunakan untuk memberi amaran apabila terpaksa berhenti di tepi jalan semasa kecemasan?', '["Right turn signal","Dipped headlights","Interior lights","Hazard lights"]'::jsonb, '["Lampu isyarat kanan","Lampu rendah","Lampu kabin","Lampu kecemasan"]'::jsonb, 3, 'Hazard lights warn others that your vehicle has stopped in an emergency.', 'Lampu kecemasan memberi amaran bahawa kenderaan anda berhenti dalam keadaan kecemasan.', NULL, 'KPP_D_Manual.pdf PDF page 119'),
  ('2abd352c-a8af-4756-987b-18f8a2c94a9f'::uuid, 'traffic-rules', 'mock-d-combined-2', 45, 'A storm makes it hard to see enough road to continue safely. What should you do?', 'Ribut menyebabkan pandangan terlalu terhad untuk meneruskan perjalanan dengan selamat. Apakah tindakan anda?', '["Keep going with high beam","Follow the next car closely","Continue along the road edge","Stop somewhere safe"]'::jsonb, '["Teruskan dengan lampu tinggi","Ikut kereta di hadapan dengan rapat","Teruskan di sepanjang tepi jalan","Berhenti di tempat yang selamat"]'::jsonb, 3, 'When visibility becomes too poor, pause your journey in a safe place.', 'Apabila penglihatan terlalu terhad, hentikan perjalanan sementara di tempat selamat.', NULL, 'KPP_D_Manual.pdf PDF page 122'),
  ('bfba9c8d-4fee-49cd-8b97-2c10411e6ee1'::uuid, 'traffic-rules', 'mock-d-combined-2', 46, 'Sun glare makes the road hard to see. What should change about your driving?', 'Silau matahari menyukarkan anda melihat jalan. Apakah yang patut diubah semasa memandu?', '["Keep speed and lengthen your gap","Slow down only before bends","Reduce speed to suit your view","Match the speed of the car ahead"]'::jsonb, '["Kekalkan kelajuan dan tambah jarak","Perlahankan hanya sebelum selekoh","Kurangkan kelajuan mengikut jarak penglihatan","Ikut kelajuan kereta di hadapan"]'::jsonb, 2, 'Adjust your speed to suit the visibility when glare makes it harder to see.', 'Sesuaikan kelajuan dengan jarak penglihatan apabila silau menyukarkan anda melihat.', NULL, 'KPP_D_Manual.pdf PDF page 123'),
  ('03928540-f326-42a6-a7e2-086493b0b212'::uuid, 'traffic-rules', 'mock-d-combined-2', 47, 'When can high beam help on an unlit road?', 'Bilakah lampu tinggi boleh membantu di jalan tanpa lampu jalan?', '["When driving through busy streets","When approaching oncoming traffic","When following a car closely","When it will not dazzle anyone"]'::jsonb, '["Apabila melalui jalan yang sibuk","Apabila trafik bertentangan menghampiri","Apabila mengekori kereta dengan rapat","Apabila tidak menyilaukan orang lain"]'::jsonb, 3, 'High beam extends your view but should not be used where it dazzles others.', 'Lampu tinggi memanjangkan jarak penglihatan tetapi tidak patut digunakan jika menyilaukan orang lain.', NULL, 'KPP_D_Manual.pdf PDF page 145'),
  ('2dd73eb8-b4ae-447f-8b1c-75e45393ded9'::uuid, 'traffic-rules', 'mock-d-combined-2', 48, 'Why allow extra stopping room on a wet road?', 'Mengapa perlu sediakan ruang berhenti tambahan di jalan basah?', '["Tyre pressure rises quickly","Tyres have more rolling resistance","Tyres have less grip","The brake pedal travels farther"]'::jsonb, '["Tekanan tayar meningkat cepat","Rintangan gelinciran tayar bertambah","Cengkaman tayar berkurangan","Pedal brek bergerak lebih jauh"]'::jsonb, 2, 'Reduced grip increases the distance needed to stop.', 'Cengkaman yang berkurangan meningkatkan jarak yang diperlukan untuk berhenti.', NULL, 'KPP_D_Manual.pdf PDF page 147'),
  ('81068fa0-bef0-478a-a677-b43e185dbc89'::uuid, 'traffic-rules', 'mock-d-combined-2', 49, 'What can a strong crosswind do to a small car?', 'Apakah kesan angin lintang kuat terhadap kereta kecil?', '["Make it accelerate downhill","Pull it backwards","Push it sideways","Make it turn into the wind"]'::jsonb, '["Membuatnya memecut menuruni bukit","Menariknya ke belakang","Menolaknya ke sisi","Membuatnya membelok ke arah angin"]'::jsonb, 2, 'A gust can displace the car toward an adjacent lane.', 'Tiupan angin boleh menolak kereta ke arah lorong bersebelahan.', NULL, 'KPP_D_Manual.pdf PDF page 148'),
  ('0fd13847-aeae-45f5-b7fe-31a39b895d99'::uuid, 'traffic-rules', 'mock-d-combined-2', 50, 'Floodwater ahead looks too deep for the car. What should you do?', 'Air banjir di hadapan kelihatan terlalu dalam untuk kereta. Apakah tindakan anda?', '["Cross behind a larger vehicle","Turn back and take another route","Try the middle of the road","Build speed before entering"]'::jsonb, '["Lintas di belakang kenderaan lebih besar","Patah balik dan guna laluan lain","Cuba melalui bahagian tengah jalan","Tambah kelajuan sebelum masuk"]'::jsonb, 1, 'Do not risk deep water. Water entering the air intake can damage the engine.', 'Jangan mengambil risiko melalui air dalam. Air yang memasuki salur masuk udara boleh merosakkan enjin.', NULL, 'KPP_D_Manual.pdf PDF page 149'),
  ('9096fc67-cf48-4ae9-aac5-0d8c6a060e6b'::uuid, 'traffic-rules', 'mock-d-combined-2', 51, 'A slow car is ahead on a two-way road in fog. What should you do?', 'Kereta perlahan berada di hadapan di jalan dua hala yang berkabus. Apakah tindakan anda?', '["Close in until the fog thins","Pass using the centre line","Follow at a safe gap","Pass with your hazards on"]'::jsonb, '["Rapatkan jarak sehingga kabus menipis","Potong dengan menggunakan garisan tengah","Ikut pada jarak yang selamat","Potong dengan lampu kecemasan dihidupkan"]'::jsonb, 2, 'Fog makes it hard to judge oncoming traffic, so avoid overtaking and leave room to stop.', 'Kabus menyukarkan anda menilai trafik bertentangan. Elakkan memotong dan tinggalkan ruang untuk berhenti.', NULL, 'KPP_D_Manual.pdf PDF page 150'),
  ('cab9b4b0-f9ea-468e-be71-7d34acc0591f'::uuid, 'traffic-rules', 'mock-d-combined-2', 52, 'Before a trip, how do you check the engine oil level under the bonnet?', 'Sebelum bertolak, bagaimanakah anda memeriksa paras minyak enjin di bawah bonet?', '["Read the marks on the dipstick","Look through the filler opening","Read the level on the coolant tank","Check the colour under the oil cap"]'::jsonb, '["Baca tanda pada batang celup","Lihat melalui lubang pengisi","Baca paras pada tangki penyejuk","Periksa warna di bawah penutup minyak"]'::jsonb, 0, 'Use the dipstick to check the oil level during regular maintenance.', 'Gunakan batang penyukat untuk memeriksa aras minyak semasa penyelenggaraan berkala.', NULL, 'KPP_D_Manual.pdf PDF page 152'),
  ('4946e42c-6121-4ac3-8f6e-79822659087f'::uuid, 'traffic-rules', 'mock-d-combined-2', 53, 'Which condition is the cooling system, including the radiator, designed to prevent?', 'Keadaan manakah yang direka untuk dicegah oleh sistem penyejukan, termasuk radiator?', '["The engine overheating","The engine oil running low","The fuel supply running low","The battery losing its charge"]'::jsonb, '["Enjin terlalu panas","Minyak enjin berkurang","Bekalan bahan api berkurang","Bateri kehilangan cas"]'::jsonb, 0, 'The radiator is part of the cooling system that regulates engine temperature.', 'Radiator ialah sebahagian daripada sistem penyejuk yang mengawal suhu enjin.', NULL, 'KPP_D_Manual.pdf PDF page 153'),
  ('3a2322c5-fa55-4a12-91ad-d65958af8d12'::uuid, 'traffic-rules', 'mock-d-combined-2', 54, 'You find a hose loose during a check under the bonnet. What should happen before the trip?', 'Anda menemui hos longgar semasa memeriksa ruang enjin. Apakah yang perlu dilakukan sebelum perjalanan?', '["Secure or replace the hose","Top up fluid and leave it loose","Drive until the engine warms","Recheck only if a warning appears"]'::jsonb, '["Ketatkan atau gantikan hos","Tambah cecair dan biarkan longgar","Pandu sehingga enjin panas","Periksa semula jika amaran muncul"]'::jsonb, 0, 'Inspect hoses for leaks and loose fittings. Tighten or replace a faulty hose.', 'Periksa hos untuk kebocoran dan sambungan longgar. Ketatkan atau gantikan hos yang rosak.', NULL, 'KPP_D_Manual.pdf PDF page 155'),
  ('c7941030-5c85-424f-a373-8dedc59427c0'::uuid, 'traffic-rules', 'mock-d-combined-2', 55, 'You are travelling only a short distance. When should you fasten your seat belt?', 'Anda hanya akan bergerak dalam jarak dekat. Bilakah tali pinggang keledar perlu dipasang?', '["When joining the main road","After leaving the car park","Before moving off","When the speed rises"]'::jsonb, '["Apabila memasuki jalan utama","Selepas keluar dari tempat letak kereta","Sebelum mula bergerak","Apabila kelajuan meningkat"]'::jsonb, 2, 'Wear a seat belt even on a short trip.', 'Pakai tali pinggang keledar walaupun untuk perjalanan singkat.', NULL, 'KPP_D_Manual.pdf PDF page 157'),
  ('adc0efd3-ae15-4da9-8f2d-d64266305652'::uuid, 'traffic-rules', 'mock-d-combined-2', 56, 'Why use an appropriate child restraint?', 'Mengapa perlu menggunakan kerusi keselamatan kanak-kanak yang sesuai?', '["To stop the rear door opening","To reduce injuries in a crash","To improve the driver''s rear view","To keep the child from using a window"]'::jsonb, '["Untuk mengelakkan pintu belakang dibuka","Untuk mengurangkan kecederaan dalam kemalangan","Untuk memperbaik pandangan belakang pemandu","Untuk mengelakkan kanak-kanak menggunakan tingkap"]'::jsonb, 1, 'A child restraint helps protect a child passenger if a collision happens.', 'Kerusi keselamatan kanak-kanak membantu melindungi penumpang kanak-kanak jika berlaku perlanggaran.', NULL, 'KPP_D_Manual.pdf PDF page 158'),
  ('587c8ab7-1449-4527-8355-3fd1d5c3ef0c'::uuid, 'safety-principles', 'mock-d-combined-2', 57, 'Which plan is allowed while your driving licence is suspended?', 'Rancangan manakah dibenarkan ketika lesen memandu anda digantung?', '["Ask someone else to drive you","Drive a borrowed car to work","Ride a different vehicle class","Take a short drive for essentials"]'::jsonb, '["Minta orang lain memandu anda","Pandu kereta pinjaman ke tempat kerja","Tunggang kenderaan kelas lain","Pandu sekejap untuk urusan penting"]'::jsonb, 0, 'Suspension prevents the person from driving. Changing vehicles does not remove the restriction.', 'Penggantungan melarang orang itu daripada memandu. Menukar kenderaan tidak menamatkan larangan tersebut.', NULL, 'KPP General, PDF 96'),
  ('d97dda98-5f4b-4063-a0ee-afbd0d7ca935'::uuid, 'safety-principles', 'mock-d-combined-2', 58, 'What must a former probationary driver repeat after a cancellation ban ends?', 'Apakah yang perlu diulang oleh bekas pemegang lesen percubaan selepas larangan pembatalan tamat?', '["The medical form alone","The licence renewal alone","The training and tests","The probation period alone"]'::jsonb, '["Borang kesihatan sahaja","Pembaharuan lesen sahaja","Latihan dan ujian","Tempoh percubaan sahaja"]'::jsonb, 2, 'The curriculum requires the training and tests again, followed by a new probation period.', 'Kurikulum memerlukan latihan dan ujian semula, diikuti tempoh percubaan yang baharu.', NULL, 'KPP Kelas DA Automatik, PDF 21'),
  ('cb5c2f58-9202-4bb8-bc84-d470c6773bf8'::uuid, 'safety-principles', 'mock-d-combined-2', 59, 'What should you look for under the car during a pre-drive walk-around?', 'Apakah yang perlu diperiksa di bawah kereta sebelum memandu?', '["Signs of tread wear","Loose washer nozzles","A blocked air filter","Signs of a leak"]'::jsonb, '["Tanda bunga tayar haus","Muncung pencuci longgar","Penapis udara tersumbat","Tanda kebocoran"]'::jsonb, 3, 'Look underneath to see whether anything is leaking before setting off.', 'Lihat di bawah kereta untuk mengesan sebarang kebocoran sebelum bergerak.', NULL, 'KPP Kelas D Manual, PDF 231'),
  ('599360d1-a7d7-4640-8055-07728bd477ec'::uuid, 'safety-principles', 'mock-d-combined-2', 60, 'What should you check on the number plates during a walk-around?', 'Apakah yang perlu diperiksa pada plat nombor semasa pemeriksaan keliling kereta?', '["Clean and undamaged","Readable and loosely attached","Secure and covered with dirt","Straight and cracked"]'::jsonb, '["Bersih dan tidak rosak","Boleh dibaca dan longgar","Kukuh dan dilitupi kotoran","Lurus dan retak"]'::jsonb, 0, 'Check that the plates are clean and undamaged.', 'Pastikan plat nombor bersih dan tidak rosak.', NULL, 'KPP Kelas D Manual, PDF 230'),
  ('a9f7fbda-44b3-42bd-bb9b-da72993dfb23'::uuid, 'safety-principles', 'mock-d-combined-2', 61, 'When should you choose a suitable speed for a bend?', 'Bilakah anda perlu memilih kelajuan yang sesuai untuk selekoh?', '["When you reach its middle","While approaching it","After clearing it","When the steering straightens"]'::jsonb, '["Apabila sampai ke tengahnya","Ketika menghampirinya","Selepas melepasinya","Apabila stereng diluruskan"]'::jsonb, 1, 'Choose a suitable speed as you approach, maintain control through the bend, and only increase speed after clearing it.', 'Pilih kelajuan yang sesuai ketika menghampiri selekoh, kekalkan kawalan semasa melaluinya dan tingkatkan kelajuan selepas melepasi selekoh.', NULL, 'KPP Kelas D Manual, PDF 251'),
  ('d930ec8f-7084-45e7-915f-dbacc3bde91d'::uuid, 'safety-principles', 'mock-d-combined-2', 62, 'Which action does the manual circuit lesson advise against while going through an S-bend?', 'Apakah tindakan yang perlu dielakkan ketika melalui selekoh S dalam latihan litar manual?', '["Steering with both hands","Holding a steady speed","Changing gears","Following the curve"]'::jsonb, '["Memegang stereng dengan dua tangan","Mengekalkan kelajuan","Menukar gear","Mengikut lengkung selekoh"]'::jsonb, 2, 'The lesson says to use the pull-push steering technique, keep speed steady, and avoid gear changes and braking while passing through the bend.', 'Gunakan teknik tarik dan tolak pada stereng, kekalkan kelajuan dan elakkan menukar gear serta membrek semasa melalui selekoh.', NULL, 'KPP Kelas D Manual, PDF 253'),
  ('d0ba6a9d-e752-42d4-bef0-e91f98a75909'::uuid, 'safety-principles', 'mock-d-combined-2', 63, 'Which finding means a wiper blade may leave water on the windscreen?', 'Penemuan manakah menunjukkan bilah pengelap mungkin meninggalkan air pada cermin?', '["The rubber bends easily","The edge has small splits","The edge lies flat on the glass","The blade follows the glass curve"]'::jsonb, '["Getah mudah melentur","Tepi bilah ada rekahan kecil","Tepi bilah rata pada cermin","Bilah mengikut lengkung cermin"]'::jsonb, 1, 'Hardened, cracked or torn blade rubber may leave water behind or scratch the glass.', 'Getah bilah yang keras, retak atau koyak mungkin meninggalkan air atau mencalarkan cermin.', NULL, 'KPP Kelas D Manual, PDF 229'),
  ('0f8bbfd9-0f7f-4684-bd45-14cd50ae9268'::uuid, 'safety-principles', 'mock-d-combined-2', 64, 'Where does the curriculum say to look for the car manufacturer’s recommended tyre inflation?', 'Di manakah kurikulum menyatakan anda boleh melihat cadangan pengeluar tentang angin tayar kereta?', '["On the tyre tread label","On the wheel nut cap","On the driver’s door label","On the windscreen sticker"]'::jsonb, '["Pada label bunga tayar","Pada penutup nat roda","Pada label pintu pemandu","Pada pelekat cermin hadapan"]'::jsonb, 2, 'Look for the manufacturer’s tyre pressure label on the side of the driver’s door.', 'Cari label tekanan angin tayar pengeluar di bahagian tepi pintu pemandu.', NULL, 'KPP Kelas D Manual, PDF 228'),
  ('4bd65322-fa76-4b43-a87e-d0aa795f2bff'::uuid, 'safety-principles', 'mock-d-combined-2', 65, 'Which tyre fails the visual condition check even if its tread is deep?', 'Tayar manakah gagal pemeriksaan fizikal walaupun bunganya masih dalam?', '["A tyre with even wear","A tyre with deep grooves","A tyre with mould marks","A tyre with a bulge"]'::jsonb, '["Tayar yang haus sekata","Tayar dengan alur dalam","Tayar dengan kesan acuan","Tayar yang menggelembung"]'::jsonb, 3, 'During the visual inspection, check that tyres are free from bulges, cracks and tears.', 'Pastikan tayar tidak menggelembung, merekah atau koyak semasa pemeriksaan.', NULL, 'KPP Kelas D Manual, PDF 228'),
  ('f2868cb0-7596-4050-8cb7-a46b0ac6605c'::uuid, 'safety-principles', 'mock-d-combined-2', 66, 'Which wheel service does the handbook link to even tread wear?', 'Servis roda manakah yang dikaitkan dengan kehausan bunga tayar sekata dalam buku panduan?', '["Wheel alignment","Wheel balancing","Brake adjustment","Wheel bearing service"]'::jsonb, '["Penjajaran roda","Pengimbangan roda","Pelarasan brek","Servis galas roda"]'::jsonb, 0, 'Alignment helps tread wear evenly. Balancing helps the wheel turn without vibration.', 'Penjajaran membantu bunga tayar haus secara sekata. Pengimbangan membantu roda berputar tanpa gegaran.', NULL, 'KPP Kelas D Manual, PDF 228'),
  ('1db7b128-1e6a-48a5-bb65-2913493b395c'::uuid, 'safety-principles', 'mock-d-combined-2', 67, 'Where should the engine oil level sit on the dipstick?', 'Di manakah paras minyak enjin sepatutnya berada pada batang penyukat?', '["Below the lower mark","Between the two marks","Above the upper mark","Exactly on the lower mark"]'::jsonb, '["Di bawah tanda bawah","Antara kedua-dua tanda","Di atas tanda atas","Tepat pada tanda bawah"]'::jsonb, 1, 'The book says to check that the level is between the minimum and maximum marks.', 'Buku menyatakan paras minyak perlu berada antara tanda minimum dan maksimum.', NULL, 'KPP Kelas D Manual, PDF 232'),
  ('e72a5dbf-927f-48e9-88e9-aeca861f721c'::uuid, 'safety-principles', 'mock-d-combined-2', 68, 'The washer reservoir is accessible under the bonnet. Which check can you do there?', 'Takungan pencuci boleh dicapai di bawah bonet. Pemeriksaan manakah boleh dibuat di situ?', '["Check whether fluid needs topping up","Check whether fluid reaches the glass","Check how far the fluid sprays","Check which spray jet is blocked"]'::jsonb, '["Semak sama ada cecair perlu ditambah","Semak sama ada cecair sampai ke kaca","Semak sejauh mana cecair menyembur","Semak muncung semburan yang tersumbat"]'::jsonb, 0, 'Check that the washer reservoir contains enough fluid.', 'Pastikan cecair dalam tangki pencuci cermin mencukupi.', NULL, 'KPP Kelas D Manual, PDF 233'),
  ('31df1c2e-2439-4be1-b5aa-b79fd12950f7'::uuid, 'safety-principles', 'mock-d-combined-2', 69, 'Which hose condition should you report during a check under the bonnet?', 'Keadaan hos manakah yang perlu dilaporkan semasa pemeriksaan di bawah bonet?', '["A smooth curved route","An intact hose clamp","A dry outer surface","A crack or a bulge"]'::jsonb, '["Laluan melengkung licin","Pengapit hos masih elok","Permukaan luar kering","Rekah atau bengkak"]'::jsonb, 3, 'Check that hoses have no leaks, cracks or swelling.', 'Pastikan hos tidak bocor, merekah atau mengembang.', NULL, 'KPP Kelas D Manual, PDF 234'),
  ('ec2b57bd-1e8e-4319-8806-35e7d02f95e6'::uuid, 'safety-principles', 'mock-d-combined-2', 70, 'When replacing a tyre, which tool loosens the nuts before you remove the wheel?', 'Ketika mengganti tayar, alat manakah melonggarkan nat sebelum roda ditanggalkan?', '["A wheel brace","A tyre lever","A pressure gauge","A tow hook"]'::jsonb, '["Sepana roda","Tuil tayar","Tolok tekanan","Cangkuk tunda"]'::jsonb, 0, 'The book includes a wheel-nut wrench among the emergency tools to check in the boot.', 'Buku menyenaraikan pembuka nat roda antara peralatan kecemasan yang perlu diperiksa dalam but.', NULL, 'KPP Kelas D Manual, PDF 231'),
  ('e85eae7f-9574-474f-9478-3d097311a43f'::uuid, 'road-signs', 'mock-da-combined-1', 1, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on the left","Pass on the right","Use the left lane ahead","Turn left at the junction"]'::jsonb, '["Lalu di sebelah kiri","Lalu di sebelah kanan","Gunakan lorong kiri di hadapan","Belok kiri di persimpangan"]'::jsonb, 0, 'This sign means pass on the left.', 'Papan tanda ini bermaksud lalu di sebelah kiri.', '/signs/24dc89f9e7127cca.svg', 'KPP General PDF page 64'),
  ('ba55a50d-6e18-4bf8-9fb2-0bf57c619f9d'::uuid, 'road-signs', 'mock-da-combined-1', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on the right","Pass on the left","Turn right ahead","Keep to the right lane"]'::jsonb, '["Lalu di sebelah kanan","Lalu di sebelah kiri","Belok kanan di hadapan","Kekal di lorong kanan"]'::jsonb, 0, 'This sign means pass on the right.', 'Papan tanda ini bermaksud lalu di sebelah kanan.', '/signs/a50c8dd8a202a25e.svg', 'KPP General PDF page 64'),
  ('6bf800a0-a1fb-4472-b91d-8be27fe6ed28'::uuid, 'road-signs', 'mock-da-combined-1', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on either side","Pass on the left","Keep to the centre","Use the left branch only"]'::jsonb, '["Lalu di mana-mana sisi","Lalu di sebelah kiri","Kekal di tengah","Gunakan cabang kiri sahaja"]'::jsonb, 0, 'This sign means pass on either side.', 'Papan tanda ini bermaksud lalu di mana-mana sisi.', '/signs/6103dff69316bf86.svg', 'KPP General PDF page 64'),
  ('4c0eff6f-4697-4507-8eb9-f549620ea53b'::uuid, 'road-signs', 'mock-da-combined-1', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for motorcycles","Lane for bicycles","Lane for taxis","Lane for buses"]'::jsonb, '["Lorong untuk motosikal","Lorong untuk basikal","Lorong untuk teksi","Lorong untuk bas"]'::jsonb, 0, 'This sign means lane for motorcycles.', 'Papan tanda ini bermaksud lorong untuk motosikal.', '/signs/e0389a069e72ed52.png', 'KPP General PDF page 65'),
  ('c5803f6d-b8d1-45f9-b6e3-2c3506c9e448'::uuid, 'road-signs', 'mock-da-combined-1', 5, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for bicycles","Lane for motorcycles","Lane for trishaws","Lane for pedestrians"]'::jsonb, '["Lorong untuk basikal","Lorong untuk motosikal","Lorong untuk beca","Lorong untuk pejalan kaki"]'::jsonb, 0, 'This sign means lane for bicycles.', 'Papan tanda ini bermaksud lorong untuk basikal.', '/signs/e86785fec1877d75.png', 'KPP General PDF page 65'),
  ('9bf577a8-8afb-49b8-a8dc-3e3508d8adaa'::uuid, 'road-signs', 'mock-da-combined-1', 6, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["No right turn","No left turn","No U-turn","Turn right only"]'::jsonb, '["Dilarang belok kanan","Dilarang belok kiri","Dilarang membuat pusingan U","Belok kanan sahaja"]'::jsonb, 0, 'The crossed right arrow bans a right turn at that junction.', 'Anak panah kanan yang dipalang melarang pemandu membelok ke kanan di simpang itu.', '/signs/2eee15e55fa0ef48.svg', 'KPP General PDF page 57'),
  ('c457bf51-8b2f-4a1e-bb0e-3e4d1e8c7fde'::uuid, 'road-signs', 'mock-da-combined-1', 7, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for bicycles","Lane for trishaws","Lane for buses","Lane for taxis"]'::jsonb, '["Lorong untuk basikal","Lorong untuk beca","Lorong untuk bas","Lorong untuk teksi"]'::jsonb, 1, 'This sign means lane for trishaws.', 'Papan tanda ini bermaksud lorong untuk beca.', '/signs/fad437bbc08b75fa.png', 'KPP General PDF page 65'),
  ('75b9c5b9-1335-45ff-a02a-db4ca9023ef8'::uuid, 'road-signs', 'mock-da-combined-1', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Medical clinic","Public telephone","Hospital","Bus stop"]'::jsonb, '["Klinik perubatan","Telefon awam","Hospital","Perhentian bas"]'::jsonb, 2, 'This sign means hospital.', 'Papan tanda ini bermaksud hospital.', '/signs/dde5874c6044c5f3.svg', 'KPP General PDF page 67'),
  ('eac102da-1618-4740-9fb1-61b86a8dc3d8'::uuid, 'road-signs', 'mock-da-combined-1', 9, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Vehicle parking","Medical clinic","JPJ weighing station","Public telephone"]'::jsonb, '["Tempat letak kenderaan","Klinik perubatan","Stesen timbang JPJ","Telefon awam"]'::jsonb, 0, 'This sign means vehicle parking.', 'Papan tanda ini bermaksud tempat letak kenderaan.', '/signs/f6459f68e216bc5d.svg', 'KPP General PDF page 67'),
  ('e6615047-2b56-4c55-958f-2795294b03c8'::uuid, 'road-signs', 'mock-da-combined-1', 10, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Distance to a destination exit","Directions at a junction ahead","Distances to upcoming destinations","Road with no through access"]'::jsonb, '["Jarak ke susur keluar destinasi","Arah di simpang yang akan datang","Jarak ke destinasi seterusnya","Jalan buntu di hadapan"]'::jsonb, 3, 'This sign means road with no through access. The road does not continue through to another route.', 'Papan tanda ini bermaksud jalan buntu di hadapan. Jalan itu tidak bersambung dengan laluan lain.', '/signs/082877f6ec086be6.svg', 'KPP General PDF page 68'),
  ('fcb17219-40af-4638-a020-66e3a0277753'::uuid, 'road-signs', 'mock-da-combined-1', 11, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Designated U-turn","Designated P-turn","Road with no through access","Directions at a junction ahead"]'::jsonb, '["Tempat pusingan U","Tempat pusingan P","Jalan buntu di hadapan","Arah di simpang yang akan datang"]'::jsonb, 0, 'This sign means designated U-turn. It marks a place to turn around. Give way to oncoming traffic before turning.', 'Papan tanda ini bermaksud tempat pusingan U. Tanda ini menunjukkan tempat untuk berpatah balik. Beri laluan kepada trafik dari arah bertentangan sebelum membelok.', '/signs/8956fe8a103938b3.svg', 'KPP General PDF page 69'),
  ('8ad02e8f-35fd-4fd6-8001-2db5a212b360'::uuid, 'road-signs', 'mock-da-combined-1', 12, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No vehicle entry","No overtaking","No stopping","No through road"]'::jsonb, '["Kenderaan dilarang masuk","Dilarang memotong","Dilarang berhenti","Jalan buntu"]'::jsonb, 0, 'This sign means no vehicle entry.', 'Papan tanda ini bermaksud kenderaan dilarang masuk.', '/signs/9a316a4baac9f49a.svg', 'KPP General PDF page 57'),
  ('9b9a5636-975b-4683-9cfa-a5ad1e23d977'::uuid, 'road-signs', 'mock-da-combined-1', 13, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No U-turn","No right turn","No left turn","Right turn only"]'::jsonb, '["Dilarang membuat pusingan U","Dilarang membelok ke kanan","Dilarang membelok ke kiri","Belok kanan sahaja"]'::jsonb, 0, 'This sign means no U-turn.', 'Papan tanda ini bermaksud dilarang membuat pusingan U.', '/signs/a299aef5bccc0fca.svg', 'KPP General PDF page 58'),
  ('526d64b9-e14d-42ed-96f4-fe9a47be0fc0'::uuid, 'road-signs', 'mock-da-combined-1', 14, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No vehicle entry","No right turn","No U-turn","No left turn"]'::jsonb, '["Kenderaan dilarang masuk","Dilarang membelok ke kanan","Dilarang membuat pusingan U","Dilarang membelok ke kiri"]'::jsonb, 3, 'You must use a route that does not require turning left here.', 'Gunakan laluan yang tidak memerlukan anda membelok ke kiri di sini.', '/signs/ef495735d6870ce2.svg', 'KPP General PDF page 57'),
  ('22026a96-4d97-4f3e-8092-092f9f1993b7'::uuid, 'road-signs', 'mock-da-combined-1', 15, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No parking","No stopping","No entry","No waiting at the junction"]'::jsonb, '["Dilarang meletak kenderaan","Dilarang berhenti","Dilarang masuk","Dilarang menunggu di persimpangan"]'::jsonb, 0, 'This sign means no parking.', 'Papan tanda ini bermaksud dilarang meletak kenderaan.', '/signs/fbd415b24ab21b44.svg', 'KPP General PDF page 58'),
  ('941391f7-6766-45f4-9602-a4c5dcd4b190'::uuid, 'road-signs', 'mock-da-combined-1', 16, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Left lane closes ahead","Keep right of an obstacle","Traffic merges from the right","Route changes direction to the right"]'::jsonb, '["Lorong kiri ditutup di hadapan","Lalu di kanan halangan","Trafik bercantum dari kanan","Laluan berubah arah ke kanan"]'::jsonb, 3, 'The single orange chevron points the way when the route changes direction in a work zone.', 'Satu tanda serong jingga menunjukkan arah apabila laluan berubah dalam zon kerja.', '/signs/263bc825012bcc83.svg', 'KPP General PDF page 76'),
  ('d3c37c90-efeb-4e5a-8654-2851a599cc95'::uuid, 'road-signs', 'mock-da-combined-1', 17, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No stopping","No overtaking","No left turn","No parking"]'::jsonb, '["Dilarang berhenti","Dilarang memotong","Dilarang membelok ke kiri","Dilarang meletak kenderaan"]'::jsonb, 0, 'This sign means no stopping.', 'Papan tanda ini bermaksud dilarang berhenti.', '/signs/ecd3d648f3d4a187.svg', 'KPP General PDF page 59'),
  ('c35f68c3-780a-4cf2-999e-4260caeb7f53'::uuid, 'road-signs', 'mock-da-combined-1', 18, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No sounding the horn","No stopping","No motor vehicle entry","No overtaking"]'::jsonb, '["Dilarang membunyikan hon","Dilarang berhenti","Kenderaan bermotor dilarang masuk","Dilarang memotong"]'::jsonb, 0, 'This sign means no sounding the horn.', 'Papan tanda ini bermaksud dilarang membunyikan hon.', '/signs/ce55b86645694f5d.svg', 'KPP General PDF page 57'),
  ('1e5947cd-95ad-4d30-9eed-83d1c53dd163'::uuid, 'road-signs', 'mock-da-combined-1', 19, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Four-way intersection","Slippery road surface","Risk of falling rocks","Direction of a sharp bend"]'::jsonb, '["Persimpangan empat hala","Permukaan jalan licin","Risiko runtuhan batu","Arah selekoh yang tajam"]'::jsonb, 0, 'The cross symbol warns that another road crosses yours. Check both sides on approach.', 'Simbol silang memberi amaran bahawa jalan lain merentasi laluan anda. Periksa kedua-dua sisi apabila menghampiri.', '/signs/4a3491aff2749365.svg', 'KPP General PDF page 40'),
  ('0a58fed9-ce16-453a-9291-b3f95597d46b'::uuid, 'road-signs', 'mock-da-combined-1', 20, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Side road to the left","Side road to the right","Two-way traffic ahead","Gated rail crossing"]'::jsonb, '["Simpang jalan di sebelah kiri","Simpang jalan di sebelah kanan","Lalu lintas dua hala di hadapan","Lintasan kereta api berpagar"]'::jsonb, 0, 'The side branch on the left warns of a road joining from that side.', 'Cabang di sebelah kiri memberi amaran tentang jalan yang bercantum dari arah itu.', '/signs/e22292f492beec26.svg', 'KPP General PDF page 42'),
  ('cdab206e-5add-4541-885e-d5ca0a29ddd9'::uuid, 'road-signs', 'mock-da-combined-1', 21, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Side road to the right","Side road to the left","Two-way traffic ahead","Road narrows on the left"]'::jsonb, '["Simpang jalan di sebelah kanan","Simpang jalan di sebelah kiri","Lalu lintas dua hala di hadapan","Jalan menyempit di sebelah kiri"]'::jsonb, 0, 'The branch on the right warns of traffic that may enter from a side road there.', 'Cabang di sebelah kanan memberi amaran tentang trafik yang mungkin masuk dari jalan sisi itu.', '/signs/12e8b0d727c5bdf1.svg', 'KPP General PDF page 42'),
  ('a65a9fc5-3138-4d60-b7f1-b12919e2cc8e'::uuid, 'traffic-rules', 'mock-da-combined-1', 22, 'Someone offers to guarantee your test result for a private payment. What should you do?', 'Seseorang menawarkan keputusan ujian terjamin dengan bayaran peribadi. Apakah tindakan anda?', '["Decline and use the official process","Ask whether the offer is genuine","Accept if the fee is refundable","Ask your instructor to arrange it"]'::jsonb, '["Tolak dan ikut proses rasmi","Tanya sama ada tawaran itu sahih","Terima jika bayaran boleh dipulangkan","Minta pengajar menguruskannya"]'::jsonb, 0, 'Candidates must deal honestly with the driving institute and JPJ. Never offer a reward in exchange for a guaranteed pass.', 'Calon mesti berurusan secara jujur dengan institut memandu dan JPJ. Jangan tawarkan ganjaran sebagai pertukaran untuk jaminan lulus.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 100'),
  ('57bea822-d970-4c0a-906e-483d62199dfe'::uuid, 'traffic-rules', 'mock-da-combined-1', 23, 'Where is another car likely to be hidden in your blind spot?', 'Di manakah kereta lain mungkin terlindung dalam titik buta anda?', '["Alongside near a rear corner","Directly behind your rear window","Directly in front of your bonnet","Well ahead in the next lane"]'::jsonb, '["Di sisi berhampiran penjuru belakang","Tepat di belakang cermin belakang","Tepat di hadapan bonet","Jauh di hadapan di lorong sebelah"]'::jsonb, 0, 'A vehicle beside a rear quarter can be outside the view of the side and rear-view mirrors.', 'Kenderaan di sisi bahagian belakang mungkin berada di luar pandangan cermin sisi dan cermin pandang belakang.', NULL, 'KPP Kelas D Automatik, PDF page 98'),
  ('c160f16a-62ec-4849-8eec-72a126a4bad1'::uuid, 'traffic-rules', 'mock-da-combined-1', 24, 'You have passed a loaded lorry. What gap should you leave before moving in front of it?', 'Anda baru memotong lori bermuatan. Berapakah ruang yang patut ditinggalkan sebelum masuk ke hadapannya?', '["Only enough to clear its bumper","Just enough if you maintain speed","Only enough if the road is dry","Enough for the lorry to stop safely"]'::jsonb, '["Sekadar melepasi bampar lori","Sekadar cukup jika kelajuan dikekalkan","Sekadar cukup jika jalan kering","Cukup untuk lori berhenti"]'::jsonb, 3, 'A heavy vehicle needs a longer distance to stop. Avoid moving sharply into its path after passing.', 'Kenderaan berat memerlukan jarak berhenti lebih panjang. Elakkan masuk secara tiba-tiba ke laluannya selepas memotong.', NULL, 'KPP Kelas D Automatik, PDF page 88'),
  ('878381af-4f29-4cfa-b247-cbec3383eca7'::uuid, 'traffic-rules', 'mock-da-combined-1', 25, 'Why should you avoid an unnecessary horn blast beside a motorcyclist?', 'Mengapa anda patut mengelakkan bunyi hon yang tidak perlu di sisi penunggang motosikal?', '["It could startle the rider into swerving","It could make the rider slow gradually","It could make the rider check the mirror","It could make the rider hold a steady line"]'::jsonb, '["Penunggang mungkin terkejut dan melencong","Penunggang mungkin memperlahankan motosikal","Penunggang mungkin memeriksa cermin","Penunggang mungkin mengekalkan laluan"]'::jsonb, 0, 'A sudden horn can startle a rider and cause them to stray from their lane. Sound it only when needed.', 'Bunyi hon secara tiba-tiba boleh mengejutkan penunggang dan menyebabkan mereka terkeluar dari lorong. Bunyikan hon hanya apabila perlu.', NULL, 'KPP Kelas D Automatik, PDF page 85'),
  ('ccc2b908-3838-49d5-b615-87f558f442e4'::uuid, 'traffic-rules', 'mock-da-combined-1', 26, 'Which hand signal shows that a driver intends to turn right?', 'Isyarat tangan manakah menunjukkan bahawa pemandu hendak membelok ke kanan?', '["Hold the right arm vertically","Move the right arm in a circle","Extend the right arm horizontally","Wave the right arm up and down"]'::jsonb, '["Tegakkan lengan kanan","Gerakkan lengan kanan secara membulat","Luruskan lengan kanan secara mendatar","Gerakkan lengan kanan ke atas dan ke bawah"]'::jsonb, 2, 'A straight, horizontal right arm indicates a right turn.', 'Lengan kanan yang lurus dan mendatar menandakan belok kanan.', NULL, 'KPP Kelas D Automatik, PDF page 75'),
  ('efcac1dd-bdf2-4e11-85a9-51ab7ac1c71d'::uuid, 'traffic-rules', 'mock-da-combined-1', 27, 'The driver ahead holds their right hand upright and still outside the window, with the palm open. What are they signalling?', 'Pemandu di hadapan menegakkan tangan kanan dengan tapak tangan terbuka dan tidak menggerakkannya di luar tingkap. Apakah isyaratnya?', '["Stopping","Slowing down","Turning right","Allowing you to pass"]'::jsonb, '["Berhenti","Memperlahankan kenderaan","Membelok ke kanan","Membenarkan anda memotong"]'::jsonb, 0, 'A hand held upright outside the driver’s window indicates that the driver is stopping.', 'Tangan yang ditegakkan di luar tingkap pemandu menandakan pemandu akan berhenti.', NULL, 'KPP Kelas D Automatik, PDF page 75'),
  ('11a57b97-00cc-472a-bc61-936a07cee926'::uuid, 'traffic-rules', 'mock-da-combined-1', 28, 'The driver ahead is moving their right arm in a circle outside the window. What does that signal mean?', 'Pemandu di hadapan menggerakkan lengan kanan secara membulat di luar tingkap. Apakah maksud isyarat itu?', '["Turning left","Turning right","Stopping","Moving off from the shoulder"]'::jsonb, '["Belok kiri","Membelok ke kanan","Berhenti","Bergerak dari bahu jalan"]'::jsonb, 0, 'A circular movement of the right arm indicates a left turn.', 'Gerakan membulat lengan kanan menandakan belok kiri.', NULL, 'KPP Kelas D Automatik, PDF page 75'),
  ('3f06dd46-87e5-4151-970f-54a1f1cf7384'::uuid, 'traffic-rules', 'mock-da-combined-1', 29, 'A traffic officer faces you, extends their right arm straight out to their right and bends their left arm across their chest. Where can you go?', 'Polis trafik menghadap anda, meluruskan lengan kanannya ke sebelah kanannya dan membengkokkan lengan kiri di hadapan dada. Ke manakah anda boleh bergerak?', '["Straight through","Left at the junction","Right at the junction","Wait at the line"]'::jsonb, '["Terus melalui persimpangan","Belok kiri di persimpangan","Belok kanan di persimpangan","Tunggu di garisan"]'::jsonb, 2, 'For this signal, traffic approaching the officer from the front can turn right. Traffic behind the officer stops.', 'Dengan isyarat ini, trafik yang menghadap anggota polis boleh membelok ke kanan. Trafik di belakang anggota polis mesti berhenti.', NULL, 'KPP Kelas D Automatik, PDF page 74'),
  ('18c1e943-966c-4d0e-b082-2aa83afef58b'::uuid, 'traffic-rules', 'mock-da-combined-1', 30, 'A traffic officer holds both forearms upright and beckons with both hands. Which traffic may go?', 'Polis trafik menegakkan kedua-dua lengan bawah dan melambai dengan kedua-dua tangan. Trafik manakah boleh bergerak?', '["From the front and rear","From the left and right","From the front only","From the rear only"]'::jsonb, '["Dari hadapan dan belakang","Dari kiri dan kanan","Dari hadapan sahaja","Dari belakang sahaja"]'::jsonb, 1, 'This signal allows traffic on both sides of the officer to proceed.', 'Isyarat ini membenarkan trafik di kedua-dua sisi anggota polis meneruskan perjalanan.', NULL, 'KPP Kelas D Automatik, PDF page 74'),
  ('406f780a-93de-4f8f-81d1-5073c5dc17e3'::uuid, 'traffic-rules', 'mock-da-combined-1', 31, 'When should you finish adjusting your speed for an S-bend?', 'Bilakah anda perlu selesai melaraskan kelajuan untuk selekoh S?', '["Just after entering the bend","Between the two curves","Before entering the bend","Just before leaving the bend"]'::jsonb, '["Sejurus selepas masuk selekoh","Antara dua lengkungan","Sebelum masuk selekoh","Sejurus sebelum keluar selekoh"]'::jsonb, 2, 'Enter slowly and hold a steady speed through the curves. Avoid changing gear or braking in the bend.', 'Masuk perlahan-lahan dan kekalkan kelajuan sepanjang selekoh. Elakkan menukar gear atau membrek di dalam selekoh.', NULL, 'KPP Kelas D Automatik, PDF page 249'),
  ('92bda1e2-47b5-49ac-a6d2-09362de676fe'::uuid, 'traffic-rules', 'mock-da-combined-1', 32, 'Which steering technique does the handbook teach for a tight Z-bend?', 'Teknik stereng manakah yang diajar dalam buku panduan untuk selekoh Z yang sempit?', '["Let the wheel slide in the hands","Alternate pulling and pushing","Pull down with both hands","Turn with both hands fixed"]'::jsonb, '["Biarkan stereng meluncur di tangan","Tarik dan tolak secara bergilir-gilir","Tarik ke bawah dengan kedua-dua tangan","Pusing dengan kedua-dua tangan kekal"]'::jsonb, 0, 'Use the pull-and-push steering technique throughout the Z-bend.', 'Gunakan teknik stereng tarik dan tolak sepanjang selekoh Z.', NULL, 'KPP Kelas D Automatik, PDF page 250'),
  ('1f62159d-2b00-414a-b157-68f24dac2321'::uuid, 'traffic-rules', 'mock-da-combined-1', 33, 'What is the time limit for the three-point turn in the Class DA circuit test?', 'Berapakah had masa pusingan tiga penjuru dalam ujian litar Kelas DA?', '["2 minutes","4 minutes","5 minutes","3 minutes"]'::jsonb, '["2 minit","4 minit","5 minit","3 minit"]'::jsonb, 3, 'Complete the forward, reverse and final forward moves within three minutes.', 'Selesaikan gerakan ke hadapan, mengundur dan ke hadapan semula dalam masa tiga minit.', NULL, 'KPP Kelas D Automatik, PDF page 280'),
  ('9d454fe5-9288-441c-a6c7-d0befda1bceb'::uuid, 'traffic-rules', 'mock-da-combined-1', 34, 'What is the time limit for side parking in the Class DA circuit test?', 'Berapakah had masa parkir sisi dalam ujian litar Kelas DA?', '["4 minutes","5 minutes","3 minutes","6 minutes"]'::jsonb, '["4 minit","5 minit","3 minit","6 minit"]'::jsonb, 1, 'You have five minutes to complete the manoeuvre, including leaving the bay.', 'Anda mempunyai lima minit untuk melengkapkan olah gerak, termasuk keluar dari petak.', NULL, 'KPP Kelas D Automatik, PDF page 278'),
  ('fc25aa86-40d4-435c-be98-5357a230d146'::uuid, 'traffic-rules', 'mock-da-combined-1', 35, 'An injured person is conscious and asks for a drink. Which action follows the handbook guidance?', 'Mangsa yang sedar meminta minuman. Tindakan manakah mengikut panduan buku?', '["Keep the drink aside","Give a few small sips","Give a drink after they sit up","Offer plain water instead"]'::jsonb, '["Ketepikan minuman itu","Beri beberapa teguk kecil","Beri minuman selepas mangsa duduk","Tawarkan air kosong sebagai ganti"]'::jsonb, 0, 'Avoid giving a road-crash casualty anything to eat or drink at the scene.', 'Jangan beri mangsa kemalangan jalan raya makanan atau minuman di tempat kejadian.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 200'),
  ('d82ffb72-0e43-40ae-96a2-a3b850490939'::uuid, 'traffic-rules', 'mock-da-combined-1', 36, 'Which pair of details does the handbook specifically recommend photographing as crash evidence?', 'Pasangan butiran manakah yang disarankan oleh buku panduan untuk dirakam sebagai bukti kemalangan?', '["Car interiors and personal items","Nearby buildings and road signs","Vehicle damage and road marks","Service records and repair receipts"]'::jsonb, '["Ruang dalam kereta dan barang peribadi","Bangunan berhampiran dan tanda jalan","Kerosakan kenderaan dan kesan di jalan","Rekod servis dan resit pembaikan"]'::jsonb, 2, 'Photograph the scene, vehicle damage and any road marks that may help explain what happened.', 'Ambil gambar tempat kejadian, kerosakan kenderaan dan sebarang kesan di jalan yang boleh membantu menjelaskan kejadian.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 200'),
  ('1cdfd851-f396-46e3-b3ba-1cb5b9dcb1bd'::uuid, 'traffic-rules', 'mock-da-combined-1', 37, 'After a crash with serious property damage, whom should you contact to make a formal accident report?', 'Selepas kemalangan yang menyebabkan kerosakan harta benda yang serius, kepada siapakah laporan rasmi kemalangan patut dibuat?', '["Your insurer","The police","The highway operator","The local council"]'::jsonb, '["Syarikat insurans anda","Pihak polis","Pengendali lebuh raya","Pihak berkuasa tempatan"]'::jsonb, 1, 'Report the crash to the police, especially if someone was injured or the property damage was serious.', 'Laporkan kemalangan kepada polis, terutama jika terdapat kecederaan atau kerosakan harta benda yang serius.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 199'),
  ('15ddb3aa-3d93-4949-99d1-514ac50ea033'::uuid, 'traffic-rules', 'mock-da-combined-1', 38, 'A crash casualty is seriously injured. What help should you request from emergency services?', 'Seorang mangsa kemalangan cedera parah. Bantuan apakah yang perlu anda minta daripada perkhidmatan kecemasan?', '["An ambulance crew","A vehicle recovery crew","A traffic control crew","A road maintenance crew"]'::jsonb, '["Pasukan ambulans","Pasukan pemulihan kenderaan","Pasukan kawalan trafik","Pasukan penyelenggaraan jalan"]'::jsonb, 0, 'Call for urgent medical assistance if someone is seriously injured.', 'Hubungi perkhidmatan perubatan kecemasan jika ada orang yang cedera parah.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 199'),
  ('75f7741e-a100-49be-97ea-84e7a10376fe'::uuid, 'traffic-rules', 'mock-da-combined-1', 39, 'You pass parked cars in a housing estate. Which situation calls for more room and a lower speed?', 'Anda melalui kereta yang diletakkan di kawasan perumahan. Keadaan manakah memerlukan ruang tambahan dan kelajuan lebih rendah?', '["Children playing near the parked cars","A resident watering a garden behind a fence","A car parked fully inside a driveway","People waiting inside a building"]'::jsonb, '["Kanak-kanak bermain berhampiran kereta","Penduduk menyiram kebun di sebalik pagar","Kereta diletakkan sepenuhnya di laluan masuk","Orang menunggu di dalam bangunan"]'::jsonb, 0, 'Children can suddenly enter the road in residential areas. Drive at a speed that gives you time to react.', 'Kanak-kanak boleh tiba-tiba memasuki jalan di kawasan perumahan. Pandu pada kelajuan yang memberi anda masa untuk bertindak.', NULL, 'KPP Kelas D Automatik, PDF page 82'),
  ('4f48b904-26c4-4e11-8fdc-ee54b1b21892'::uuid, 'traffic-rules', 'mock-da-combined-1', 40, 'Rain reduces visibility near a pedestrian crossing. What extra risk should you expect?', 'Hujan mengurangkan jarak penglihatan berhampiran lintasan pejalan kaki. Apakah risiko tambahan yang perlu dijangkakan?', '["Pedestrians may wait longer to cross","Pedestrians may hurry across the road","Pedestrians may stand further from the road","Pedestrians may make more eye contact"]'::jsonb, '["Pejalan kaki mungkin menunggu lebih lama","Pejalan kaki mungkin tergesa-gesa melintas","Pejalan kaki mungkin berdiri lebih jauh dari jalan","Pejalan kaki mungkin lebih kerap memandang pemandu"]'::jsonb, 1, 'In bad weather, pedestrians may hurry and pay less attention while drivers also see less clearly.', 'Dalam cuaca buruk, pejalan kaki mungkin tergesa-gesa dan kurang memberi perhatian, manakala pandangan pemandu turut terjejas.', NULL, 'KPP Kelas D Automatik, PDF page 83'),
  ('547cc4bc-867a-4c7a-89fe-151be450e38d'::uuid, 'traffic-rules', 'mock-da-combined-1', 41, 'A car enters your lane unexpectedly. Which response follows the handbook’s advice on sharing the road?', 'Sebuah kereta memasuki lorong anda tanpa dijangka. Tindakan manakah mengikut nasihat buku panduan tentang berkongsi jalan?', '["Close the gap to hold your place","Signal and pass at the next gap","Let the car go and keep your composure","Keep pace until the car changes lanes"]'::jsonb, '["Rapatkan jarak untuk kekal di kedudukan","Beri isyarat dan potong apabila ada ruang","Biarkan kereta itu pergi dan kekal tenang","Ikut kelajuannya sehingga kereta menukar lorong"]'::jsonb, 2, 'The handbook advises patience with other road users, including when someone moves into your lane.', 'Buku panduan menasihatkan supaya bersabar dengan pengguna jalan raya yang lain, termasuk apabila seseorang masuk ke lorong anda.', NULL, 'KPP Kelas D Automatik, PDF page 78'),
  ('76ad87f2-e4d2-4e1f-b360-aa152b84418f'::uuid, 'traffic-rules', 'mock-da-combined-1', 42, 'Your phone shows a new message while you are driving. When should you read it?', 'Telefon anda menunjukkan mesej baharu semasa anda memandu. Bilakah anda patut membacanya?', '["While traffic is moving slowly","When you are safely parked","When the lane ahead is clear","While rolling up to a red light"]'::jsonb, '["Semasa trafik bergerak perlahan","Apabila anda sudah parkir dengan selamat","Apabila lorong di hadapan lapang","Semasa bergerak menghampiri lampu merah"]'::jsonb, 1, 'Reading a phone takes attention away from the road. Wait until the car is safely parked.', 'Membaca telefon mengalihkan tumpuan daripada jalan. Tunggu sehingga kereta diparkir dengan selamat.', NULL, 'KPP Kelas D Automatik, PDF page 78'),
  ('149ed86f-8100-4401-bfcd-5f065af138da'::uuid, 'traffic-rules', 'mock-da-combined-1', 43, 'You are struggling to stay awake before a planned drive. What should you do?', 'Anda sukar berjaga sebelum perjalanan yang dirancang. Apakah tindakan anda?', '["Drive with a window open","Take the trip in shorter stages","Delay the drive until rested","Choose a quieter route"]'::jsonb, '["Pandu dengan tingkap terbuka","Bahagikan perjalanan kepada beberapa peringkat","Tangguhkan pemanduan sehingga cukup rehat","Pilih laluan yang kurang sibuk"]'::jsonb, 2, 'The handbook advises against starting a journey if you are sleepy or tired.', 'Buku panduan menasihatkan supaya jangan memulakan perjalanan jika anda mengantuk atau letih.', NULL, 'KPP Kelas D Automatik, PDF page 119'),
  ('6aaf79b1-f37c-4985-9b4a-3cb8c7b84974'::uuid, 'traffic-rules', 'mock-da-combined-1', 44, 'Your brake lights fail during a pre-drive check. What is the best response?', 'Lampu brek anda tidak berfungsi semasa pemeriksaan sebelum memandu. Apakah tindakan terbaik?', '["Continue using your hazard lights","Drive more slowly than usual","Wait until daylight to drive","Have the lights repaired first"]'::jsonb, '["Teruskan dengan lampu amaran kecemasan","Pandu lebih perlahan daripada biasa","Tunggu sehingga siang untuk memandu","Baiki lampu sebelum memandu"]'::jsonb, 3, 'Brake lights need to work so following drivers can tell when you are braking.', 'Lampu brek mesti berfungsi supaya pemandu di belakang tahu apabila anda membrek.', NULL, 'KPP Kelas D Automatik, PDF page 120'),
  ('bae8bf90-ad84-42ea-9d79-e86e7c5a527b'::uuid, 'traffic-rules', 'mock-da-combined-1', 45, 'On a two-way road, another driver starts passing you. What should you do?', 'Di jalan dua hala, pemandu lain mula memotong anda. Apakah tindakan anda?', '["Keep left and avoid speeding up","Keep left and speed up briefly","Move right and hold your speed","Move right and slow down"]'::jsonb, '["Kekal di kiri tanpa memecut","Kekal di kiri dan tambah kelajuan seketika","Bergerak ke kanan dan kekalkan kelajuan","Bergerak ke kanan dan perlahankan kenderaan"]'::jsonb, 0, 'Cooperate with the driver passing you. Keep to the left and leave space for them to finish passing.', 'Beri kerjasama kepada pemandu yang memotong. Kekal di sebelah kiri dan tinggalkan ruang untuk mereka selesai memotong.', NULL, 'KPP Kelas D Automatik, PDF page 124'),
  ('18eb4605-fad3-4cc0-8e26-6c4c0a20c11d'::uuid, 'traffic-rules', 'mock-da-combined-1', 46, 'You have slowed for a left turn. When should you smoothly pick up speed again?', 'Anda telah memperlahankan kenderaan untuk membelok ke kiri. Bilakah anda patut menambah kelajuan dengan lancar?', '["Before reaching the junction","Immediately after signalling","After clearing the turn","As you start steering left"]'::jsonb, '["Sebelum tiba di persimpangan","Sejurus selepas memberi isyarat","Selepas selesai membelok","Sebaik mula memusing stereng ke kiri"]'::jsonb, 2, 'Set a suitable speed before the turn. Accelerate smoothly once you have cleared the hazard.', 'Tetapkan kelajuan yang sesuai sebelum membelok. Tambah kelajuan secara lancar selepas melepasi halangan.', NULL, 'KPP Kelas D Automatik, PDF page 111'),
  ('d177f00f-050f-4c6a-804b-fcb055368067'::uuid, 'traffic-rules', 'mock-da-combined-1', 47, 'You are in the wrong lane as the queues split at a toll plaza. What should you avoid?', 'Anda berada di lorong yang salah apabila barisan berpecah di plaza tol. Apakah yang perlu dielakkan?', '["Cutting across the queues","Slowing with the traffic","Watching the lane signs","Leaving a gap ahead"]'::jsonb, '["Memotong merentasi barisan","Memperlahankan kenderaan mengikut trafik","Memerhatikan papan tanda lorong","Meninggalkan ruang di hadapan"]'::jsonb, 0, 'Choose the correct toll lane early. Last-second lane changes across queues increase the crash risk.', 'Pilih lorong tol yang betul lebih awal. Pertukaran lorong pada saat akhir merentasi barisan meningkatkan risiko kemalangan.', NULL, 'KPP Kelas D Automatik, PDF page 135'),
  ('b36e3a5a-ffcb-483b-ae7a-2c62bd28d2a9'::uuid, 'traffic-rules', 'mock-da-combined-1', 48, 'A motorway lane looks empty in your mirrors. Should you still indicate before moving over?', 'Lorong lebuh raya kelihatan kosong dalam cermin anda. Adakah anda masih perlu memberi isyarat sebelum menukar lorong?', '["Yes, before moving across","Yes, once halfway across","Only if a car is visible","Only if it is the right lane"]'::jsonb, '["Ya, sebelum bergerak ke lorong sebelah","Ya, apabila separuh masuk ke lorong sebelah","Hanya jika kelihatan kereta","Hanya jika itu lorong kanan"]'::jsonb, 0, 'Signal before every lane change. An apparently empty lane may contain a vehicle outside your mirror view.', 'Beri isyarat sebelum setiap pertukaran lorong. Kenderaan di lorong yang kelihatan kosong mungkin berada di luar pandangan cermin.', NULL, 'KPP Kelas D Automatik, PDF page 141'),
  ('28ca7bbe-107c-4a5b-a425-c3f8b540fa92'::uuid, 'traffic-rules', 'mock-da-combined-1', 49, 'You have just passed a car on a three-lane motorway. Where should you drive once the road ahead is clear?', 'Anda baru memotong kereta di lebuh raya tiga lorong. Di manakah anda patut memandu apabila jalan di hadapan lapang?', '["Stay in the right lane","Return to the normal driving lane","Stay in the centre lane","Return to the emergency lane"]'::jsonb, '["Kekal di lorong kanan","Ke lorong pemanduan kiri","Kekal di lorong tengah","Kembali ke lorong kecemasan"]'::jsonb, 1, 'The centre and right lanes are for overtaking. Return to the normal driving lane when safe.', 'Lorong tengah dan kanan digunakan untuk memotong. Kembali ke lorong pemanduan biasa apabila selamat.', NULL, 'KPP Kelas D Automatik, PDF page 141'),
  ('d386ae6b-f4e1-47be-8e66-e36db96987a2'::uuid, 'traffic-rules', 'mock-da-combined-1', 50, 'A rear door will not open from inside but opens normally from outside. Which control explains this?', 'Pintu belakang tidak boleh dibuka dari dalam tetapi boleh dibuka seperti biasa dari luar. Alat kawalan manakah menerangkan keadaan ini?', '["The child safety lock","The central locking switch","The remote door lock","The driver’s door lock"]'::jsonb, '["Kunci keselamatan kanak-kanak","Suis kunci pusat","Kunci pintu kawalan jauh","Kunci pintu pemandu"]'::jsonb, 0, 'The rear-door child lock helps stop a child from opening the door from inside.', 'Kunci keselamatan kanak-kanak pada pintu belakang membantu menghalang kanak-kanak daripada membuka pintu dari dalam.', NULL, 'KPP Kelas DA Automatik, PDF 158'),
  ('5fbd4a89-09f7-4f99-baa6-076d5d7d82ce'::uuid, 'traffic-rules', 'mock-da-combined-1', 51, 'You are driving at night on a rural road with no street lights. How should you choose your speed?', 'Anda memandu pada waktu malam di jalan luar bandar tanpa lampu jalan. Bagaimanakah anda perlu memilih kelajuan?', '["Match the speed of the car ahead","Drive as fast as the limit allows","Match the speed you use by day","Leave enough time to stop for hazards"]'::jsonb, '["Ikut kelajuan kereta di hadapan","Pandu pada kelajuan maksimum yang dibenarkan","Ikut kelajuan yang digunakan pada siang hari","Pandu cukup perlahan untuk berhenti"]'::jsonb, 3, 'Drive slowly enough to respond to hazards such as pedestrians or animals that are hard to see at night.', 'Pandu cukup perlahan untuk bertindak terhadap bahaya seperti pejalan kaki atau haiwan yang sukar dilihat pada waktu malam.', NULL, 'KPP Kelas D Automatik, PDF page 137'),
  ('ce943b17-ad2c-4600-b71e-0ff7d2f060d0'::uuid, 'traffic-rules', 'mock-da-combined-1', 52, 'Which check helps you keep your view clear when rain starts?', 'Pemeriksaan manakah membantu memastikan pandangan anda jelas apabila hujan bermula?', '["Check the brake lights","Check the windscreen wipers","Check the hazard light switch","Check the rear-view mirror mount"]'::jsonb, '["Periksa lampu brek","Periksa pengelap cermin hadapan","Periksa suis lampu amaran kecemasan","Periksa pemegang cermin pandang belakang"]'::jsonb, 1, 'Make sure the wipers work before driving. They must clear rain from the windscreen.', 'Pastikan pengelap berfungsi sebelum memandu. Pengelap mesti dapat membersihkan air hujan dari cermin hadapan.', NULL, 'KPP Kelas D Automatik, PDF page 120'),
  ('5cb80552-67b7-4423-8e50-729918e464cd'::uuid, 'traffic-rules', 'mock-da-combined-1', 53, 'What should you switch on when driving through a tunnel?', 'Apakah yang perlu dihidupkan semasa memandu di dalam terowong?', '["Cabin lights","Hazard lights","Headlights","Rear fog lights"]'::jsonb, '["Lampu kabin","Lampu amaran kecemasan","Lampu hadapan","Lampu kabus belakang"]'::jsonb, 2, 'Use the vehicle’s headlights in a tunnel and allow a safe following gap because visibility is limited.', 'Gunakan lampu hadapan di dalam terowong dan kekalkan jarak mengekori yang selamat kerana penglihatan terhad.', NULL, 'KPP Kelas D Automatik, PDF page 139'),
  ('6db1e4ea-013f-4162-87c6-a404b0107538'::uuid, 'traffic-rules', 'mock-da-combined-1', 54, 'You are passing a busy market. How should you respond to pedestrians near the road?', 'Anda melalui pasar yang sibuk. Bagaimanakah anda perlu bertindak terhadap pejalan kaki berhampiran jalan?', '["Keep speed and watch the kerb","Slow down and be ready to yield","Sound the horn and continue","Move out and continue at speed"]'::jsonb, '["Kekalkan kelajuan dan perhatikan bebendul","Perlahankan dan beri laluan","Bunyikan hon dan teruskan perjalanan","Bergerak ke tepi dan kekalkan kelajuan"]'::jsonb, 1, 'Slow down and watch for pedestrians in crowded places. Give them priority when they cross and obey crossing signals.', 'Perlahankan kenderaan dan perhatikan pejalan kaki di tempat tumpuan ramai. Beri keutamaan ketika mereka melintas dan patuhi isyarat lintasan.', NULL, 'KPP Kelas D Automatik, PDF page 139'),
  ('effa4a7d-1807-4758-810c-53fad41ab3fb'::uuid, 'traffic-rules', 'mock-da-combined-1', 55, 'When you approach a stopped bus, what hazard does the handbook identify near the front and rear of the bus?', 'Apabila anda menghampiri bas yang berhenti, bahaya apakah yang dinyatakan oleh buku panduan berhampiran bahagian hadapan dan belakang bas?', '["Passengers stepping into the road","Passengers queuing at the shelter","Pedestrians waiting on the pavement","Pedestrians walking away from the stop"]'::jsonb, '["Penumpang melangkah ke jalan","Penumpang beratur di pondok","Pejalan kaki menunggu di kaki lima","Pejalan kaki beredar dari hentian"]'::jsonb, 0, 'Watch both ends of the bus for passengers who step into the road.', 'Perhatikan bahagian hadapan dan belakang bas jika ada penumpang yang melangkah ke jalan.', NULL, 'KPP Kelas D Automatik, PDF page 81'),
  ('41a8f68a-83a3-4643-9a8f-f3b06f616ec2'::uuid, 'traffic-rules', 'mock-da-combined-1', 56, 'Goats are starting to cross a village road. What should you do?', 'Kambing mula melintas jalan kampung. Apakah tindakan anda?', '["Keep speed and pass behind them","Sound the horn while passing","Move around them before they spread out","Slow down and let them cross"]'::jsonb, '["Kekalkan kelajuan dan lalu di belakangnya","Bunyikan hon ketika melintas di sisinya","Pintas sebelum haiwan itu berselerak","Perlahankan kenderaan dan beri laluan"]'::jsonb, 3, 'Slow down and give animals room to cross. Avoid sounding the horn because it can startle them.', 'Perlahankan kenderaan dan beri ruang kepada haiwan untuk melintas. Elakkan membunyikan hon kerana bunyinya boleh mengejutkan haiwan.', NULL, 'KPP Kelas D Automatik, PDF page 136'),
  ('7e4d79a5-6d07-453f-bdab-ddfed85e3cd2'::uuid, 'safety-principles', 'mock-da-combined-1', 57, 'Which licence does the curriculum require for ordinary GDL or PSV applications?', 'Lesen manakah diperlukan untuk permohonan GDL atau PSV biasa mengikut kurikulum ini?', '["A learner driving licence","A competent driving licence","A probationary driving licence","An international driving permit"]'::jsonb, '["Lesen belajar memandu","Lesen memandu kompeten","Lesen memandu percubaan","Permit memandu antarabangsa"]'::jsonb, 1, 'The vocational application requirements list a competent driving licence. The probationary licence exception is for Class C only.', 'Syarat permohonan lesen vokasional menyenaraikan lesen memandu kompeten. Pengecualian untuk lesen percubaan hanya bagi Kelas C.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('fab58373-bb80-4e85-87fc-c2d779155bf9'::uuid, 'safety-principles', 'mock-da-combined-1', 58, 'A PSV bus applicant has completed the course and wants to book the practical test. Which result is needed first?', 'Pemohon PSV bas telah mengikuti kursus dan ingin menempah ujian amali. Keputusan manakah diperlukan dahulu?', '["A pass in vocational theory","A pass in the motorcar theory test alone","A pass in the ordinary road test","A pass in a driving institute trial run"]'::jsonb, '["Lulus ujian teori vokasional","Lulus ujian teori motokar sahaja","Lulus ujian jalan raya biasa","Lulus percubaan di institut memandu"]'::jsonb, 0, 'Vocational practical tests take place after a theory pass. PSV bus applicants are one of the groups required to take a practical test.', 'Ujian amali lesen vokasional dijalankan selepas lulus ujian teori. Pemohon PSV bas ialah antara kumpulan yang perlu menjalani ujian amali.', NULL, 'KPP Kelas DA Automatik, PDF 24'),
  ('837795a9-d770-4f53-a670-0dc1a6917752'::uuid, 'safety-principles', 'mock-da-combined-1', 59, 'What does this curriculum say happens to a vocational licence that stays expired for over three years?', 'Apakah yang berlaku kepada lesen vokasional yang tamat tempoh melebihi tiga tahun mengikut kurikulum ini?', '["It is put on probation","It is suspended for a year","It is renewed for a year","It is cancelled"]'::jsonb, '["Lesen diletak dalam percubaan","Lesen digantung setahun","Lesen diperbaharui setahun","Lesen dibatalkan"]'::jsonb, 3, 'The curriculum lists automatic cancellation for a vocational licence that has been expired for more than three years.', 'Kurikulum menyenaraikan pembatalan automatik bagi lesen vokasional yang tamat tempoh melebihi tiga tahun.', NULL, 'KPP Kelas DA Automatik, PDF 25'),
  ('8c51a532-15c4-49af-a00a-6aedc5131e6f'::uuid, 'safety-principles', 'mock-da-combined-1', 60, 'Which part of the driving test assesses practical driving on public roads?', 'Bahagian ujian memandu manakah menilai pemanduan amali di jalan raya?', '["Part III","Part II","Part I","The theory course"]'::jsonb, '["Bahagian III","Bahagian II","Bahagian I","Kursus teori"]'::jsonb, 0, 'Part II tests circuit skills. Part III tests applying safe driving skills on the road.', 'Bahagian II menguji kemahiran di litar. Bahagian III menguji amalan pemanduan selamat di jalan raya.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('c44028df-aafc-4c41-9534-0286b89c1770'::uuid, 'safety-principles', 'mock-da-combined-1', 61, 'How long must a candidate wait after failing the circuit and road practical tests before retesting, according to this curriculum?', 'Berapa lamakah calon perlu menunggu selepas gagal ujian amali litar dan jalan raya sebelum mengulang ujian mengikut kurikulum ini?', '["One day","One week","Two weeks","One month"]'::jsonb, '["Satu hari","Satu minggu","Dua minggu","Satu bulan"]'::jsonb, 1, 'The book lists a one-week wait after failing the practical driving test before a candidate can retest.', 'Buku menetapkan tempoh menunggu seminggu selepas gagal ujian amali sebelum calon boleh mengulang ujian.', NULL, 'KPP Kelas DA Automatik, PDF 17'),
  ('18af8fb7-8574-4531-a34c-3fa22590601a'::uuid, 'safety-principles', 'mock-da-combined-1', 62, 'Which form records the training the institute confirms for a practical test booking?', 'Borang manakah merekodkan latihan yang disahkan oleh institut untuk tempahan ujian amali?', '["SM4","A copy of the LDL","The theory test result sheet","The practical test booking slip"]'::jsonb, '["SM4","Salinan LDL","Slip keputusan ujian teori","Slip tempahan ujian amali"]'::jsonb, 0, 'The booking requirements include a copy of the learner licence and the SM4 driving training record.', 'Syarat tempahan termasuk salinan lesen belajar memandu dan rekod latihan memandu SM4.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('a89c5926-a414-4a6c-be2e-0ae86173daf6'::uuid, 'safety-principles', 'mock-da-combined-1', 63, 'Where does a licence applicant with a disability obtain the medical verification specified in the handbook?', 'Di manakah pemohon lesen yang mempunyai ketidakupayaan mendapatkan pengesahan kesihatan yang dinyatakan dalam buku panduan?', '["A government clinic","The driving institute","A JPJ testing centre","An optical shop"]'::jsonb, '["Klinik kerajaan","Institut memandu","Pusat ujian JPJ","Kedai optik"]'::jsonb, 0, 'The curriculum requires medical verification by a medical officer at a government health clinic.', 'Kurikulum memerlukan pengesahan oleh pegawai perubatan di klinik kesihatan kerajaan.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('87e39515-3c4b-4fda-b695-8ba74d18ae25'::uuid, 'safety-principles', 'mock-da-combined-1', 64, 'When are demerit points counted for a scheduled offence?', 'Bilakah mata demerit dikira bagi kesalahan terjadual?', '["When the summons is issued","After payment of the penalty","When the licence is renewed","When a hearing is scheduled"]'::jsonb, '["Apabila saman dikeluarkan","Selepas penalti dibayar","Apabila lesen diperbaharui","Apabila perbicaraan dijadualkan"]'::jsonb, 1, 'The curriculum ties demerit points to a scheduled offence after the compound payment or court fine has been paid.', 'Kurikulum mengaitkan mata demerit bagi kesalahan terjadual dengan pembayaran kompaun atau denda mahkamah.', NULL, 'KPP General, PDF 93'),
  ('3b46c74e-072e-435e-a3f1-5343ffb65900'::uuid, 'safety-principles', 'mock-da-combined-1', 65, 'What is one use of selector position 3 on the automatic car in this curriculum?', 'Apakah satu kegunaan kedudukan gear 3 dalam kereta automatik yang diterangkan?', '["Starting in Neutral","Controlling speed downhill","Reversing into a space","Securing the parked car"]'::jsonb, '["Menghidupkan enjin dalam N","Mengawal kelajuan menuruni bukit","Mengundur ke petak parkir","Menahan kereta yang diparkir"]'::jsonb, 1, 'Selector position 3 allows the first three gears. It can be used on descents or when more power is needed for overtaking or climbing.', 'Kedudukan 3 membenarkan tiga gear pertama. Ia boleh digunakan ketika menuruni bukit atau apabila memerlukan lebih kuasa untuk memotong atau mendaki.', NULL, 'KPP Kelas DA Automatik, PDF 212'),
  ('45dbd6ab-5c3f-45bd-9798-d723b1c427be'::uuid, 'safety-principles', 'mock-da-combined-1', 66, 'What distinguishes the vehicle covered by Class DA in the classification table?', 'Apakah yang membezakan kenderaan Kelas DA dalam jadual pengelasan?', '["It has a manual clutch pedal","It has a hand-operated clutch","It has no clutch pedal","It has a separate low-range lever"]'::jsonb, '["Ada pedal cekam manual","Ada cekam kendalian tangan","Tiada pedal cekam","Ada tuil julat rendah berasingan"]'::jsonb, 2, 'The table lists Class DA for cars without a clutch pedal and with an unladen weight of no more than 3,500 kg.', 'Jadual menyenaraikan Kelas DA bagi motokar tanpa pedal cekam dengan berat tanpa muatan tidak melebihi 3,500 kg.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('03345fdc-f7da-4cb4-8d1f-85e5a94089c5'::uuid, 'safety-principles', 'mock-da-combined-1', 67, 'What is one purpose of the KEJARA system?', 'Apakah satu tujuan sistem KEJARA?', '["Track vehicle ownership","Set road speed limits","Reduce repeat offences","Manage driving-test bookings"]'::jsonb, '["Merekod pemilikan kenderaan","Menetapkan had laju jalan","Mengurangkan kesalahan berulang","Mengurus tempahan ujian memandu"]'::jsonb, 2, 'One purpose is to discourage repeat offences by educating and disciplining drivers.', 'Antara tujuannya ialah mengurangkan kesalahan berulang dengan mendidik dan mendisiplinkan pemandu.', NULL, 'KPP General, PDF 94'),
  ('af53609f-f4f5-4fcc-a9f9-52064992bae2'::uuid, 'safety-principles', 'mock-da-combined-1', 68, 'A driver with a competent licence reaches 20 KEJARA points for the first time. What does the schedule show?', 'Pemegang lesen kompeten mencapai 20 mata KEJARA buat kali pertama. Apakah tindakan dalam jadual?', '["A suspension","A cancellation","A course referral","A warning"]'::jsonb, '["Penggantungan","Pembatalan","Rujukan kursus","Amaran"]'::jsonb, 3, 'The first 20-point threshold shown in the schedule results in a warning.', 'Ambang 20 mata kali pertama dalam jadual ini membawa kepada amaran.', NULL, 'KPP General, PDF 95'),
  ('7a948819-ce54-4265-9399-4f5823037dfb'::uuid, 'safety-principles', 'mock-da-combined-1', 69, 'What kind of offence can lead to KEJARA points?', 'Apakah jenis kesalahan yang boleh menyebabkan mata KEJARA dikenakan?', '["A scheduled traffic offence","An internal parking charge","An insurance contract breach","A missed service appointment"]'::jsonb, '["Kesalahan trafik terjadual","Caj parkir dalaman","Pelanggaran kontrak insurans","Janji temu servis terlepas"]'::jsonb, 0, 'KEJARA applies to scheduled offences under the road transport rules.', 'KEJARA terpakai kepada kesalahan terjadual di bawah peraturan pengangkutan jalan.', NULL, 'KPP General, PDF 93'),
  ('e7a8210a-eef6-4aa8-8d37-4122ee574e73'::uuid, 'safety-principles', 'mock-da-combined-1', 70, 'If a KEJARA points deduction is granted under the handbook’s conditions, what is the upper limit?', 'Jika pengurangan mata KEJARA diberikan mengikut syarat buku panduan, berapakah hadnya?', '["25%","50%","60%","75%"]'::jsonb, '["25%","50%","60%","75%"]'::jsonb, 1, 'The curriculum describes a possible reduction of up to 50% of the demerit points under the listed conditions.', 'Kurikulum menerangkan potongan sehingga 50% daripada mata demerit tertakluk pada syarat yang disenaraikan.', NULL, 'KPP General, PDF 95'),
  ('1627835e-b4a0-44de-ae3b-37bd53c5a4d2'::uuid, 'road-signs', 'mock-da-combined-2', 1, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["T-junction ahead","Divided road ends","Stop sign ahead","Sharp right bend"]'::jsonb, '["Persimpangan T di hadapan","Jalan terbahagi dua tamat","Tanda berhenti di hadapan","Selekoh tajam ke kanan"]'::jsonb, 0, 'The T shows that your road meets a crossroad and does not continue straight.', 'Bentuk T menunjukkan bahawa jalan anda bertemu jalan melintang dan tidak bersambung lurus.', '/signs/e3ccd470b3c6bc8e.svg', 'KPP General PDF page 42'),
  ('5599f031-e6f9-4a10-84cf-14cdac05613a'::uuid, 'road-signs', 'mock-da-combined-2', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass either side of the island","Pass the island on the left","Pass the island on the right","Merge into a single lane"]'::jsonb, '["Lalui pulau dari mana-mana sisi","Lalui pulau di sebelah kiri","Lalui pulau di sebelah kanan","Bercantum ke satu lorong"]'::jsonb, 0, 'The arrows split around the island. Choose the side that leads to your destination.', 'Anak panah berpecah di sekeliling pulau. Pilih sisi yang menuju ke destinasi anda.', '/signs/322e269754adeff6.svg', 'KPP General PDF page 44'),
  ('1a0c6302-18c5-4ed7-b0ed-c42f784d810a'::uuid, 'road-signs', 'mock-da-combined-2', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Sharp left bend","Sharp right bend","Roundabout ahead","Stop sign ahead"]'::jsonb, '["Selekoh tajam ke kiri","Selekoh tajam ke kanan","Bulatan di hadapan","Tanda berhenti di hadapan"]'::jsonb, 0, 'The arrow turns sharply left. Reduce speed before the road bends.', 'Anak panah membelok tajam ke kiri. Kurangkan kelajuan sebelum selekoh.', '/signs/194637442da016e5.svg', 'KPP General PDF page 47'),
  ('357209e8-ab8a-4db8-9370-a3c535627af9'::uuid, 'road-signs', 'mock-da-combined-2', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Sharp right bend","Sharp left bend","Other hazard ahead","T-junction ahead"]'::jsonb, '["Selekoh tajam ke kanan","Selekoh tajam ke kiri","Bahaya lain di hadapan","Persimpangan T di hadapan"]'::jsonb, 0, 'The arrow turns sharply right. Reduce speed before reaching that bend.', 'Anak panah membelok tajam ke kanan. Kurangkan kelajuan sebelum tiba di selekoh itu.', '/signs/8c4124b32afd3704.svg', 'KPP General PDF page 47'),
  ('51ffd0fe-3553-442b-8601-7cdb181e120b'::uuid, 'road-signs', 'mock-da-combined-2', 5, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Direction of a sharp bend","Four-way intersection","Steep downhill stretch","Slippery road surface"]'::jsonb, '["Arah selekoh yang tajam","Persimpangan empat hala","Jalan menurun dengan curam","Permukaan jalan licin"]'::jsonb, 0, 'The chevron points in the direction of the sharp turn. Follow its direction through the bend.', 'Chevron menunjukkan arah belokan tajam. Ikuti arah itu semasa melalui selekoh.', '/signs/b716cb9e685088a5.svg', 'KPP General PDF page 47'),
  ('2684beb8-f1bf-4155-8f03-bc358976f916'::uuid, 'road-signs', 'mock-da-combined-2', 6, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Divided road ends","T-junction ahead","Stop sign ahead","Narrow bridge ahead"]'::jsonb, '["Jalan terbahagi dua tamat","Persimpangan T di hadapan","Tanda berhenti di hadapan","Jambatan sempit di hadapan"]'::jsonb, 0, 'The two sides come together where the divider ends. Watch for vehicles coming toward you.', 'Kedua-dua sisi bertemu apabila pembahagi tamat. Awasi kenderaan dari arah bertentangan.', '/signs/b12139221efc15b6.svg', 'KPP General PDF page 48'),
  ('06393a9f-6e7e-4f8d-8fcb-ef3142153e3a'::uuid, 'road-signs', 'mock-da-combined-2', 7, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Divided road begins","Divided road ends","Two-way traffic ahead","Road narrows on both sides"]'::jsonb, '["Jalan terbahagi dua bermula","Jalan terbahagi dua tamat","Lalu lintas dua hala di hadapan","Jalan menyempit di kedua-dua sisi"]'::jsonb, 0, 'The symbol shows a divider starting between the opposite directions of travel.', 'Simbol menunjukkan pembahagi bermula di antara dua arah perjalanan.', '/signs/788d475c2d05336c.svg', 'KPP General PDF page 48'),
  ('9f1da112-0fee-4968-b04b-9c94930f3936'::uuid, 'road-signs', 'mock-da-combined-2', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Roundabout ahead","Sharp left bend","Sharp right bend","Other hazard ahead"]'::jsonb, '["Bulatan di hadapan","Selekoh tajam ke kiri","Selekoh tajam ke kanan","Bahaya lain di hadapan"]'::jsonb, 0, 'The circular arrows indicate a roundabout. Choose your lane before entering and give way to circulating traffic.', 'Anak panah bulat menunjukkan bulatan. Pilih lorong sebelum masuk dan beri laluan kepada trafik yang beredar.', '/signs/d26a8ccc75c5a905.svg', 'KPP General PDF page 48'),
  ('104afba6-d69a-47d4-b3c7-c739b122bcb8'::uuid, 'road-signs', 'mock-da-combined-2', 9, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Two-way traffic ahead","Side road to the left","Side road to the right","Road narrows on the left"]'::jsonb, '["Lalu lintas dua hala di hadapan","Simpang jalan di sebelah kiri","Simpang jalan di sebelah kanan","Jalan menyempit di sebelah kiri"]'::jsonb, 0, 'The opposite arrows warn that traffic runs in both directions on the road ahead.', 'Anak panah bertentangan memberi amaran bahawa trafik bergerak dalam kedua-dua arah di jalan hadapan.', '/signs/ea082fc0b4c65733.svg', 'KPP General PDF page 49'),
  ('72a9627b-1c5e-425c-9271-0d606da1a210'::uuid, 'road-signs', 'mock-da-combined-2', 10, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on both sides","Road narrows on the left","Road narrows on the right","A divided road begins"]'::jsonb, '["Jalan menyempit di kedua-dua sisi","Jalan menyempit di sebelah kiri","Jalan menyempit di sebelah kanan","Jalan terbahagi dua bermula"]'::jsonb, 0, 'Both edges of the symbol move inward, so the available width decreases on both sides.', 'Kedua-dua tepi simbol menuju ke dalam, jadi lebar jalan berkurang pada kedua-dua sisi.', '/signs/ce68f8896451a2c9.svg', 'KPP General PDF page 50'),
  ('12552d17-2385-4091-806d-a32b103af072'::uuid, 'road-signs', 'mock-da-combined-2', 11, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on the left","Road narrows on the right","Side road to the right","Two-way traffic ahead"]'::jsonb, '["Jalan menyempit di sebelah kiri","Jalan menyempit di sebelah kanan","Simpang jalan di sebelah kanan","Lalu lintas dua hala di hadapan"]'::jsonb, 0, 'The left edge moves inward while the right edge stays straight. The narrowing is on the left.', 'Tepi kiri menuju ke dalam manakala tepi kanan kekal lurus. Penyempitan berlaku di kiri.', '/signs/2be93e13645351ef.svg', 'KPP General PDF page 50'),
  ('3feaa3bb-991a-4965-9cc1-054576b5ef0b'::uuid, 'road-signs', 'mock-da-combined-2', 12, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on the right","Road narrows on both sides","Road narrows on the left","Side road to the right"]'::jsonb, '["Jalan menyempit di sebelah kanan","Jalan menyempit di kedua-dua sisi","Jalan menyempit di sebelah kiri","Simpang jalan di sebelah kanan"]'::jsonb, 0, 'The right edge moves inward while the left edge stays straight. The narrowing is on the right.', 'Tepi kanan menuju ke dalam manakala tepi kiri kekal lurus. Penyempitan berlaku di kanan.', '/signs/e08ca85fb4d9816f.svg', 'KPP General PDF page 50'),
  ('9d8bde9a-586d-4ece-a87a-7a4447d7419a'::uuid, 'road-signs', 'mock-da-combined-2', 13, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Steep uphill stretch","Narrow bridge ahead","Divided road begins","Steep downhill stretch"]'::jsonb, '["Jalan mendaki dengan curam","Jambatan sempit di hadapan","Jalan terbahagi dua bermula","Jalan menurun dengan curam"]'::jsonb, 0, 'The incline rises in your direction of travel. A lower gear can help on the climb.', 'Cerun naik mengikut arah perjalanan anda. Gear rendah boleh membantu ketika mendaki.', '/signs/fa01479a3e275ae3.svg', 'KPP General PDF page 50'),
  ('f5eec660-73ca-492c-864f-6c977c53a67d'::uuid, 'road-signs', 'mock-da-combined-2', 14, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Steep downhill stretch","Steep uphill stretch","Narrow bridge ahead","Four-way intersection"]'::jsonb, '["Jalan menurun dengan curam","Jalan mendaki dengan curam","Jambatan sempit di hadapan","Persimpangan empat hala"]'::jsonb, 0, 'The incline falls in your direction of travel. A lower gear can help control speed downhill.', 'Cerun menurun mengikut arah perjalanan anda. Gear rendah boleh membantu mengawal kelajuan ketika menurun.', '/signs/eb9c555ec03577f6.svg', 'KPP General PDF page 50'),
  ('587580b7-f309-4210-a60e-d8facf1b86c7'::uuid, 'road-signs', 'mock-da-combined-2', 15, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Narrow bridge ahead","A steep descent ahead","Road narrows on the left","Road narrows on the right"]'::jsonb, '["Jambatan sempit di hadapan","Jalan menurun curam di hadapan","Jalan menyempit di sebelah kiri","Jalan menyempit di sebelah kanan"]'::jsonb, 0, 'The bridge symbol warns of limited width. Slow down and check for oncoming traffic before crossing.', 'Simbol jambatan memberi amaran tentang lebar yang terhad. Perlahankan kenderaan dan periksa trafik bertentangan sebelum melintas.', '/signs/d1e9a6d6aab128b3.svg', 'KPP General PDF page 51'),
  ('a9c584fd-7ae6-4434-a20d-291892513875'::uuid, 'road-signs', 'mock-da-combined-2', 16, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Slippery road surface","Uneven road ahead","Winding road ahead","Soft road shoulder"]'::jsonb, '["Permukaan jalan licin","Jalan tidak rata di hadapan","Jalan berliku di hadapan","Bahu jalan lembut"]'::jsonb, 0, 'The sign warns of a slippery stretch. Brake carefully and keep control of the steering.', 'Tanda ini memberi amaran tentang jalan licin. Brek dengan berhati-hati dan kekalkan kawalan stereng.', '/signs/9702f462c37241a4.svg', 'KPP General PDF page 51'),
  ('f68b2b69-438f-4351-8b65-ec40fe59816a'::uuid, 'road-signs', 'mock-da-combined-2', 17, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Stop sign ahead","T-junction ahead","Divided road ends","Sharp left bend"]'::jsonb, '["Tanda berhenti di hadapan","Persimpangan T di hadapan","Jalan terbahagi dua tamat","Selekoh tajam ke kiri"]'::jsonb, 0, 'The warning is in advance of a stop sign. Slow down so you can stop at the sign itself.', 'Amaran ini diletakkan sebelum tanda berhenti. Perlahankan kenderaan supaya anda boleh berhenti pada tanda sebenar.', '/signs/add368369889404d.svg', 'KPP General PDF page 52'),
  ('c29f4849-173d-4aa3-9ae2-388167146e3b'::uuid, 'road-signs', 'mock-da-combined-2', 18, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Other hazard ahead","Sharp right bend","Four-way intersection","Sharp left bend"]'::jsonb, '["Bahaya lain di hadapan","Selekoh tajam ke kanan","Persimpangan empat hala","Selekoh tajam ke kiri"]'::jsonb, 0, 'The exclamation mark warns of an unspecified danger ahead. Proceed with care.', 'Tanda seru memberi amaran tentang bahaya yang tidak dinyatakan jenisnya. Pandu dengan berhati-hati.', '/signs/3f13bbd2ffe5c466.svg', 'KPP General PDF page 52'),
  ('a9296c48-a86b-49d2-a76f-eadda37a22e1'::uuid, 'road-signs', 'mock-da-combined-2', 19, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Risk of falling rocks","Steep slope ahead","Soft road shoulder","Loose surface ahead"]'::jsonb, '["Risiko runtuhan batu","Cerun curam di hadapan","Bahu jalan lembut","Permukaan longgar di hadapan"]'::jsonb, 0, 'The rocks shown falling from a slope warn that debris may reach the roadway.', 'Batu yang ditunjukkan jatuh dari cerun memberi amaran bahawa runtuhan mungkin sampai ke jalan.', '/signs/adc5145404e740b4.svg', 'KPP General PDF page 53'),
  ('dbc64cdb-8c88-4ec6-b31c-bcf7a4b83596'::uuid, 'road-signs', 'mock-da-combined-2', 20, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Blind pedestrians may cross","Direction of a sharp bend","Steep downhill stretch","Pass either side of the island"]'::jsonb, '["Orang buta mungkin melintas","Arah selekoh yang tajam","Jalan menurun dengan curam","Lalui pulau dari mana-mana sisi"]'::jsonb, 0, 'The sign alerts you to people with impaired vision who may be crossing. Slow and give them time.', 'Tanda ini memberi amaran bahawa orang kurang upaya penglihatan mungkin melintas. Perlahankan kenderaan dan beri mereka masa.', '/signs/f986766e1fca4c02.svg', 'KPP General PDF page 54'),
  ('df320d18-8bcb-447b-858b-cf2571bb04fb'::uuid, 'road-signs', 'mock-da-combined-2', 21, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Gated rail crossing","Divided road begins","Narrow bridge ahead","Side road to the left"]'::jsonb, '["Lintasan kereta api berpagar","Jalan terbahagi dua bermula","Jambatan sempit di hadapan","Simpang jalan di sebelah kiri"]'::jsonb, 0, 'The symbol indicates a railway crossing with gates. Wait for the gates to open before proceeding.', 'Simbol menunjukkan lintasan kereta api berpagar. Tunggu pagar dibuka sebelum meneruskan perjalanan.', '/signs/e846f69e41c180a7.svg', 'KPP General PDF page 56'),
  ('4bb12d78-1049-4d83-a0a5-1a793790e35f'::uuid, 'traffic-rules', 'mock-da-combined-2', 22, 'An oncoming vehicle approaches a bend on a narrow rural road. What should you be ready for?', 'Kenderaan dari arah bertentangan menghampiri selekoh di jalan luar bandar yang sempit. Apakah yang perlu dijangkakan?', '["It may stop at the lane line","It may cut into your lane","It may signal before the bend","It may slow on its own side"]'::jsonb, '["Ia mungkin berhenti di garisan lorong","Ia mungkin masuk ke lorong anda","Ia mungkin memberi isyarat sebelum selekoh","Ia mungkin memperlahankan kenderaan di laluannya"]'::jsonb, 1, 'On a narrow bend, an approaching vehicle may cross into your lane. Reduce speed and leave room to respond.', 'Di selekoh sempit, kenderaan dari arah bertentangan mungkin masuk ke lorong anda. Perlahankan kenderaan dan tinggalkan ruang untuk bertindak.', NULL, 'KPP Kelas D Automatik, PDF page 135'),
  ('f9f8f434-138f-4450-90cb-1f79184c9eb3'::uuid, 'traffic-rules', 'mock-da-combined-2', 23, 'You are about to follow a heavy lorry uphill. What should you do with the space in front of you?', 'Anda akan mengekori lori berat ketika mendaki bukit. Apakah yang patut anda lakukan dengan ruang di hadapan?', '["Close the gap as the lorry slows","Hold back as the lorry climbs","Move beside the lorry before the hill","Follow its rear closely at the crest"]'::jsonb, '["Rapatkan jarak apabila lori perlahan","Jarakkan kenderaan semasa lori mendaki","Bergerak ke sisi lori sebelum bukit","Ekor rapat di belakang lori di puncak"]'::jsonb, 1, 'Allow a safe gap behind heavy vehicles when they start, climb or turn. Give yourself room to react to changes in their speed.', 'Kekalkan jarak yang selamat di belakang kenderaan berat apabila ia mula bergerak, mendaki atau membelok. Sediakan ruang untuk bertindak jika kelajuannya berubah.', NULL, 'KPP Kelas D Automatik, PDF page 88'),
  ('09d0c51c-316a-4753-b33b-9f05b6c71cfd'::uuid, 'traffic-rules', 'mock-da-combined-2', 24, 'You catch up to a car on an unlit road. Which lights should you use while following it?', 'Anda menghampiri sebuah kereta di jalan yang tidak berlampu. Lampu manakah yang patut digunakan semasa mengekorinya?', '["High beams","Low beams","Side lights","Front fog lights"]'::jsonb, '["Lampu tinggi","Lampu rendah","Lampu sisi","Lampu kabus hadapan"]'::jsonb, 1, 'Dip your headlights when following another vehicle. High beams can dazzle its driver through the mirrors.', 'Gunakan lampu rendah apabila mengekori kenderaan lain. Lampu tinggi boleh menyilaukan pemandunya melalui cermin.', NULL, 'KPP Kelas D Automatik, PDF page 142'),
  ('9f6986c1-cfbc-4032-a2d1-8774f9f5b7be'::uuid, 'traffic-rules', 'mock-da-combined-2', 25, 'Oncoming headlights are dazzling you. Where should you direct your gaze briefly to avoid looking into them?', 'Lampu hadapan dari arah bertentangan menyilaukan anda. Ke manakah anda patut mengalihkan pandangan seketika supaya tidak melihat terus ke arahnya?', '["Towards the centre line","Towards the right lane","Towards the left edge","Towards the rear-view mirror"]'::jsonb, '["Ke arah garisan tengah","Ke arah lorong kanan","Ke arah tepi kiri jalan","Ke arah cermin pandang belakang"]'::jsonb, 2, 'Use the left edge of the road as a reference while maintaining control. Avoid looking straight at the bright headlights.', 'Gunakan tepi kiri jalan sebagai panduan sambil mengekalkan kawalan. Elakkan melihat terus ke arah lampu yang terang.', NULL, 'KPP Kelas D Automatik, PDF page 143'),
  ('5e00e6d0-c9e2-4b6c-a035-6338479997b8'::uuid, 'traffic-rules', 'mock-da-combined-2', 26, 'Bright sunlight is scattering across the glass in front of you. What preparation helps reduce it?', 'Cahaya matahari terang berselerak pada kaca di hadapan anda. Persediaan apakah membantu mengurangkannya?', '["Remove dirt from the glass","Raise the rear-view mirror","Move the visor up","Close both side windows"]'::jsonb, '["Bersihkan kotoran pada kaca","Naikkan cermin pandang belakang","Naikkan pengadang matahari","Tutup kedua-dua tingkap sisi"]'::jsonb, 0, 'Remove dirt from the windscreen and keep enough washer fluid to clean it as needed.', 'Bersihkan kotoran pada cermin hadapan dan pastikan cecair pencuci mencukupi apabila diperlukan.', NULL, 'KPP Kelas D Automatik, PDF page 145'),
  ('9125c161-cf62-4afb-ae0f-4d30c9779e9c'::uuid, 'traffic-rules', 'mock-da-combined-2', 27, 'Why does a wet road leave you needing more room to stop?', 'Mengapakah anda memerlukan lebih ruang untuk berhenti di jalan basah?', '["The tyres have less grip","The engine takes longer to respond","The steering becomes heavier","The road markings become less visible"]'::jsonb, '["Cengkaman tayar berkurang","Enjin mengambil masa lebih lama untuk bertindak","Stereng menjadi lebih berat","Garisan jalan menjadi kurang jelas"]'::jsonb, 0, 'Wet roads reduce tyre grip, lengthening the distance needed to stop. Increase your following gap.', 'Jalan basah mengurangkan cengkaman tayar dan memanjangkan jarak untuk berhenti. Tambah jarak mengekori.', NULL, 'KPP Kelas D Automatik, PDF page 146'),
  ('90263d1c-4eae-4532-adfe-7e3e37889d98'::uuid, 'traffic-rules', 'mock-da-combined-2', 28, 'You are behind a slow car in thick fog on a two-way road. What is the safest plan?', 'Anda berada di belakang kereta perlahan dalam kabus tebal di jalan dua hala. Apakah rancangan paling selamat?', '["Follow closer to see its lights","Pass as soon as its lane is clear","Wait behind at a safe distance","Move partly out to look ahead"]'::jsonb, '["Ekor lebih rapat untuk melihat lampunya","Potong sebaik sahaja laluannya lapang","Kekal di belakang pada jarak selamat","Keluar sedikit dari lorong untuk melihat ke hadapan"]'::jsonb, 2, 'Limited visibility makes overtaking risky in fog. Stay in your lane, leave a safe gap and match your speed to what you can see.', 'Penglihatan terhad menjadikan tindakan memotong berbahaya dalam kabus. Kekal di lorong, tinggalkan jarak yang selamat dan sesuaikan kelajuan dengan jarak penglihatan.', NULL, 'KPP Kelas D Automatik, PDF page 149'),
  ('63354c2a-6e3e-447b-a503-101ae14257d9'::uuid, 'traffic-rules', 'mock-da-combined-2', 29, 'Rain reduces visibility on the motorway, but your car is moving normally. Which lights should you use?', 'Hujan mengurangkan penglihatan di lebuh raya, tetapi kereta anda bergerak seperti biasa. Lampu manakah yang patut digunakan?', '["Hazard lights alone","Headlights alone","Headlights and hazard lights","Hazard lights and side lights"]'::jsonb, '["Lampu amaran kecemasan sahaja","Lampu hadapan sahaja","Lampu hadapan dan lampu amaran kecemasan","Lampu amaran kecemasan dan lampu sisi"]'::jsonb, 1, 'Use headlights so others can see your moving car. Reserve hazard lights for an emergency.', 'Gunakan lampu hadapan supaya orang lain dapat melihat kereta anda yang sedang bergerak. Gunakan lampu amaran kecemasan untuk keadaan kecemasan.', NULL, 'KPP Kelas D Automatik, PDF page 141'),
  ('a3c666f0-a8cf-4908-941c-e61ce97b1096'::uuid, 'traffic-rules', 'mock-da-combined-2', 30, 'What happens to the tyres when a car aquaplanes?', 'Apakah yang berlaku pada tayar apabila kereta mengalami gelinciran air?', '["Water separates them from the road","Water increases their tread depth","Water presses them into the road","Water cools the tread evenly"]'::jsonb, '["Air memisahkan tayar daripada jalan","Air menambah kedalaman bunga tayar","Air menekan tayar ke permukaan jalan","Air menyejukkan bunga tayar secara sekata"]'::jsonb, 0, 'Water can build up between the tyres and the road. The tyres lose contact and the car slides.', 'Air boleh terkumpul antara tayar dengan jalan. Tayar kehilangan sentuhan dan kereta tergelincir.', NULL, 'KPP Kelas D Automatik, PDF page 146'),
  ('3ef36186-7df2-4945-a590-21364cf2d54a'::uuid, 'traffic-rules', 'mock-da-combined-2', 31, 'A motorcycle ahead is crossing an exposed bridge in strong crosswinds. What should you allow for?', 'Motosikal di hadapan sedang melalui jambatan terbuka ketika angin lintang bertiup kencang. Apakah yang perlu dijangkakan?', '["It may drift sideways","It may need more room to accelerate","It may pull over under a bridge","It may leave a larger following gap"]'::jsonb, '["Ia mungkin teranjak ke sisi","Ia mungkin memerlukan lebih ruang untuk memecut","Ia mungkin berhenti di bawah jambatan","Ia mungkin menambah jarak mengekori"]'::jsonb, 0, 'Crosswinds can push a motorcycle sideways. Allow for this movement before passing.', 'Angin lintang boleh menolak motosikal ke sisi. Ambil kira pergerakan ini sebelum memotong.', NULL, 'KPP Kelas D Automatik, PDF page 147'),
  ('37795397-e810-4f68-836b-81b06242394a'::uuid, 'traffic-rules', 'mock-da-combined-2', 32, 'Floodwater covers the road and you cannot judge its depth. What should you do?', 'Air banjir menutupi jalan dan anda tidak dapat menganggarkan kedalamannya. Apakah tindakan anda?', '["Follow a taller vehicle through","Take a different route","Try the edge at walking speed","Cross along the centre line"]'::jsonb, '["Ikut kenderaan lebih tinggi meredah air","Gunakan laluan lain","Cuba di tepi pada kelajuan berjalan kaki","Redah air di sepanjang garisan tengah"]'::jsonb, 1, 'If you cannot establish that the water is shallow enough to cross safely, turn back and take another route.', 'Jika anda tidak dapat memastikan air cukup cetek untuk dilalui dengan selamat, patah balik dan ambil laluan lain.', NULL, 'KPP Kelas D Automatik, PDF page 148'),
  ('8e139679-277c-44fb-8128-00cf8031a217'::uuid, 'traffic-rules', 'mock-da-combined-2', 33, 'A driver enters deep floodwater and the engine stops. Which component can admit water directly into the engine?', 'Pemandu meredah banjir dalam dan enjin terhenti. Komponen manakah boleh membenarkan air masuk terus ke dalam enjin?', '["The air intake","The coolant reservoir","The washer fluid tank","The wheel arch"]'::jsonb, '["Salur masuk udara","Takungan cecair penyejuk","Tangki cecair pencuci cermin","Ruang lengkung roda"]'::jsonb, 0, 'Floodwater can enter through the air intake and seriously damage the engine. Avoid driving into deep water.', 'Air banjir boleh masuk melalui salur masuk udara dan menyebabkan kerosakan serius pada enjin. Elakkan meredah air dalam.', NULL, 'KPP Kelas D Automatik, PDF page 148'),
  ('fe4bc5b6-b1dd-4fca-aaab-7332bf8b3c74'::uuid, 'traffic-rules', 'mock-da-combined-2', 34, 'Rain becomes so heavy that you can no longer see far enough to drive. What should you do next?', 'Hujan terlalu lebat sehingga anda tidak dapat melihat cukup jauh untuk memandu. Apakah tindakan seterusnya?', '["Pull off at a suitable stopping place","Keep going behind another vehicle","Slow and stay in the live lane","Continue until visibility improves"]'::jsonb, '["Berhenti di tempat yang sesuai di luar aliran trafik","Teruskan di belakang kenderaan lain","Perlahankan dan kekal di lorong trafik","Teruskan sehingga penglihatan bertambah baik"]'::jsonb, 0, 'When visibility becomes too poor to proceed safely, stop at the nearest suitable place away from moving traffic.', 'Apabila penglihatan terlalu terhad untuk meneruskan perjalanan dengan selamat, berhenti di tempat sesuai yang terdekat, jauh daripada trafik bergerak.', NULL, 'KPP Kelas D Automatik, PDF page 147'),
  ('04febfdc-51d1-402f-bf26-0edd8d7d96a5'::uuid, 'traffic-rules', 'mock-da-combined-2', 35, 'You have been driving on the motorway for about two hours. Where should you take a planned break?', 'Anda telah memandu di lebuh raya selama kira-kira dua jam. Di manakah anda patut berhenti untuk berehat?', '["At a designated rest area","On the emergency shoulder","At the entrance to an exit lane","On a wide part of an on-ramp"]'::jsonb, '["Di kawasan rehat yang disediakan","Di bahu jalan kecemasan","Di pintu masuk lorong susur keluar","Di bahagian lebar susur masuk"]'::jsonb, 0, 'Plan to stop and rest at a designated area on long journeys. The motorway guidance suggests a break after two hours.', 'Rancang untuk berhenti dan berehat di kawasan yang disediakan semasa perjalanan jauh. Panduan lebuh raya mencadangkan rehat selepas dua jam.', NULL, 'KPP Kelas D Automatik, PDF page 140'),
  ('f69b7258-ce6d-4506-8c3f-d235639b0cb9'::uuid, 'traffic-rules', 'mock-da-combined-2', 36, 'Which step may JPJ require of a driver whose licence has been suspended under KEJARA?', 'Apakah langkah yang mungkin diarahkan oleh JPJ kepada pemandu yang lesennya digantung di bawah KEJARA?', '["Apply for a vocational licence","Attend a rehabilitation course","Replace the licence card","Join a vehicle inspection course"]'::jsonb, '["Mohon lesen vokasional","Hadiri kursus pemulihan","Gantikan kad lesen","Sertai kursus pemeriksaan kenderaan"]'::jsonb, 1, 'JPJ may direct a suspended driver to attend a rehabilitation course.', 'JPJ boleh mengarahkan pemandu yang lesennya digantung supaya menghadiri kursus pemulihan.', NULL, 'KPP Kelas D Automatik, PDF page 170'),
  ('51e88c29-b477-422e-9071-ac2cf9fcff76'::uuid, 'traffic-rules', 'mock-da-combined-2', 37, 'Where should a probationary car driver display the P signs?', 'Di manakah pemandu kereta dengan lesen percubaan perlu mempamerkan tanda P?', '["Front windscreen only","Rear windscreen only","Both side windows","Front and rear windscreens"]'::jsonb, '["Cermin hadapan sahaja","Cermin belakang sahaja","Kedua-dua tingkap sisi","Cermin hadapan dan belakang"]'::jsonb, 3, 'Place a P sign at the upper left of each windscreen as shown in the licence guidance.', 'Letakkan tanda P di penjuru kiri atas setiap cermin seperti yang ditunjukkan dalam panduan lesen.', NULL, 'KPP Kelas D Automatik, PDF page 21'),
  ('3c0887f3-8d04-40ed-bed2-376bdc14b03f'::uuid, 'traffic-rules', 'mock-da-combined-2', 38, 'What is the purpose of the probationary driving period?', 'Apakah tujuan tempoh percubaan memandu?', '["To gain experience under licence conditions","To prepare for the first theory class","To qualify for a vocational driving licence","To allow unlicensed practice on roads"]'::jsonb, '["Untuk menimba pengalaman tertakluk pada syarat lesen","Untuk bersedia bagi kelas teori pertama","Untuk melayakkan diri bagi lesen vokasional","Untuk membenarkan latihan tanpa lesen di jalan"]'::jsonb, 0, 'The probationary period gives new drivers time to build skill and experience under specific conditions.', 'Tempoh percubaan memberi masa kepada pemandu baharu untuk membina kemahiran dan pengalaman tertakluk pada syarat tertentu.', NULL, 'KPP Kelas D Automatik, PDF page 20'),
  ('11739bb6-3181-421d-a79d-b2887d6c7b95'::uuid, 'traffic-rules', 'mock-da-combined-2', 39, 'Which skill does the handbook specifically link to the loss of concentration caused by alcohol?', 'Kemahiran manakah yang dikaitkan secara khusus oleh buku panduan dengan kehilangan tumpuan akibat alkohol?', '["Keeping track of dashboard readings","Remembering which route to take","Noticing changes in the car’s engine note","Anticipating changes in traffic"]'::jsonb, '["Memantau bacaan pada papan pemuka","Mengingati laluan yang hendak diambil","Menyedari perubahan bunyi enjin","Menjangka perubahan trafik"]'::jsonb, 0, 'Alcohol impairs concentration and makes it harder to anticipate hazards. Do not drive under its influence.', 'Alkohol menjejaskan tumpuan dan menyukarkan anda menjangka bahaya. Jangan memandu di bawah pengaruh alkohol.', NULL, 'KPP Kelas D Automatik, PDF page 78'),
  ('1ff58818-add3-495e-b8cb-eb10455b12d1'::uuid, 'traffic-rules', 'mock-da-combined-2', 40, 'You cannot attend your practical test appointment. What should you arrange?', 'Anda tidak dapat menghadiri janji temu ujian amali. Apakah yang perlu diatur?', '["An approved change of date","A walk-in at another testing site","A replacement theory appointment","A switch with another candidate"]'::jsonb, '["Pertukaran tarikh yang diluluskan","Hadir tanpa tempahan di pusat lain","Janji temu ujian teori gantian","Pertukaran dengan calon lain"]'::jsonb, 0, 'If you cannot attend on the booked date, apply to change it within the permitted period.', 'Jika anda tidak dapat hadir pada tarikh yang ditempah, mohon untuk memindanya dalam tempoh yang dibenarkan.', NULL, 'KPP Kelas D Automatik, PDF page 16'),
  ('752bd4d2-da60-4d94-bb9f-2b93145756d5'::uuid, 'traffic-rules', 'mock-da-combined-2', 41, 'You are already at the highest speed allowed on this stretch. Traffic in the lane to your right is moving faster. What should determine your speed?', 'Anda sudah memandu pada kelajuan tertinggi yang dibenarkan di jalan ini. Trafik di lorong kanan bergerak lebih laju. Apakah yang patut menentukan kelajuan anda?', '["The speed of the car ahead","The posted limit and road conditions","The average speed of passing traffic","The time left to reach your exit"]'::jsonb, '["Kelajuan kereta di hadapan","Had laju dan keadaan jalan","Purata kelajuan trafik yang memotong","Baki masa untuk sampai ke susur keluar"]'::jsonb, 1, 'Keep a speed that suits the traffic and road conditions while staying within the posted limit.', 'Pilih kelajuan yang sesuai dengan keadaan trafik dan jalan, tanpa melebihi had laju yang dipaparkan.', NULL, 'KPP Kelas D Automatik, PDF page 140'),
  ('ae5dab47-7e67-4f77-bb97-b3fda6c956ce'::uuid, 'traffic-rules', 'mock-da-combined-2', 42, 'You stop at a junction where a building blocks your view. What must you establish before continuing?', 'Anda berhenti di persimpangan apabila sebuah bangunan menghalang pandangan. Apakah yang mesti dipastikan sebelum meneruskan perjalanan?', '["That your indicator has flashed","That the road is clear to enter","That another driver has waved","That the car behind has stopped"]'::jsonb, '["Lampu isyarat anda telah berkelip","Jalan lapang untuk dimasuki","Pemandu lain telah melambai","Kereta di belakang telah berhenti"]'::jsonb, 1, 'At a junction where you must stop, wait until you can establish that it is safe to go. Slowing alone does not establish that.', 'Di persimpangan yang memerlukan anda berhenti, tunggu sehingga anda dapat memastikan keadaan selamat. Memperlahankan kenderaan sahaja tidak mencukupi.', NULL, 'KPP Kelas D Automatik, PDF page 109'),
  ('497da2f2-7ce8-4f63-9283-64be21ba6149'::uuid, 'traffic-rules', 'mock-da-combined-2', 43, 'You see traffic joining from an on-ramp ahead. What should you plan for?', 'Anda melihat trafik memasuki lebuh raya melalui susur masuk di hadapan. Apakah yang perlu dirancang?', '["Space for vehicles to join","A turn into the joining lane","A stop at the end of the ramp","A pass along the hard shoulder"]'::jsonb, '["Ruang untuk kenderaan masuk","Belokan ke lorong susur masuk","Berhenti di hujung susur masuk","Memotong melalui bahu jalan"]'::jsonb, 0, 'Watch for vehicles entering the motorway. Leave enough space to respond to their movements.', 'Perhatikan kenderaan yang memasuki lebuh raya. Tinggalkan ruang yang cukup untuk bertindak terhadap pergerakannya.', NULL, 'KPP Kelas D Automatik, PDF page 140'),
  ('f770549a-d776-49c7-ae01-165036973e46'::uuid, 'traffic-rules', 'mock-da-combined-2', 44, 'Your car breaks down on a motorway. Where should you pull over if you can safely reach it?', 'Kereta anda rosak di lebuh raya. Di manakah anda perlu berhenti jika dapat sampai dengan selamat?', '["At the edge of the driving lane","In the next overtaking lane","At the entrance to an exit ramp","In the emergency lane"]'::jsonb, '["Di tepi lorong pemanduan","Di lorong memotong seterusnya","Di pintu masuk susur keluar","Di lorong kecemasan"]'::jsonb, 3, 'Signal left and move into the emergency lane if you can do so safely. Switch on the hazard lights once stopped.', 'Beri isyarat kiri dan masuk ke lorong kecemasan jika selamat. Hidupkan lampu amaran kecemasan selepas berhenti.', NULL, 'KPP Kelas D Automatik, PDF page 128'),
  ('27adc315-f232-4f61-8dbc-80d27744fba3'::uuid, 'traffic-rules', 'mock-da-combined-2', 45, 'The light is red and there is an empty space between the stop line and the junction. Where do you wait?', 'Lampu merah dan ada ruang kosong antara garisan berhenti dengan persimpangan. Di manakah anda perlu menunggu?', '["Just beyond the stop line","At the edge of the junction","Behind the stop line","In the empty space"]'::jsonb, '["Sejurus selepas garisan berhenti","Di tepi persimpangan","Di belakang garisan berhenti","Di ruang kosong itu"]'::jsonb, 2, 'Stop behind the white line when facing a red signal. Keep the area ahead of it clear.', 'Berhenti di belakang garisan putih apabila lampu merah. Pastikan kawasan di hadapan garisan itu tidak terhalang.', NULL, 'KPP Kelas D Automatik, PDF page 70'),
  ('e0f6cbba-5655-4f72-843f-efcf7648a308'::uuid, 'traffic-rules', 'mock-da-combined-2', 46, 'The light changes to green while a vehicle is still clearing the junction. What should you do?', 'Lampu bertukar hijau ketika sebuah kenderaan masih belum keluar dari persimpangan. Apakah tindakan anda?', '["Proceed when the junction is clear","Proceed along the edge of the lane","Proceed when the driver behind signals","Proceed and let the other vehicle stop"]'::jsonb, '["Teruskan apabila persimpangan lapang","Teruskan di tepi lorong","Teruskan apabila pemandu di belakang memberi isyarat","Teruskan dan biarkan kenderaan lain berhenti"]'::jsonb, 0, 'A green light lets you proceed when it is safe. Check that the junction is clear first.', 'Lampu hijau membenarkan anda meneruskan perjalanan apabila selamat. Pastikan persimpangan lapang dahulu.', NULL, 'KPP Kelas D Automatik, PDF page 70'),
  ('812d6fdf-e9a3-47c9-8bd8-764f36ef55ff'::uuid, 'traffic-rules', 'mock-da-combined-2', 47, 'You want to go straight. The main signal is red and a green arrow points right. What should you do?', 'Anda hendak bergerak lurus. Lampu utama merah dan anak panah hijau menunjuk ke kanan. Apakah tindakan anda?', '["Wait for a straight-ahead signal","Follow right-turn traffic straight","Proceed straight if the road is clear","Move forward into the junction and wait"]'::jsonb, '["Tunggu isyarat untuk bergerak lurus","Ikut trafik belok kanan secara lurus","Teruskan jika laluan lurus lapang","Maju ke dalam simpang dan tunggu"]'::jsonb, 0, 'A green arrow applies to the direction it points. If you are going straight, wait for the signal that applies to you.', 'Anak panah hijau terpakai pada arah yang ditunjukkan. Jika anda hendak terus, tunggu isyarat yang terpakai untuk anda.', NULL, 'KPP Kelas D Automatik, PDF page 70'),
  ('d32f03ef-27a0-4d04-952b-6b9ee6852ffa'::uuid, 'traffic-rules', 'mock-da-combined-2', 48, 'You have priority at a junction. An ambulance approaches with its siren sounding. Who should go first?', 'Anda mempunyai keutamaan di persimpangan. Sebuah ambulans menghampiri dengan siren berbunyi. Siapakah patut bergerak dahulu?', '["The vehicle with the green light","The vehicle already at the line","The vehicle approaching from the right","The ambulance with its siren on"]'::jsonb, '["Kenderaan yang mendapat lampu hijau","Kenderaan yang sudah tiba di garisan","Kenderaan yang menghampiri dari kanan","Ambulans yang membunyikan siren"]'::jsonb, 3, 'Give priority to an ambulance sounding its siren even when you normally have right of way.', 'Beri keutamaan kepada ambulans yang membunyikan siren walaupun anda biasanya mempunyai hak laluan.', NULL, 'KPP Kelas D Automatik, PDF page 89'),
  ('405cb0bb-b17e-48a6-a3d8-a9bdb154a21b'::uuid, 'traffic-rules', 'mock-da-combined-2', 49, 'You are closing on a slow car near the top of a hill. When is it appropriate to consider passing?', 'Anda menghampiri kereta perlahan berhampiran puncak bukit. Bilakah anda boleh mempertimbangkan untuk memotong?', '["While both cars are still climbing","As the car reaches the crest","After the view beyond the crest clears","As soon as the car moves slightly left"]'::jsonb, '["Semasa kedua-dua kereta masih mendaki","Ketika kereta itu tiba di puncak","Selepas pandangan melepasi puncak jelas","Sebaik sahaja kereta itu bergerak sedikit ke kiri"]'::jsonb, 2, 'Avoid overtaking at a hill crest. Wait for a clear view of oncoming traffic and a lawful place to pass.', 'Elakkan memotong di puncak bukit. Tunggu sehingga trafik dari arah bertentangan dapat dilihat dengan jelas dan anda berada di tempat yang membenarkan memotong.', NULL, 'KPP Kelas D Automatik, PDF page 106'),
  ('1790663e-ead7-47ef-a983-56220425238f'::uuid, 'traffic-rules', 'mock-da-combined-2', 50, 'A car ahead slows just before a pedestrian crossing without lights. What should you do?', 'Kereta di hadapan memperlahankan kenderaan sejurus sebelum lintasan pejalan kaki tanpa lampu isyarat. Apakah tindakan anda?', '["Ease off and prepare to stop","Sound the horn and move alongside","Pass if the opposite lane is empty","Maintain speed until you see a person"]'::jsonb, '["Perlahankan kenderaan dan bersedia untuk berhenti","Bunyikan hon dan bergerak ke sisi kereta","Potong jika lorong bertentangan kosong","Kekalkan kelajuan sehingga nampak seseorang"]'::jsonb, 0, 'Slow down at an unsignalised crossing and stop if needed to let pedestrians cross. Do not overtake there.', 'Perlahankan kenderaan di lintasan tanpa lampu isyarat dan berhenti jika perlu untuk memberi laluan. Jangan memotong di lintasan itu.', NULL, 'KPP Kelas D Automatik, PDF page 72'),
  ('1c50fcc5-0a29-4a96-8d38-a5c260323394'::uuid, 'traffic-rules', 'mock-da-combined-2', 51, 'The car behind is following much too closely. Which change gives you more time to slow gently?', 'Kereta di belakang mengekori terlalu rapat. Perubahan manakah memberi anda lebih masa untuk memperlahankan kenderaan secara beransur-ansur?', '["Move closer to the car ahead","Leave more space ahead","Keep the same gap ahead","Speed up to close the gap"]'::jsonb, '["Dekati kereta di hadapan","Tinggalkan lebih ruang di hadapan","Kekalkan jarak yang sama di hadapan","Tambah kelajuan untuk merapatkan jarak"]'::jsonb, 1, 'Use a longer following gap when tailgated. A four-second gap ahead gives you more room to respond without sudden braking.', 'Kekalkan jarak mengekori lebih panjang apabila diekori terlalu rapat. Jarak empat saat memberi lebih ruang untuk bertindak tanpa membrek secara tiba-tiba.', NULL, 'KPP Kelas D Automatik, PDF page 102'),
  ('1842e2d6-4523-4e57-a4e8-a73fdf58b074'::uuid, 'traffic-rules', 'mock-da-combined-2', 52, 'Why should you leave a longer gap when towing a load?', 'Mengapakah anda perlu mengekalkan jarak lebih panjang apabila menarik beban?', '["The extra weight needs more stopping room","The trailer increases your view ahead","The load makes the engine turn faster","The trailer makes the car steer more sharply"]'::jsonb, '["Berat tambahan memerlukan ruang berhenti lebih jauh","Treler meluaskan pandangan ke hadapan","Beban membuat enjin berpusing lebih laju","Treler menyebabkan kereta membelok lebih tajam"]'::jsonb, 0, 'Allow more time and space to stop the combined weight of the car and load.', 'Sediakan lebih masa dan ruang untuk memberhentikan gabungan berat kereta dan beban.', NULL, 'KPP Kelas D Automatik, PDF page 104'),
  ('d2e004a9-79b2-4a4b-9998-2569d7f32417'::uuid, 'traffic-rules', 'mock-da-combined-2', 53, 'Traffic beyond a yellow box has stopped and there is nowhere to clear the box. Where should you wait?', 'Trafik selepas petak kuning telah berhenti dan tiada ruang untuk keluar dari petak. Di manakah anda patut menunggu?', '["Just inside the box","Before the box","Beside the first car inside the box","At the centre of the box"]'::jsonb, '["Sejurus di dalam petak","Sebelum petak","Di sisi kereta pertama di dalam petak","Di tengah petak"]'::jsonb, 1, 'Wait until there is room to cross without stopping in the yellow box and blocking other traffic.', 'Tunggu sehingga ada ruang untuk melintas tanpa berhenti di dalam petak kuning dan menghalang trafik lain.', NULL, 'KPP Kelas D Automatik, PDF page 73'),
  ('df493033-a018-4a2f-b1ce-8eb4dc5dc057'::uuid, 'traffic-rules', 'mock-da-combined-2', 54, 'At roadworks, the controller displays the stop side of a paddle. The temporary lane is empty. What should you do?', 'Di zon kerja jalan, pengawal menunjukkan sisi berhenti pada papan. Lorong sementara lapang. Apakah tindakan anda?', '["Wait for the controller to release you","Follow the last car through","Enter slowly and watch the controller","Move into the lane and wait there"]'::jsonb, '["Tunggu arahan pengawal untuk bergerak","Ikut kereta terakhir yang melalui lorong","Masuk perlahan sambil memerhati pengawal","Masuk ke lorong dan tunggu di situ"]'::jsonb, 0, 'Follow the instructions of the person controlling traffic through the roadworks. Stop when directed.', 'Patuhi arahan petugas yang mengawal trafik di kawasan kerja jalan. Berhenti apabila diarahkan.', NULL, 'KPP Kelas D Automatik, PDF page 69'),
  ('c60b0f91-b3fc-41f6-b7f8-2a344cfaf59a'::uuid, 'traffic-rules', 'mock-da-combined-2', 55, 'A bus-and-taxi lane runs beside a pickup bay for private cars. Where should you stop to collect a passenger?', 'Lorong bas dan teksi bersebelahan petak mengambil penumpang untuk kereta persendirian. Di manakah anda patut berhenti untuk mengambil penumpang?', '["In the bay outside the bus lane","In the bus lane beside the bay","In the traffic lane next to the bay","At the start of the bus lane"]'::jsonb, '["Di petak di luar lorong bas","Di lorong bas di sebelah petak","Di lorong trafik di sebelah petak","Di permulaan lorong bas"]'::jsonb, 0, 'The bus-and-taxi lane is reserved. A private car should use a permitted pickup point outside it.', 'Lorong bas dan teksi dikhaskan untuk pengangkutan awam. Kereta persendirian perlu menggunakan tempat mengambil penumpang yang dibenarkan di luar lorong itu.', NULL, 'KPP Kelas D Automatik, PDF page 72'),
  ('93ed1be1-caa9-4b95-a7da-9814afc01f85'::uuid, 'traffic-rules', 'mock-da-combined-2', 56, 'An oncoming car drifts into your lane. Which early warning can you give while responding safely?', 'Kereta dari arah bertentangan memasuki lorong anda. Apakah amaran awal yang boleh diberikan sambil bertindak dengan selamat?', '["Flash the headlights briefly","Turn on the right indicator","Turn on the left indicator","Switch off the headlights briefly"]'::jsonb, '["Kelipkan lampu hadapan","Hidupkan isyarat kanan","Hidupkan isyarat kiri","Padamkan lampu hadapan seketika"]'::jsonb, 0, 'A brief flash or horn can warn the oncoming driver. Keep control and act quickly to avoid a collision.', 'Kelipan lampu atau bunyi hon yang singkat boleh memberi amaran kepada pemandu dari arah bertentangan. Kekalkan kawalan dan bertindak segera untuk mengelakkan perlanggaran.', NULL, 'KPP Kelas D Automatik, PDF page 107'),
  ('f8359bc2-cd44-4f25-886d-d0c7cebed0df'::uuid, 'safety-principles', 'mock-da-combined-2', 57, 'Which plan is allowed while your driving licence is suspended?', 'Rancangan manakah dibenarkan ketika lesen memandu anda digantung?', '["Ask someone else to drive you","Drive a borrowed car to work","Ride a different vehicle class","Take a short drive for essentials"]'::jsonb, '["Minta orang lain memandu anda","Pandu kereta pinjaman ke tempat kerja","Tunggang kenderaan kelas lain","Pandu sekejap untuk urusan penting"]'::jsonb, 0, 'Suspension prevents the person from driving. Changing vehicles does not remove the restriction.', 'Penggantungan melarang orang itu daripada memandu. Menukar kenderaan tidak menamatkan larangan tersebut.', NULL, 'KPP General, PDF 96'),
  ('e03caac2-59ee-46b1-ba6c-61506ac3a233'::uuid, 'safety-principles', 'mock-da-combined-2', 58, 'What must a former probationary driver repeat after a cancellation ban ends?', 'Apakah yang perlu diulang oleh bekas pemegang lesen percubaan selepas larangan pembatalan tamat?', '["The medical form alone","The licence renewal alone","The training and tests","The probation period alone"]'::jsonb, '["Borang kesihatan sahaja","Pembaharuan lesen sahaja","Latihan dan ujian","Tempoh percubaan sahaja"]'::jsonb, 2, 'The curriculum requires the training and tests again, followed by a new probation period.', 'Kurikulum memerlukan latihan dan ujian semula, diikuti tempoh percubaan yang baharu.', NULL, 'KPP Kelas DA Automatik, PDF 21'),
  ('7124c3d1-4d9b-4165-bd8b-ef98cdecc1e7'::uuid, 'safety-principles', 'mock-da-combined-2', 59, 'What should you look for under the car during a pre-drive walk-around?', 'Apakah yang perlu diperiksa di bawah kereta sebelum memandu?', '["Signs of tread wear","Loose washer nozzles","A blocked air filter","Signs of a leak"]'::jsonb, '["Tanda bunga tayar haus","Muncung pencuci longgar","Penapis udara tersumbat","Tanda kebocoran"]'::jsonb, 3, 'Look underneath to see whether anything is leaking before setting off.', 'Lihat di bawah kereta untuk mengesan sebarang kebocoran sebelum bergerak.', NULL, 'KPP Kelas DA Automatik, PDF 227'),
  ('d356c67d-a7f5-4685-88ca-01f5f13ebb2f'::uuid, 'safety-principles', 'mock-da-combined-2', 60, 'What should you check on the number plates during a walk-around?', 'Apakah yang perlu diperiksa pada plat nombor semasa pemeriksaan keliling kereta?', '["Clean and undamaged","Readable and loosely attached","Secure and covered with dirt","Straight and cracked"]'::jsonb, '["Bersih dan tidak rosak","Boleh dibaca dan longgar","Kukuh dan dilitupi kotoran","Lurus dan retak"]'::jsonb, 0, 'Check that the plates are clean and undamaged.', 'Pastikan plat nombor bersih dan tidak rosak.', NULL, 'KPP Kelas DA Automatik, PDF 226'),
  ('fbd8cbca-47e8-4b35-af79-b67f788eb965'::uuid, 'safety-principles', 'mock-da-combined-2', 61, 'The automatic car has stopped on the marked ramp line and is ready to move off uphill. Which position should you select?', 'Kereta automatik telah berhenti di garisan tanjakan dan sedia bergerak mendaki. Kedudukan manakah patut dipilih?', '["D","N","P","R"]'::jsonb, '["D","N","P","R"]'::jsonb, 0, 'Select D and release the brakes as instructed, then press the accelerator gently to leave the ramp.', 'Pilih D dan lepaskan brek mengikut langkah yang diterangkan, kemudian tekan pemecut perlahan-lahan untuk keluar dari tanjakan.', NULL, 'KPP Kelas DA Automatik, PDF 284'),
  ('f9628299-5954-45ce-880c-c1b4e224d99f'::uuid, 'safety-principles', 'mock-da-combined-2', 62, 'How do you start reversing slowly in the automatic car after selecting R and checking it is safe?', 'Bagaimanakah anda mula mengundur perlahan dalam kereta automatik selepas memilih R dan memastikan keadaan selamat?', '["Tap the accelerator twice","Release the foot brake quickly","Ease off the foot brake","Hold the brake and add throttle"]'::jsonb, '["Tekan pemecut dua kali","Lepaskan pedal brek dengan cepat","Lepaskan pedal brek perlahan-lahan","Tahan brek sambil menekan pemecut"]'::jsonb, 2, 'With the parking brake released, ease off the foot brake to start moving without using the accelerator.', 'Selepas melepaskan brek tangan, lepaskan pedal brek perlahan-lahan untuk bergerak tanpa menekan pemecut.', NULL, 'KPP Kelas DA Automatik, PDF 233'),
  ('03de4ae6-ce8d-41e3-a6d9-67ece1d93960'::uuid, 'safety-principles', 'mock-da-combined-2', 63, 'Which finding means a wiper blade may leave water on the windscreen?', 'Penemuan manakah menunjukkan bilah pengelap mungkin meninggalkan air pada cermin?', '["The rubber bends easily","The edge has small splits","The edge lies flat on the glass","The blade follows the glass curve"]'::jsonb, '["Getah mudah melentur","Tepi bilah ada rekahan kecil","Tepi bilah rata pada cermin","Bilah mengikut lengkung cermin"]'::jsonb, 1, 'Hardened, cracked or torn blade rubber may leave water behind or scratch the glass.', 'Getah bilah yang keras, retak atau koyak mungkin meninggalkan air atau mencalarkan cermin.', NULL, 'KPP Kelas DA Automatik, PDF 225'),
  ('7ca0a06f-5309-451e-8f59-97317dd580b9'::uuid, 'safety-principles', 'mock-da-combined-2', 64, 'Where does the curriculum say to look for the car manufacturer’s recommended tyre inflation?', 'Di manakah kurikulum menyatakan anda boleh melihat cadangan pengeluar tentang angin tayar kereta?', '["On the tyre tread label","On the wheel nut cap","On the driver’s door label","On the windscreen sticker"]'::jsonb, '["Pada label bunga tayar","Pada penutup nat roda","Pada label pintu pemandu","Pada pelekat cermin hadapan"]'::jsonb, 2, 'Look for the manufacturer’s tyre pressure label on the side of the driver’s door.', 'Cari label tekanan angin tayar pengeluar di bahagian tepi pintu pemandu.', NULL, 'KPP Kelas DA Automatik, PDF 224'),
  ('eef26162-eb9d-4e33-a343-c9f994d91ac9'::uuid, 'safety-principles', 'mock-da-combined-2', 65, 'Which tyre fails the visual condition check even if its tread is deep?', 'Tayar manakah gagal pemeriksaan fizikal walaupun bunganya masih dalam?', '["A tyre with even wear","A tyre with deep grooves","A tyre with mould marks","A tyre with a bulge"]'::jsonb, '["Tayar yang haus sekata","Tayar dengan alur dalam","Tayar dengan kesan acuan","Tayar yang menggelembung"]'::jsonb, 3, 'During the visual inspection, check that tyres are free from bulges, cracks and tears.', 'Pastikan tayar tidak menggelembung, merekah atau koyak semasa pemeriksaan.', NULL, 'KPP Kelas DA Automatik, PDF 224'),
  ('1c31a1ea-7733-4884-9356-c01d5f552459'::uuid, 'safety-principles', 'mock-da-combined-2', 66, 'A workshop finds that the wheel angles are out of specification. Which service addresses that problem?', 'Bengkel mendapati sudut roda tidak mengikut spesifikasi. Servis manakah membetulkan masalah itu?', '["Wheel alignment","Wheel balancing","Brake adjustment","Wheel bearing service"]'::jsonb, '["Penjajaran roda","Pengimbangan roda","Pelarasan brek","Servis galas roda"]'::jsonb, 0, 'Correct wheel alignment helps the tyre tread wear evenly. The book describes wheel balancing separately as a way to reduce vibration.', 'Penjajaran roda yang betul membantu bunga tayar haus secara sekata. Pengimbangan roda pula membantu mengurangkan gegaran.', NULL, 'KPP Kelas DA Automatik, PDF 224'),
  ('51cfa566-8ede-461e-83ed-af739a45fdab'::uuid, 'safety-principles', 'mock-da-combined-2', 67, 'Where should the engine oil level sit on the dipstick?', 'Di manakah paras minyak enjin sepatutnya berada pada batang penyukat?', '["Below the lower mark","Between the two marks","Above the upper mark","Exactly on the lower mark"]'::jsonb, '["Di bawah tanda bawah","Antara kedua-dua tanda","Di atas tanda atas","Tepat pada tanda bawah"]'::jsonb, 1, 'The book says to check that the level is between the minimum and maximum marks.', 'Buku menyatakan paras minyak perlu berada antara tanda minimum dan maksimum.', NULL, 'KPP Kelas DA Automatik, PDF 228'),
  ('0d43339b-a8a1-4533-86a0-b423a42c52f5'::uuid, 'safety-principles', 'mock-da-combined-2', 68, 'The washer reservoir is accessible under the bonnet. Which check can you do there?', 'Takungan pencuci boleh dicapai di bawah bonet. Pemeriksaan manakah boleh dibuat di situ?', '["Check whether fluid needs topping up","Check whether fluid reaches the glass","Check how far the fluid sprays","Check which spray jet is blocked"]'::jsonb, '["Semak sama ada cecair perlu ditambah","Semak sama ada cecair sampai ke kaca","Semak sejauh mana cecair menyembur","Semak muncung semburan yang tersumbat"]'::jsonb, 0, 'Check that the washer reservoir contains enough fluid.', 'Pastikan cecair dalam tangki pencuci cermin mencukupi.', NULL, 'KPP Kelas DA Automatik, PDF 229'),
  ('04af2388-0993-4fb9-bb50-67f550a1aca6'::uuid, 'safety-principles', 'mock-da-combined-2', 69, 'Which hose condition should you report during a check under the bonnet?', 'Keadaan hos manakah yang perlu dilaporkan semasa pemeriksaan di bawah bonet?', '["A smooth curved route","An intact hose clamp","A dry outer surface","A crack or a bulge"]'::jsonb, '["Laluan melengkung licin","Pengapit hos masih elok","Permukaan luar kering","Rekah atau bengkak"]'::jsonb, 3, 'Check that hoses have no leaks, cracks or swelling.', 'Pastikan hos tidak bocor, merekah atau mengembang.', NULL, 'KPP Kelas DA Automatik, PDF 230'),
  ('fc34ce83-dc46-4eb1-990e-51b9d3ab78c2'::uuid, 'safety-principles', 'mock-da-combined-2', 70, 'When replacing a tyre, which tool loosens the nuts before you remove the wheel?', 'Ketika mengganti tayar, alat manakah melonggarkan nat sebelum roda ditanggalkan?', '["A wheel brace","A tyre lever","A pressure gauge","A tow hook"]'::jsonb, '["Sepana roda","Tuil tayar","Tolok tekanan","Cangkuk tunda"]'::jsonb, 0, 'The book includes a wheel-nut wrench among the emergency tools to check in the boot.', 'Buku menyenaraikan pembuka nat roda antara peralatan kecemasan yang perlu diperiksa dalam but.', NULL, 'KPP Kelas DA Automatik, PDF 227')
ON CONFLICT (set_id, order_index) DO UPDATE SET
  category = EXCLUDED.category,
  question_en = EXCLUDED.question_en,
  question_ms = EXCLUDED.question_ms,
  options_en = EXCLUDED.options_en,
  options_ms = EXCLUDED.options_ms,
  correct_index = EXCLUDED.correct_index,
  explanation_en = EXCLUDED.explanation_en,
  explanation_ms = EXCLUDED.explanation_ms,
  image_url = EXCLUDED.image_url,
  source_url = EXCLUDED.source_url;

-- ─── Update Secure Practice View to Include All Practice Sets (quiz-*) ─────
CREATE OR REPLACE VIEW public.kpp_practice_questions
WITH (security_invoker = false, security_barrier = true)
AS
  SELECT
    id,
    category,
    set_id,
    order_index,
    question_en,
    question_ms,
    options_en,
    options_ms,
    correct_index,
    explanation_en,
    explanation_ms,
    image_url,
    source_url,
    created_at
  FROM public.kpp_questions
  WHERE set_id = 'quiz-pool' OR set_id LIKE 'quiz-%';

GRANT SELECT ON public.kpp_practice_questions TO authenticated, anon;

-- ─── Update Authoritative Score Recompute Trigger for New Set IDs ─────────
CREATE OR REPLACE FUNCTION public.recompute_exam_score()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_score integer := 0;
  v_total integer;
  v_q_id_text text;
  v_sel_idx_text text;
  v_q_uuid uuid;
  v_sel_idx integer;
  v_correct integer;
  v_set text;
  v_seen uuid[] := ARRAY[]::uuid[];
BEGIN
  IF NEW.answers IS NULL OR jsonb_typeof(NEW.answers) <> 'object' THEN
    RAISE EXCEPTION 'Answers must be a JSON object' USING ERRCODE = '22023';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'Cannot modify result owner' USING ERRCODE = '42501';
  END IF;

  IF TG_TABLE_NAME = 'mock_test_results' THEN
    IF NEW.set_id IS NULL OR NEW.set_id NOT IN (
      'mock-1', 'mock-2', 'mock-3',
      'mock-da-combined-1', 'mock-da-combined-2', 'mock-d-combined-1', 'mock-d-combined-2',
      'mock-da-1', 'mock-da-2', 'mock-da-3', 'mock-da-4', 'mock-da-5', 'mock-da-6',
      'mock-d-1', 'mock-d-2', 'mock-d-3', 'mock-d-4', 'mock-d-5', 'mock-d-6'
    ) THEN
      RAISE EXCEPTION 'Invalid mock set_id' USING ERRCODE = '22023';
    END IF;
    SELECT count(*) INTO v_total FROM public.kpp_questions WHERE set_id = NEW.set_id;
    IF v_total = 0 THEN
      RAISE EXCEPTION 'Empty mock set' USING ERRCODE = '22023';
    END IF;
  ELSIF TG_TABLE_NAME = 'quiz_results' THEN
    v_total := cardinality(NEW.question_ids);
    IF v_total IS NULL OR v_total = 0 OR v_total <> (
      SELECT count(DISTINCT id) FROM unnest(NEW.question_ids) AS selection(id)
    ) THEN
      RAISE EXCEPTION 'Quiz selection must be nonempty and distinct' USING ERRCODE = '22023';
    END IF;
    IF v_total <> (
      SELECT count(*) FROM public.kpp_questions
      WHERE id = ANY(NEW.question_ids) AND (set_id = 'quiz-pool' OR set_id LIKE 'quiz-%')
    ) THEN
      RAISE EXCEPTION 'Quiz selection must belong to the practice pool' USING ERRCODE = '22023';
    END IF;
  ELSE
    RAISE EXCEPTION 'Unsupported grading table' USING ERRCODE = '22023';
  END IF;

  FOR v_q_id_text, v_sel_idx_text IN SELECT key, value FROM jsonb_each_text(NEW.answers) LOOP
    BEGIN
      v_q_uuid := v_q_id_text::uuid;
      v_sel_idx := v_sel_idx_text::integer;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'Malformed question UUID or answer index' USING ERRCODE = '22023';
    END;
    IF v_q_uuid = ANY(v_seen) THEN
      RAISE EXCEPTION 'Duplicate parsed question UUID' USING ERRCODE = '22023';
    END IF;
    v_seen := array_append(v_seen, v_q_uuid);
    IF v_sel_idx IS NULL OR v_sel_idx < 0 OR v_sel_idx > 3 THEN
      RAISE EXCEPTION 'Impossible answer option index' USING ERRCODE = '22023';
    END IF;
    SELECT correct_index, set_id INTO v_correct, v_set
    FROM public.kpp_questions WHERE id = v_q_uuid;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Unknown question ID' USING ERRCODE = '22023';
    END IF;
    IF TG_TABLE_NAME = 'mock_test_results' THEN
      IF v_set <> NEW.set_id THEN
        RAISE EXCEPTION 'Foreign-set answer' USING ERRCODE = '22023';
      END IF;
    ELSIF NOT (v_q_uuid = ANY(NEW.question_ids)) THEN
      RAISE EXCEPTION 'Undeclared quiz answer' USING ERRCODE = '22023';
    END IF;
    IF v_sel_idx = v_correct THEN
      v_score := v_score + 1;
    END IF;
  END LOOP;

  NEW.total_questions := v_total;
  NEW.score := v_score;
  NEW.percentage := round(100 * v_score::numeric / v_total, 2);
  IF TG_TABLE_NAME = 'mock_test_results' THEN
    NEW.passed := v_score >= CASE WHEN NEW.set_id LIKE 'mock-%-combined-%' THEN 56 ELSE 42 END;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.recompute_exam_score() FROM PUBLIC, anon, authenticated;
